import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, doublePrecision, index } from 'drizzle-orm/pg-core'

/**
 * `finance` is BK Dash's BC8 Finance schema.
 *
 * All TS-owned merchant aggregates — no Go writes here. The Go-side
 * sync engine emits provider-reported amounts (gateway fees inline in
 * OrderTransaction, etc.); Finance owns the merchant-side
 * configuration that turns those amounts into profit margins.
 *
 * Tables:
 *   - `taxes`               — Store-scoped, time-effective tax regime
 *   - `fees_configuration`  — Store-scoped header + typed sub-fee
 *                             jsonb arrays (gateway / checkout / shipping)
 *   - `operational_costs`   — merchant cost ledger w/ status overrides
 *   - `warranty_reserves`   — % of revenue reserved per Store (time-effective)
 *   - `fx_rates`            — append-only, query by (from, to, startDate ≤ at)
 */
export const financeSchema = pgSchema('finance')

/**
 * `taxes` — one row per (storeId, startDate slice). `endDate` nullable
 * means "still effective". Queries pick the row matching
 * `startDate <= date AND (endDate IS NULL OR endDate > date)`.
 */
export const taxes = financeSchema.table(
	'taxes',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// TaxType enum (NONE | PRESUMED_PROFIT | REAL_PROFIT).
		type: text('type').notNull(),
		// TaxDeductionType enum (NONE | PRODUCT_COST | PRODUCT_COST_AND_MARKETING).
		deductionType: text('deduction_type').notNull(),

		// Effective tax rate as a fraction 0..1 (e.g. 0.085 = 8.5%). Stored
		// as double precision because tax calculations vary in precision
		// per jurisdiction and a fixed-point representation would force
		// us to pick a unit per market.
		rate: doublePrecision('rate').notNull(),

		// Spec §4 BC8 `Taxes` aggregate: per-Store profit multiplier
		// applied to revenue tax (e.g. 1.0 = neutral, 1.15 = 15% safety
		// buffer). Stored alongside `rate` to keep T25 reads to a single
		// SELECT. Default 1.0 = no multiplier so historical rows backfill
		// to a neutral value.
		revenueTaxMultiplier: doublePrecision('revenue_tax_multiplier').notNull().default(1.0),

		// Spec §4 BC8 + T25: per-platform marketing-tax overrides keyed by
		// MarketingPlatform (META | GOOGLE_ADS | TIKTOK). Empty map = no
		// per-platform overrides — fall back to `rate`. JSONB shape is
		// `Partial<Record<MarketingPlatform, number>>` per spec line 836.
		marketingTaxRatePerPlatform: jsonb('marketing_tax_rate_per_platform').notNull().default({}),

		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('taxes_store_id_idx').on(t.storeId),
		// Time-effective lookup index.
		storeStartDateIdx: index('taxes_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `fees_configuration` — single header row per Store with three typed
 * jsonb arrays of sub-fees:
 *
 *   - gateway_fees: GatewayFee[]
 *       { platform: PaymentGateway, paymentMethod: PaymentMethod,
 *         percentage: number, fixed: { amountCents, currency }[] }
 *   - checkout_fees: CheckoutFee[]
 *       { platform: CheckoutPlatform, rate: number }
 *   - shipping_fees: ShippingFee[]
 *       { type: ShippingCostType, value: ShippingCostValue }
 *
 * jsonb chosen over separate child tables because (a) read shape is
 * always "the full configuration for one Store", and (b) the
 * per-platform sub-shapes vary (e.g. ShippingCostValue is a 4-variant
 * discriminated union from spec — modeling it relationally would
 * require multiple child tables for a write that happens N×/year.)
 */
export const feesConfiguration = financeSchema.table(
	'fees_configuration',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		gatewayFees: jsonb('gateway_fees').notNull(),
		checkoutFees: jsonb('checkout_fees').notNull(),
		// Singular: the spec's FeesConfiguration carries one shipping
		// fee per row (matches the entity's `shippingFee` field).
		// Stored as a nullable jsonb so the "no shipping fee
		// configured yet" state encodes as JSON null.
		shippingFee: jsonb('shipping_fee'),

		// Spec §4 BC8 + C40: time-effective semantics matching `taxes`.
		// Multiple rows per Store; the active one has `endDate IS NULL`.
		// C40 closes the previous row's endDate and inserts a new one.
		// Default startDate = row insertion time (safe for historical
		// single-row data migrated forward — it becomes the first slice).
		startDate: timestamp('start_date', { withTimezone: true }).notNull().defaultNow(),
		endDate: timestamp('end_date', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Time-effective lookup: (storeId, startDate) replaces the previous
		// `(storeId) UNIQUE` constraint. Active-row lookup uses
		// `WHERE storeId = ? AND endDate IS NULL`.
		storeStartDateIdx: index('fees_configuration_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `operational_costs` — merchant cost ledger. Each row is one cost
 * line item with its own recurrence pattern. Occurrences are derived
 * at runtime (never stored); `status_overrides` is a jsonb array of
 * { occurrenceDate, status } holding only the per-occurrence deviations
 * from the default status (e.g. mark October's RENT as CANCELLED).
 */
export const operationalCosts = financeSchema.table(
	'operational_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Free-form merchant description ("November salary advance",
		// "Adobe CC", …). category is the enum classification.
		description: text('description').notNull(),
		category: text('category').notNull(),

		// OperationalCostFlow enum (CREDIT = money in | DEBIT = money out).
		// Entity always supplies it; migration backfills existing rows to DEBIT.
		flow: text('flow').notNull(),

		// OperationalCostRecurrency enum (ONCE | DAILY | WEEKLY | … |
		// YEARLY | NONE).
		recurrency: text('recurrency').notNull(),

		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// First occurrence date. For recurring costs the date implies
		// each future occurrence (e.g. MONTHLY starting Jan 15 →
		// Feb 15, Mar 15, …).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		// Optional terminator for recurring costs ("stop billing this
		// after X"); nullable = still recurring.
		endDate: timestamp('end_date', { withTimezone: true }),

		// jsonb array of { occurrenceDate, status } — only the per-occurrence
		// deviations from the default status, matching the OperationalCost
		// entity's statusOverrides shape verbatim. Status uses
		// OperationalCostPaymentStatus (PAID | UNPAID | OVERDUE | CANCELLED).
		statusOverrides: jsonb('status_overrides').notNull(),

		// Soft-delete timestamp. T27 ListOperationalCosts filters out
		// rows where this is non-null — the entity uses `deletedAt`
		// alone as the "is this row visible?" signal (no separate
		// `active` flag).
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('operational_costs_store_id_idx').on(t.storeId),
		categoryIdx: index('operational_costs_category_idx').on(t.category),
		// Date scans for analytics rollups.
		startDateIdx: index('operational_costs_start_date_idx').on(t.startDate),
	}),
)

/**
 * `warranty_reserves` — per-Store percentage of revenue reserved for
 * warranty claims. Time-effective (multiple rows per Store; queries
 * pick the row whose start_date ≤ now AND (end_date IS NULL OR
 * end_date > now)).
 */
export const warrantyReserves = financeSchema.table(
	'warranty_reserves',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Fraction 0..1 of revenue to reserve. Same precision rationale as
		// `taxes.rate`.
		rate: doublePrecision('rate').notNull(),

		// Spec § BC8 BC and the WarrantyReserve entity name the
		// time-effective window `effectiveFrom`/`effectiveTo` to
		// distinguish it from the soft-delete `deletedAt` timestamp.
		// (Taxes uses `start_date`/`end_date` because it has no soft
		// delete; reusing the same names here would conflate the two
		// audit dimensions.)
		effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
		effectiveTo: timestamp('effective_to', { withTimezone: true }),
		// Soft-delete timestamp. listByStoreId filters out rows where
		// this is non-null; the supersession path uses effectiveTo
		// (not deletedAt) so historical analytics keep the row
		// visible.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeEffectiveFromIdx: index('warranty_reserves_store_effective_from_idx').on(t.storeId, t.effectiveFrom),
	}),
)

/**
 * `fx_rates` — append-only currency conversion source of truth.
 *
 * Hourly CaptureFxRates cron emits rows from CURRENCY_API; merchants
 * may insert MANUAL overrides; providers may report rates inline
 * (PROVIDER_REPORTED, captured during transaction ingest).
 *
 * Queried with the canonical pattern:
 *   SELECT * FROM fx_rates
 *    WHERE from_currency = ? AND to_currency = ?
 *      AND start_date <= ?
 *    ORDER BY start_date DESC LIMIT 1
 *
 * The composite index on (from_currency, to_currency, start_date DESC)
 * makes that query a single-page seek.
 */
export const fxRates = financeSchema.table(
	'fx_rates',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		fromCurrency: text('from_currency').notNull(),
		toCurrency: text('to_currency').notNull(),

		// Conversion rate: 1 unit of fromCurrency = `rate` units of
		// toCurrency. Stored as `text` to preserve provider-side
		// decimal precision verbatim (e.g. '5.10' stays '5.10', not
		// coerced to 5.1). Queries never sort or aggregate on rate
		// (ORDER BY runs on start_date) so the lack of numeric
		// semantics is fine. The FxRate entity carries `rate: string`
		// matching this column.
		rate: text('rate').notNull(),

		// FxRateSource enum (CURRENCY_API | MANUAL | PROVIDER_REPORTED).
		source: text('source').notNull(),

		// When this rate became effective. Multiple rows may exist for
		// the same currency pair; queries pick the most recent ≤ desired
		// timestamp.
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		// Canonical query index — covers the "find rate at time T" path.
		pairStartDateIdx: index('fx_rates_pair_start_date_idx').on(t.fromCurrency, t.toCurrency, t.startDate),
		sourceIdx: index('fx_rates_source_idx').on(t.source),
	}),
)

import { pgSchema, uuid, text, timestamp, boolean, integer, bigint, jsonb, index, uniqueIndex, primaryKey } from 'drizzle-orm/pg-core'

/**
 * `sales` is BK Dash's BC4 Sales schema.
 *
 * The canonical `orders` table is **Go-owned**: go-worker writes via
 * `UPSERT … ON CONFLICT (platform, external_id) DO UPDATE` after every
 * webhook + backfill page. TS consumers (Sales, Notifications,
 * Analytics) only read.
 *
 * Merchant edits land in the separate `order_overrides` aggregate
 * (TS-owned write-side, in iter 42a-ii) which joins on `order_id` at
 * query time — keeping provider data immutable in `orders` while still
 * letting merchants correct totals/method/etc. without rewriting source.
 */
export const salesSchema = pgSchema('sales')

export const orders = salesSchema.table(
	'orders',
	{
		// Deterministic UUIDv5 derived from (platform, external_id) so both
		// go-worker and the TS API resolve the same internal id without a
		// database lookup. The namespace constant lives in
		// packages/api/{go,typescript}/core/objects/ and stays byte-for-byte
		// identical across services.
		id: uuid('id').primaryKey(),

		// Tenant scoping. storeId is the BK Dash workspace; storeIntegrationId
		// pins the provider connection that produced the order; the
		// `storeIntegrationExternalId` denormalizes the provider-side handle
		// (e.g. shop domain) so consumers can resolve without a join.
		storeId: uuid('store_id').notNull(),
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		// Provider identity.
		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),
		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		// Customer + shipping snapshots (jsonb because shapes vary per
		// provider and BK Dash doesn't normalize address into columns).
		description: text('description'),
		customerEmail: text('customer_email'),
		customerName: text('customer_name'),
		customerPhone: text('customer_phone'),
		shippingAddress: jsonb('shipping_address'),

		// Monetary totals — bigint(cents) + ISO-4217 currency. Native +
		// presentment + settlement preserved separately so FX is applied at
		// query time in the consumer's reportingCurrency.
		subtotalCents: bigint('subtotal_cents', { mode: 'bigint' }).notNull(),
		discountTotalCents: bigint('discount_total_cents', { mode: 'bigint' }).notNull(),
		shippingTotalCents: bigint('shipping_total_cents', { mode: 'bigint' }).notNull(),
		taxTotalCents: bigint('tax_total_cents', { mode: 'bigint' }).notNull(),
		totalCents: bigint('total_cents', { mode: 'bigint' }).notNull(),
		totalCurrency: text('total_currency').notNull(),

		presentmentTotalCents: bigint('presentment_total_cents', { mode: 'bigint' }),
		presentmentCurrency: text('presentment_currency'),
		settlementTotalCents: bigint('settlement_total_cents', { mode: 'bigint' }),
		settlementCurrency: text('settlement_currency'),

		// Payment classification.
		paymentStatus: text('payment_status').notNull(),
		paymentMethod: text('payment_method').notNull(),
		paymentGateway: text('payment_gateway').notNull(),

		// Line items + transactions stored as jsonb arrays. Indexed for
		// per-aggregate reads (a query asking for one order returns the
		// full document in one round-trip).
		lines: jsonb('lines').notNull(),
		transactions: jsonb('transactions').notNull(),

		// Cart linkage + attribution.
		cartToken: text('cart_token'),
		utm: jsonb('utm'),

		// Lifecycle flags.
		isDraft: boolean('is_draft').notNull().default(false),
		isManual: boolean('is_manual').notNull().default(false),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Provider uniqueness. The UPSERT discriminator. Drives the
		// `is_new = (xmax = 0)` first-write detection on RETURNING.
		platformExternalIdUnq: uniqueIndex('orders_platform_external_id_unq').on(t.platform, t.externalId),
		// Tenant-scoped reads — dashboards filter by store first, then date.
		storeIdx: index('orders_store_id_idx').on(t.storeId),
		// Per-integration drilldowns + reintegration sweeps.
		storeIntegrationIdx: index('orders_store_integration_id_idx').on(t.storeIntegrationId),
		// Time-series reads order DESC for "latest orders" lists.
		externalCreatedAtIdx: index('orders_external_created_at_idx').on(t.externalCreatedAt),
	}),
)

/**
 * `carts` is the Go-owned Cart projection. Lifecycle: created on first
 * checkout-start pixel event → abandoned (idle past provider's window)
 * → recovered (linked to a real Order via `linked_order_id` after
 * CHECKOUT_COMPLETED + provider order match).
 *
 * Same UPSERT discriminator pattern as `orders`: deterministic UUIDv5
 * PK + unique (platform, external_cart_id) for first-insert detection.
 */
export const carts = salesSchema.table(
	'carts',
	{
		id: uuid('id').primaryKey(),

		storeId: uuid('store_id').notNull(),
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalCartId: text('external_cart_id').notNull(),

		// Customer contact at cart time. Often partial — providers stream
		// these in over multiple pixel events as the user types.
		customerEmail: text('customer_email'),
		customerPhone: text('customer_phone'),

		// Item-level snapshot (jsonb array of CartLine: productExternalId,
		// variantExternalId, quantity, unitPriceCents/currency).
		lines: jsonb('lines').notNull(),

		// Subtotal at cart time. May lag the resolved Order's totalCents
		// (Cart doesn't carry tax/shipping until checkout).
		totalCents: bigint('total_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// Lifecycle.
		abandonedAt: timestamp('abandoned_at', { withTimezone: true }),
		recoveredAt: timestamp('recovered_at', { withTimezone: true }),
		// When this cart resolved to an Order. References `orders.id` but
		// the FK is intentionally omitted — go-worker may write the cart
		// row before the order is upserted in concurrent flows.
		linkedOrderId: uuid('linked_order_id'),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalCartIdUnq: uniqueIndex('carts_platform_external_cart_id_unq').on(t.platform, t.externalCartId),
		storeIdx: index('carts_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('carts_store_integration_id_idx').on(t.storeIntegrationId),
		// Partial-index pattern — Drizzle doesn't yet have first-class
		// WHERE clause support in pg-core indexes, so we ship a plain
		// index on abandonedAt. The "is_abandoned" predicate is computed
		// at query time as `abandoned_at IS NOT NULL AND recovered_at IS NULL`.
		abandonedAtIdx: index('carts_abandoned_at_idx').on(t.abandonedAt),
	}),
)

/**
 * `order_overrides` is the merchant-editable per-Order patch aggregate.
 * Composite primary key `(order_id, store_integration_external_id)`
 * keeps overrides scoped per integration (a merchant editing override
 * on one StoreIntegration doesn't bleed across re-connections).
 *
 * Every field except the PK is OPTIONAL — merchants override one field
 * at a time. At read-time, query-side use cases COALESCE
 * `order_overrides.<field>` over `orders.<field>` to surface the
 * merchant's view of the order.
 *
 * Owned by the TS Sales BC (not Go) — the only writer is the
 * UpdateOrderOverride command.
 */
export const orderOverrides = salesSchema.table(
	'order_overrides',
	{
		orderId: uuid('order_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		// Override fields — all optional; the consumer COALESCEs over `orders.*`.
		paymentMethod: text('payment_method'),
		paymentStatus: text('payment_status'),

		revenueAmountCents: bigint('revenue_amount_cents', { mode: 'bigint' }),
		revenueCurrency: text('revenue_currency'),

		shippingAmountCents: bigint('shipping_amount_cents', { mode: 'bigint' }),
		shippingCurrency: text('shipping_currency'),

		feesAmountCents: bigint('fees_amount_cents', { mode: 'bigint' }),
		feesCurrency: text('fees_currency'),

		taxesAmountCents: bigint('taxes_amount_cents', { mode: 'bigint' }),
		taxesCurrency: text('taxes_currency'),

		// Per-line product cost overrides: jsonb array of
		// { lineId, costAmountCents, costCurrency } — flattened from spec's
		// `productCostByLine` so consumers don't unwrap a nested object per
		// element. nullable; rare for merchants to override at line level.
		productCostByLine: jsonb('product_cost_by_line'),

		// Audit.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		pk: primaryKey({ columns: [t.orderId, t.storeIntegrationExternalId] }),
		orderIdx: index('order_overrides_order_id_idx').on(t.orderId),
	}),
)

namespace TemplateContracts;

@doc("Component of a payment-gateway fee: VARIABLE is the percentage-of-amount part, FIXED is the flat per-transaction part.")
enum GatewayFeeKind {
  VARIABLE: "VARIABLE",
  FIXED: "FIXED",
}

namespace TemplateContracts;

@doc("Category of cost in a dashboard cost breakdown. Anchored on the keys of OrderMetrics costs/fees/taxes plus operational costs.")
enum CostKind {
  MARKETING: "MARKETING",
  PRODUCT: "PRODUCT",
  SHIPPING: "SHIPPING",
  FEES: "FEES",
  REFUND: "REFUND",
  CHARGEBACK: "CHARGEBACK",
  TAXES: "TAXES",
  OPERATIONAL: "OPERATIONAL",
}

namespace TemplateContracts;

@doc("Brazilian tax regime selection on a Store's Taxes aggregate; informs profit-margin calculation. NONE disables tax deduction entirely.")
enum TaxType {
  NONE: "NONE",
  PRESUMED_PROFIT: "PRESUMED_PROFIT",
  REAL_PROFIT: "REAL_PROFIT",
}

namespace TemplateContracts;

@doc("Strategy a Store uses to charge shipping back to revenue. Discriminator for the ShippingCostValue union (modeled inline on the FeesConfiguration aggregate; not surfaced as a standalone wire field yet).")
enum ShippingCostType {
  NONE: "NONE",
  PAID_BY_CUSTOMER: "PAID_BY_CUSTOMER",
  AVERAGE_PER_ORDER: "AVERAGE_PER_ORDER",
  AVERAGE_PER_ITEM: "AVERAGE_PER_ITEM",
}

namespace TemplateContracts;

@doc("Cadence at which an OperationalCost recurs. ONCE = single occurrence (different from NONE which means \"no recurrence semantics applicable\").")
enum OperationalCostRecurrency {
  ONCE: "ONCE",
  DAILY: "DAILY",
  WEEKLY: "WEEKLY",
  MONTHLY: "MONTHLY",
  BIMESTER: "BIMESTER",
  TRIMESTER: "TRIMESTER",
  SEMESTER: "SEMESTER",
  YEARLY: "YEARLY",
  NONE: "NONE",
}

namespace TemplateContracts;

@doc("Which cost categories are deducted from revenue when computing taxable income. Paired with TaxType to derive the per-order tax obligation.")
enum TaxDeductionType {
  NONE: "NONE",
  PRODUCT_COST: "PRODUCT_COST",
  PRODUCT_COST_AND_MARKETING: "PRODUCT_COST_AND_MARKETING",
}

import "./_base.tsp";

namespace TemplateContracts;

@doc("Published by TS Finance after `UpdateFeesConfiguration` (C40) inserts a new time-effective FeesConfiguration row covering gateway fees per (platform × payment method), checkout fees per checkout platform, and the shipping fee block. Analytics consumes to recompute profit margin from `effectiveAt` forward.")
model FeesConfigurationUpdatedEvent extends IntegrationEvent {
  name: "integration.shared.finance.fees_configuration_updated";

  @doc("Owning Store.")
  storeId: string;

  @doc("FeesConfiguration aggregate id (the newly inserted row). Mirrors entityId.")
  feesConfigurationId: string;

  @doc("RFC3339 instant the new fees configuration becomes effective.")
  @encode("rfc3339", string)
  effectiveAt: utcDateTime;
}

import "./_base.tsp";

namespace TemplateContracts;

@doc("Published by TS Finance after `UpdateTaxes` (C39) inserts a new time-effective Taxes row (the previous row's endDate becomes the new row's startDate). Analytics consumes to recompute profit margin from `effectiveAt` forward; queries that fall in the prior window remain pinned to the old configuration.")
model TaxesUpdatedEvent extends IntegrationEvent {
  name: "integration.shared.finance.taxes_updated";

  @doc("Owning Store.")
  storeId: string;

  @doc("Taxes aggregate id (the newly inserted row). Mirrors entityId.")
  taxesId: string;

  @doc("RFC3339 instant the new tax configuration becomes effective. Analytics rolls forward cache invalidation from here.")
  @encode("rfc3339", string)
  effectiveAt: utcDateTime;
}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
