import { injectable } from 'tsyringe-neo'
import { and, eq, isNull } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { feesConfiguration } from '@bk-dash/contracts/db'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

/**
 * Drizzle-backed FeesConfigurationRepository (iter 307 — paired with
 * the 0024 schema rename `shipping_fees`→`shipping_fee` + DROP NOT
 * NULL, bringing the table into agreement with the entity's singular
 * nullable `shippingFee` field).
 *
 * `findActiveByStoreId` returns the row with `endDate IS NULL` —
 * matches the supersede-on-write pattern UpdateFeesConfiguration uses
 * (the prior active row's endDate is stamped + a new row inserted;
 * the "active" pointer is "the one with null endDate").
 *
 * The three fee collections (gatewayFees, checkoutFees, shippingFee)
 * stay opaque at the repository layer — the entity validates them as
 * `unknown` arrays / scalar so the JSON shape is preserved verbatim
 * through the round-trip.
 */
@injectable()
export class DrizzleFeesConfigurationRepository extends FeesConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findActiveByStoreId(storeId: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(feesConfiguration)
				.where(and(eq(feesConfiguration.storeId, storeId), isNull(feesConfiguration.endDate)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: FeesConfiguration, tx?: DrizzleClient): Promise<FeesConfiguration> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(feesConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: feesConfiguration.id,
					set: {
						storeId: data.storeId,
						gatewayFees: data.gatewayFees,
						checkoutFees: data.checkoutFees,
						shippingFee: data.shippingFee,
						startDate: data.startDate,
						endDate: data.endDate,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(feesConfiguration).where(eq(feesConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof feesConfiguration.$inferSelect): FeesConfiguration {
		return new FeesConfiguration({
			id: row.id,
			storeId: row.storeId,
			gatewayFees: (row.gatewayFees as unknown[]) ?? [],
			checkoutFees: (row.checkoutFees as unknown[]) ?? [],
			shippingFee: row.shippingFee ?? null,
			startDate: row.startDate,
			endDate: row.endDate,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: FeesConfiguration): typeof feesConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			gatewayFees: entity.gatewayFees,
			checkoutFees: entity.checkoutFees,
			shippingFee: entity.shippingFee,
			startDate: entity.startDate,
			endDate: entity.endDate,
			version: entity.version,
		}
	}
}

