// OrderTransactionFee is the canonical fee row nested inside an
// OrderTransaction. Spec § BC4: `externalId, type, fixed, variable`.
type OrderTransactionFee struct {
	externalID string
	feeType    wire.OrderTransactionFeeType
	fixed      objects.MonetaryAmount
	variable   objects.MonetaryAmount
}

type OrderTransactionFeeInput struct {
	ExternalID string
	Type       string
	Fixed      objects.MonetaryAmount
	Variable   objects.MonetaryAmount
}

var (
	ErrFeeMissingExternalID = errors.New("orderTransactionFee: externalId required")
	ErrFeeInvalidType       = errors.New("orderTransactionFee: invalid type")
)

func NewOrderTransactionFee(in OrderTransactionFeeInput) (OrderTransactionFee, error) {
	if strings.TrimSpace(in.ExternalID) == "" {
		return OrderTransactionFee{}, ErrFeeMissingExternalID
	}
	feeType, err := wire.ParseOrderTransactionFeeType(in.Type)
	if err != nil {
		return OrderTransactionFee{}, fmt.Errorf("%w: %v", ErrFeeInvalidType, err)
	}
	return OrderTransactionFee{
		externalID: in.ExternalID,
		feeType:    feeType,
		fixed:      in.Fixed,
		variable:   in.Variable,
	}, nil
}

func (f OrderTransactionFee) ExternalID() string                 { return f.externalID }
func (f OrderTransactionFee) Type() wire.OrderTransactionFeeType { return f.feeType }
func (f OrderTransactionFee) Fixed() objects.MonetaryAmount      { return f.fixed }
func (f OrderTransactionFee) Variable() objects.MonetaryAmount   { return f.variable }

