 *   - checkoutFees[]  (per checkout platform)
 *   - shippingFee     (single, with type + value)
 *
 * Same time-effective shape as Taxes: a new row is opened with
 * `startDate=effectiveFrom`; the previously-active row's `endDate` is
 * stamped on supersession.
 *
 * Child shapes stay `unknown` at this layer to match the controller
 * surface — they're tightened once the spec's GatewayFee / CheckoutFee /
 * ShippingFee value objects ship in a follow-up iter.
 */
export const FeesConfigurationSchema = z.object({
	storeId: z.instance(Id),
	gatewayFees: z.array(z.unknown()).default([]),
	checkoutFees: z.array(z.unknown()).default([]),
	shippingFee: z.unknown().nullable().default(null),
	startDate: z.date(),
	endDate: z.date().nullable(),
})

export type FeesConfigurationProps = Z.infer<typeof FeesConfigurationSchema>

export class FeesConfiguration extends AggregateRoot<typeof FeesConfigurationSchema> {
	static override schema = FeesConfigurationSchema

	static create(data: {
		storeId: string
		gatewayFees?: unknown[]
		checkoutFees?: unknown[]
		shippingFee?: unknown
		startDate: Date
	}): FeesConfiguration {
		return new FeesConfiguration({
			storeId: data.storeId,
			gatewayFees: data.gatewayFees ?? [],
			checkoutFees: data.checkoutFees ?? [],
			shippingFee: data.shippingFee ?? null,
			startDate: data.startDate,
			endDate: null,
		})
	}

	supersede(at: Date): void {
		if (this.endDate !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'FeesConfiguration row already superseded')
		}
		if (at <= this.startDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'supersession instant must be after startDate')
