import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import type { FinanceDomainErrors } from '../errors'

/**
 * `FeesConfiguration` aggregate per spec § BC8 Finance. One parent
 * per Store carrying three typed child collections:
 *   - gatewayFees[]   (per platform × payment-method)
 *   - checkoutFees[]  (per checkout platform)
 *   - shippingFee     (single, with type + value)
 *
 * Same time-effective shape as Taxes: a new row is opened with
 * `startDate=effectiveFrom`; the previously-active row's `endDate` is
 * stamped on supersession.
 *
 * Child shapes stay `unknown` at this layer to match the controller
 * surface — they're tightened once the spec's GatewayFee / CheckoutFee /
 * ShippingFee value objects ship in a follow-up iter.
 */
export const FeesConfigurationSchema = z.object({
	storeId: z.instance(Id),
	gatewayFees: z.array(z.unknown()).default([]),
	checkoutFees: z.array(z.unknown()).default([]),
	shippingFee: z.unknown().nullable().default(null),
	startDate: z.date(),
	endDate: z.date().nullable(),
})

export type FeesConfigurationProps = Z.infer<typeof FeesConfigurationSchema>

export class FeesConfiguration extends AggregateRoot<typeof FeesConfigurationSchema> {
	static override schema = FeesConfigurationSchema

	static create(data: {
		storeId: string
		gatewayFees?: unknown[]
		checkoutFees?: unknown[]
		shippingFee?: unknown
		startDate: Date
	}): FeesConfiguration {
		return new FeesConfiguration({
			storeId: data.storeId,
			gatewayFees: data.gatewayFees ?? [],
			checkoutFees: data.checkoutFees ?? [],
			shippingFee: data.shippingFee ?? null,
			startDate: data.startDate,
			endDate: null,
		})
	}

	supersede(at: Date): void {
		if (this.endDate !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'FeesConfiguration row already superseded')
		}
		if (at <= this.startDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'supersession instant must be after startDate')
		}
		this.endDate = at
		this.validate()
	}

	get isActive(): boolean {
		return this.endDate === null
	}
}

export interface FeesConfiguration extends FeesConfigurationProps {}

import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, boolean, index, uniqueIndex } from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'

/**
 * `catalog` is BK Dash's BC5 Catalog schema.
 *
 * Two ownership models live in the same schema:
 *   - `products` + `variants` are **Go-owned** canonical projections,
 *     written via UPSERT by go-worker every time a provider catalog
 *     sync lands. Deterministic UUIDv5 PK + unique (platform,
 *     external_id) lets the (xmax = 0) is_new detection ride alongside.
 *   - `product_costs` (+ `product_cost_options`) is **TS-owned** —
 *     merchant-entered cost data, no provider source. Joined to
 *     products at analytics-query time to derive profit margin.
 */
export const catalogSchema = pgSchema('catalog')

export const products = catalogSchema.table(
	'products',
	{
		id: uuid('id').primaryKey(),

		storeId: uuid('store_id').notNull(),
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),

		// Provider-side identifiers + presentation.
		title: text('title').notNull(),
		handle: text('handle'),
		description: text('description'),
		vendor: text('vendor'),
		productType: text('product_type'),
		imageUrl: text('image_url'),

		// Status enum value from spec ProductStatus (ACTIVE/ARCHIVED/DRAFT)
		// — stored as text rather than pgEnum so we don't lock the
		// migration to one snapshot of the enum.
		status: text('status').notNull(),

		// Aggregated price range across all variants — cheap to denormalize
		// here so list views don't fan out to variant rows.
		minPriceCents: bigint('min_price_cents', { mode: 'bigint' }),
		maxPriceCents: bigint('max_price_cents', { mode: 'bigint' }),
		currency: text('currency'),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('products_platform_external_id_unq').on(t.platform, t.externalId),
		storeIdx: index('products_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('products_store_integration_id_idx').on(t.storeIntegrationId),
		statusIdx: index('products_status_idx').on(t.status),
	}),
)

/**
 * TS-owned merchant overlay on canonical Product (SPEC-10). Carries
 * fields the merchant edits without the Go sync pipeline overwriting:
 * starts with `tags`, future extensions go here (custom descriptions, etc.).
 * Unique on (product_id, store_id) — 1:1 with Product per Store.
 */
export const productOverrides = catalogSchema.table(
	'product_overrides',
	{
		id: uuid('id').primaryKey(),
		productId: uuid('product_id').notNull(),
		storeId: uuid('store_id').notNull(),

		// Merchant-curated tag list (moved off canonical Product).
		tags: jsonb('tags').notNull().default(sql`'[]'::jsonb`),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		productStoreUnq: uniqueIndex('product_overrides_product_id_store_id_unq').on(t.productId, t.storeId),
		storeIdx: index('product_overrides_store_id_idx').on(t.storeId),
	}),
)

export const variants = catalogSchema.table(
	'variants',
	{
		id: uuid('id').primaryKey(),

		// Parent product. Intentionally NO FK reference (Go writes variants
		// concurrently with products during a backfill; a strict FK would
		// require ordering writes by parent-then-child which `sqlc` doesn't
		// naturally express). Drizzle queries JOIN by product_id explicitly.
		productId: uuid('product_id').notNull(),

		// No storeId — the canonical ProductVariant aggregate (spec § BC5)

		// No storeId — the canonical ProductVariant aggregate (spec § BC5)
		// scopes by productId; the store is reachable by JOINing the parent
		// catalog.products. Dropped to keep the table aligned with the aggregate.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),
		productExternalId: text('product_external_id').notNull(),

		// Option labels — providers expose these as ordered key/value pairs
		// (Color/Red, Size/M, …). Stored as jsonb so 1- to N-option variants
		// share one column without schema churn.
		optionLabels: jsonb('option_labels'),

		title: text('title'),
		sku: text('sku'),
		imageUrl: text('image_url'),

		compareAtPriceCents: bigint('compare_at_price_cents', { mode: 'bigint' }),

		// Provider inventory quantity. Sentinel-free — null = provider
		// doesn't track inventory for this variant.
		quantityAvailable: integer('quantity_available'),

		status: text('status').notNull(),
		isDefault: boolean('is_default').notNull().default(false),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('variants_platform_external_id_unq').on(t.platform, t.externalId),
		productIdx: index('variants_product_id_idx').on(t.productId),
		storeIntegrationIdx: index('variants_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

/**
 * `product_costs` is the merchant-owned cost aggregate per Store ×
 * Product. The header carries scope + type; the `product_cost_options`
 * child table carries the time-effective / per-country / per-variant
 * cost tiers (one option = one (currency, country?, dateRange) slice).
 *
 * Spec rule: at most one ProductCost per (storeId, productId). The
 * variant-level granularity is encoded in `product_cost_options.items`.
 */
export const productCosts = catalogSchema.table(
	'product_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		// Scopes the cost row to the StoreIntegration that owns the
		// underlying product/variant ids. Required because the same
		// product can appear under multiple integrations (multi-channel
		// merchant) and merchant cost rules are typically per-channel.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		// References catalog.products.id but no FK — products can be
		// re-synced (re-UPSERTed) without breaking the merchant's cost
		// data; we want costs to survive provider id changes. Nullable
		// for kit-scoped costs (multi-variant bundle priced together).
		productId: uuid('product_id'),

		// Discriminator from spec ProductCostType (SINGLE / MULTIPLE).
		// SINGLE = one cost across all variants; MULTIPLE = per-variant.
		costType: text('cost_type').notNull(),

		// Optional merchant-facing label (used by the BFF list shape).
		displayName: text('display_name'),

		// Time-effective option array, stored inline as jsonb. Each
		// option carries: { id, currency, country?, startDate, endDate?,
		// shipping: {amountCents, currency}, items: [{id, variantIds,
		// quantity, quantityModifier, unitCost, shipping, variantsHash}] }.
		// Inlined (vs the original product_cost_options child table)
		// because reads always pull the full document; the child-table
		// shape required cascade writes + N+1 reads for no actual
		// normalization benefit.
		options: jsonb('options').notNull().default([]),

		// Soft-delete timestamp. List queries filter by `deleted_at IS NULL`.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Partial unique — only enforce on live rows so a re-created cost
		// for the same (storeId, productId) after soft-delete doesn't
		// collide with the historical row.
		storeProductUnq: uniqueIndex('product_costs_store_product_unq').on(t.storeId, t.productId).where(sql`${t.deletedAt} IS NULL`),
		storeIdx: index('product_costs_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('product_costs_store_integration_id_idx').on(t.storeIntegrationId),
