import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { MarketingPlatform, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from '../entities/Taxes'
import { TaxesRepository } from '../repositories/TaxesRepository'
import { TaxesUpdatedEvent } from '../events'

export const UpdateTaxesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	revenueTaxType: z.enum(TaxType).optional(),
	revenueTaxDeductionType: z.enum(TaxDeductionType).optional(),
	/** Effective rate as a 0..100 percentage. Persisted as 0..1 fraction. */
	revenueTaxRate: z.number().min(0).max(100).optional(),
	revenueTaxMultiplier: z.number().min(0).optional(),
	marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).optional(),
	effectiveFrom: z.date(),
})

export const UpdateTaxesOutputSchema = z.object({
	taxesId: z.uuid(),
	effectiveFrom: z.date(),
})

/**
 * C39 UpdateTaxes. Time-effective insert: opens a new row with the
 * supplied effectiveFrom + any patched fields (carrying defaults forward
 * from the previously-active row when present), and supersedes the
 * previous row by stamping its endDate with the new effectiveFrom.
 *
 * The supersession + insert are persisted in a single transaction so
 * reads always see exactly one active row per store.
 */
@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxes: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.taxes.findActiveByStoreId(input.storeId, tx)

			const type = input.revenueTaxType ?? previous?.type ?? TaxType.NONE
			const deductionType = input.revenueTaxDeductionType ?? previous?.deductionType ?? TaxDeductionType.NONE
			const ratePct = input.revenueTaxRate ?? (previous ? previous.rate * 100 : 0)
			const rate = ratePct / 100
			const revenueTaxMultiplier = input.revenueTaxMultiplier ?? previous?.revenueTaxMultiplier ?? 1.0
			const marketingTaxRatePerPlatform = input.marketingTaxRatePerPlatform ?? previous?.marketingTaxRatePerPlatform ?? {}

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.taxes.save(previous, tx)
			}

			const fresh = Taxes.create({
				storeId: input.storeId,
				type,
				deductionType,
				rate,
				revenueTaxMultiplier,
				marketingTaxRatePerPlatform,
				startDate: input.effectiveFrom,
			})
			await this.taxes.save(fresh, tx)

			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						taxes: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousTaxesId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { taxesId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { and, eq, isNull } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { feesConfiguration } from '@bk-dash/contracts/db'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

/**
 * Drizzle-backed FeesConfigurationRepository (iter 307 — paired with
 * the 0024 schema rename `shipping_fees`→`shipping_fee` + DROP NOT
 * NULL, bringing the table into agreement with the entity's singular
 * nullable `shippingFee` field).
 *
 * `findActiveByStoreId` returns the row with `endDate IS NULL` —
 * matches the supersede-on-write pattern UpdateFeesConfiguration uses
 * (the prior active row's endDate is stamped + a new row inserted;
 * the "active" pointer is "the one with null endDate").
 *
 * The three fee collections (gatewayFees, checkoutFees, shippingFee)
 * stay opaque at the repository layer — the entity validates them as
 * `unknown` arrays / scalar so the JSON shape is preserved verbatim
 * through the round-trip.
 */
@injectable()
export class DrizzleFeesConfigurationRepository extends FeesConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findActiveByStoreId(storeId: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(feesConfiguration)
				.where(and(eq(feesConfiguration.storeId, storeId), isNull(feesConfiguration.endDate)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: FeesConfiguration, tx?: DrizzleClient): Promise<FeesConfiguration> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(feesConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: feesConfiguration.id,
					set: {
						storeId: data.storeId,
						gatewayFees: data.gatewayFees,
						checkoutFees: data.checkoutFees,
						shippingFee: data.shippingFee,
						startDate: data.startDate,
						endDate: data.endDate,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(feesConfiguration).where(eq(feesConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof feesConfiguration.$inferSelect): FeesConfiguration {
		return new FeesConfiguration({
			id: row.id,
			storeId: row.storeId,
			gatewayFees: (row.gatewayFees as unknown[]) ?? [],
			checkoutFees: (row.checkoutFees as unknown[]) ?? [],
			shippingFee: row.shippingFee ?? null,
			startDate: row.startDate,
			endDate: row.endDate,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: FeesConfiguration): typeof feesConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			gatewayFees: entity.gatewayFees,
			checkoutFees: entity.checkoutFees,
			shippingFee: entity.shippingFee,
			startDate: entity.startDate,
			endDate: entity.endDate,
			version: entity.version,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

@injectable()
export class MockFeesConfigurationRepository extends FeesConfigurationRepository {
	private rows = new Map<string, FeesConfiguration>()

	async findById(id: string, _tx?: Transaction): Promise<FeesConfiguration | undefined> {
		return this.rows.get(id)
	}

	async findActiveByStoreId(storeId: string, _tx?: Transaction): Promise<FeesConfiguration | undefined> {
		for (const f of this.rows.values()) {
			if (f.storeId.value === storeId && f.isActive) return f
		}
		return undefined
	}

	async save(entity: FeesConfiguration, _tx?: Transaction): Promise<FeesConfiguration> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: FeesConfiguration): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}

import { BaseDomainEvent, z } from '@bk-dash/core-typescript'
import { FeesConfigurationSchema } from '../entities/FeesConfiguration'

export const FeesConfigurationUpdatedEventSchema = z.domainEvent({
	feesConfiguration: FeesConfigurationSchema.input(),
	effectiveStartDate: z.date(),
	previousFeesConfigurationId: z.uuid().nullable(),
})

export class FeesConfigurationUpdatedEvent extends BaseDomainEvent<typeof FeesConfigurationUpdatedEventSchema> {
	static override readonly name = 'finance.fees_configuration.updated' as const
	static readonly schema = FeesConfigurationUpdatedEventSchema
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { FeesConfiguration } from '../entities/FeesConfiguration'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

export const UpdateFeesConfigurationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	gatewayFees: z.array(z.unknown()).optional(),
	checkoutFees: z.array(z.unknown()).optional(),
	shippingFee: z.unknown().optional(),
	effectiveFrom: z.date(),
})

export const UpdateFeesConfigurationOutputSchema = z.object({
	feesConfigurationId: z.uuid(),
	effectiveFrom: z.date(),
})

/**
 * C40 UpdateFeesConfiguration. Time-effective insert covering the three
 * fee blocks. Mirrors the UpdateTaxes shape: supersede the active row,
 * insert a fresh one carrying forward non-supplied fee collections, and
 * emit FeesConfigurationUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateFeesConfiguration extends Handler<
	typeof UpdateFeesConfigurationInputSchema,
	typeof UpdateFeesConfigurationOutputSchema
> {
	readonly name = 'update_fees_configuration' as const
	readonly inputSchema = UpdateFeesConfigurationInputSchema
	readonly outputSchema = UpdateFeesConfigurationOutputSchema

	constructor(private readonly fees: FeesConfigurationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.fees.findActiveByStoreId(input.storeId, tx)

			const gatewayFees = input.gatewayFees ?? previous?.gatewayFees ?? []
			const checkoutFees = input.checkoutFees ?? previous?.checkoutFees ?? []
			const shippingFee = input.shippingFee !== undefined ? input.shippingFee : (previous?.shippingFee ?? null)

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.fees.save(previous, tx)
			}

			const fresh = FeesConfiguration.create({
				storeId: input.storeId,
				gatewayFees,
				checkoutFees,
				shippingFee,
				startDate: input.effectiveFrom,
			})
			await this.fees.save(fresh, tx)

			await this.domainEventRepository.save(
				new FeesConfigurationUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						feesConfiguration: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousFeesConfigurationId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { feesConfigurationId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

