export const GetTaxesSettingsOutputSchema = z.object({
	storeId: z.uuid(),
	revenueTaxType: z.enum(TaxType).nullable(),
	revenueTaxDeductionType: z.enum(TaxDeductionType).nullable(),
	/** Effective rate as 0..100 percentage. */
	revenueTaxRate: z.number().nullable(),
	revenueTaxMultiplier: z.number().nullable(),
	marketingTaxRatePerPlatform: z.record(z.string(), z.number()),
	reportingCurrency: z.enum(CurrencyCode).nullable(),
	effectiveFrom: z.date().nullable(),
})

/**
 * T25 TaxesSettings. Returns the currently-effective Taxes row for a
 * Store. `revenueTaxRate` is denormalised back to a 0..100 percentage
 * for the UI. `reportingCurrency` would COALESCE from the Store
 * preferences row at the BFF layer — left null here until that read
 * use case wires through (cross-BC composition).
 */
@injectable()
export class GetTaxesSettings extends Handler<typeof GetTaxesSettingsInputSchema, typeof GetTaxesSettingsOutputSchema> {
	readonly name = 'get_taxes_settings' as const
	readonly inputSchema = GetTaxesSettingsInputSchema
	readonly outputSchema = GetTaxesSettingsOutputSchema

	constructor(private readonly taxes: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const active = await this.taxes.findActiveByStoreId(input.storeId, tx)
		if (!active) {
			return {
				storeId: input.storeId,
				revenueTaxType: null,
				revenueTaxDeductionType: null,
				revenueTaxRate: null,
				revenueTaxMultiplier: null,
				marketingTaxRatePerPlatform: {},
				reportingCurrency: null,
				effectiveFrom: null,
			}
		}
		return {
			storeId: input.storeId,
			revenueTaxType: active.type,
