import { mkdir, writeFile, rm } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { readFile } from 'node:fs/promises'
import { parseContractsOpenapi, type ParsedEnum, type ParsedUnion, type ParsedEvent, type FieldType } from './lib/parse-openapi'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')
const INPUT = join(ROOT, 'dist/contracts.openapi.yaml')
const OUTPUT = join(ROOT, 'generated/typescript/src/wire')

const HEADER = `// AUTO-GENERATED by packages/contracts/codegen/emit-wire-ts.ts — do not edit.\n`

function kebab(name: string): string {
	return name.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase()
}

/**
 * Convert an enum value string to a valid TypeScript identifier.
 * For values that are already valid identifiers (e.g. "SHOPIFY"), this is a no-op.
 * For dotted namespaced values (e.g. "sync.external_order_updated"), the leading
 * namespace segment (everything up to and including the first ".") is stripped before
 * uppercasing + replacing remaining non-identifier chars with "_". This currently
 * serves the only dotted enum in the contracts: SyncEventName.
 * "sync.external_order_updated" → strip "sync." → "external_order_updated" → "EXTERNAL_ORDER_UPDATED"
 */
function toTsEnumMember(v: string): string {
	if (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(v)) return v
	// Strip the leading namespace segment (up to and including the first dot), then
	// uppercase and replace any remaining non-identifier characters with underscores.
	const stripped = v.includes('.') ? v.slice(v.indexOf('.') + 1) : v
	return stripped.toUpperCase().replace(/[^A-Z0-9_$]/g, '_')
}

export function emitTsEnums(enums: ParsedEnum[]): Record<string, string> {
	const files: Record<string, string> = {}
	const indexLines: string[] = []

	for (const e of enums) {
		const file = `${kebab(e.name)}.ts`
		const members = e.values.map(v => `\t${toTsEnumMember(v)} = '${v}',`).join('\n')
		const body = `${HEADER + (e.doc ? `/** ${e.doc} */\n` : '')}export enum ${e.name} {\n${members}\n}\n`
		files[file] = body
		indexLines.push(`export * from './${kebab(e.name)}'`)
	}

	files['index.ts'] = `${HEADER + indexLines.sort().join('\n')}\n`
	return files
}

export function emitTsUnions(unions: ParsedUnion[]): Record<string, string> {
	const files: Record<string, string> = {}
	const indexLines: string[] = []
	for (const u of unions) {
		const members = u.refs.map(r => `z.enum(${r})`).join(', ')
		const body =
			HEADER +
			`import { z } from '@bk-dash/core-typescript/schema'\n` +
			`import { ${u.refs.join(', ')} } from '../enums'\n\n` +
			(u.doc ? `/** ${u.doc} */\n` : '') +
			`export const ${u.name}Schema = z.union([${members}])\n`
		files[`${kebab(u.name)}.ts`] = body
		indexLines.push(`export * from './${kebab(u.name)}'`)
	}
	files['index.ts'] = `${HEADER + indexLines.sort().join('\n')}\n`
	return files
}

const ENVELOPE_FIELDS = new Set(['name', 'entityId', 'ownerId', 'occurredAt'])

function zodExpr(t: FieldType): string {
	switch (t.kind) {
		case 'string':
			return 'z.string()'
		case 'literal':
			return `z.literal('${t.value}')`
		case 'string-enum':
			return `z.enum([${t.values.map(v => `'${v}'`).join(', ')}])`
		case 'enum-ref':
			return `z.enum(${t.ref})`
		case 'union-ref':
			return `${t.ref}Schema`
		case 'boolean':
			return 'z.boolean()'
		case 'integer':
			return 'z.number().int()'
		case 'number':
			return 'z.number()'
		case 'date-time':
			return 'z.date()'
		case 'url':
			return 'z.string().url()'
		case 'unknown':
			return 'z.unknown()'
	}
}

export function emitTsEvents(events: ParsedEvent[]): Record<string, string> {
	const files: Record<string, string> = {}

	for (const ev of events) {
		const payloadFields = ev.fields.filter(f => !ENVELOPE_FIELDS.has(f.name))

		const enumRefs = payloadFields.filter(f => f.type.kind === 'enum-ref').map(f => (f.type as { ref: string }).ref)
		const enumImports = [...new Set(enumRefs)].sort()
		const importLines = [
			`import { z } from '@bk-dash/core-typescript/schema'`,
			`import { BaseIntegrationEvent } from '@bk-dash/core-typescript/events'`,
		]
		if (enumImports.length > 0) {
			const names = enumImports.join(', ')
			importLines.push(`import { ${names} } from '../enums'`)
		}
		const unionRefs = payloadFields.filter(f => f.type.kind === 'union-ref').map(f => (f.type as { ref: string }).ref)
		const unionImports = [...new Set(unionRefs)].sort()
		if (unionImports.length > 0) {
			importLines.push(`import { ${unionImports.map(r => `${r}Schema`).join(', ')} } from '../unions'`)
		}

		const zodFields = payloadFields.map(f => `\t${f.name}: ${zodExpr(f.type)}${f.required ? '' : '.optional()'},`).join('\n')

		const body =
			HEADER +
			importLines.join('\n') +
			'\n\n' +
			(ev.doc ? `/** ${ev.doc} */\n` : '') +
			`export const ${ev.modelName}Schema = z.integrationEvent('${ev.wireName}', {\n${zodFields}\n})\n\n` +
			`export class ${ev.modelName} extends BaseIntegrationEvent<typeof ${ev.modelName}Schema> {\n` +
			`\tstatic override readonly name = '${ev.wireName}' as const\n` +
			`\tstatic readonly schema = ${ev.modelName}Schema\n` +
			`}\n`

		files[`${kebab(ev.modelName.replace(/Event$/, ''))}.ts`] = body
	}

	return files
}

export function emitTsBarrel(events: ParsedEvent[]): string {
	const names = events.map(e => e.modelName)
	const reExports = events
		.map(e => `export * from './${kebab(e.modelName.replace(/Event$/, ''))}'`)
		.sort()
		.join('\n')
	const schemaImports = names.map(n => `\t${n}Schema,`).join('\n')
	const schemas = names.map(n => `\t${n}Schema`).join(',\n')
	return (
		HEADER +
		`import { z } from '@bk-dash/core-typescript/schema'\n` +
		`import Z from 'zod'\n` +
		`import {\n${schemaImports}\n} from './_imports'\n\n` +
		reExports +
		'\n\n' +
		`export const IntegrationEventSchema = z.discriminatedUnion('name', [\n${schemas},\n])\n` +
		`export type IntegrationEvent = Z.infer<typeof IntegrationEventSchema>\n`
	)
}

async function run() {
	const yamlText = await readFile(INPUT, 'utf-8')
	const parsed = parseContractsOpenapi(yamlText)

	const enumDir = join(OUTPUT, 'enums')
	const unionDir = join(OUTPUT, 'unions')
	const eventDir = join(OUTPUT, 'events')
	await rm(enumDir, { recursive: true, force: true })
	await rm(eventDir, { recursive: true, force: true })
	await mkdir(enumDir, { recursive: true })
	await mkdir(eventDir, { recursive: true })

	const enumFiles = emitTsEnums(parsed.enums)
	for (const [name, contents] of Object.entries(enumFiles)) {
		await writeFile(join(enumDir, name), contents)
	}
	if (parsed.unions.length > 0) {
		await rm(unionDir, { recursive: true, force: true })
		await mkdir(unionDir, { recursive: true })
		const unionFiles = emitTsUnions(parsed.unions)
		for (const [name, contents] of Object.entries(unionFiles)) {
			await writeFile(join(unionDir, name), contents)
		}
	}

	const eventFiles = emitTsEvents(parsed.events)
	for (const [name, contents] of Object.entries(eventFiles)) {
		await writeFile(join(eventDir, name), contents)
	}

	const importsRe =
		HEADER +
		parsed.events
			.map(e => `export * from './${kebab(e.modelName.replace(/Event$/, ''))}'`)
			.sort()
			.join('\n') +
		'\n'
	await writeFile(join(eventDir, '_imports.ts'), importsRe)

	await writeFile(join(eventDir, 'index.ts'), emitTsBarrel(parsed.events))

	const unionExport = parsed.unions.length > 0 ? `export * from './unions'\n` : ''
	const wireIndex = `${HEADER}export * from './enums'\n${unionExport}export * from './events'\n`
	await writeFile(join(OUTPUT, 'index.ts'), wireIndex)

	console.log(`✔ emitted ${parsed.enums.length} enums and ${parsed.events.length} events`)
}

if (import.meta.main) {
	await run()
}

import { mkdir, writeFile, rm, readFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseContractsOpenapi, type ParsedEnum, type ParsedUnion, type ParsedEvent, type FieldType } from './lib/parse-openapi'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')
const INPUT = join(ROOT, 'dist/contracts.openapi.yaml')
const OUTPUT = join(ROOT, 'generated/go/wire')

const HEADER = `// AUTO-GENERATED by packages/contracts/codegen/emit-wire-go.ts — do not edit.\n`

function pascalToGoField(name: string): string {
	const out = name[0]!.toUpperCase() + name.slice(1)
	return out.replace(/Id\b/g, 'ID').replace(/Url\b/g, 'URL')
}

function goType(t: FieldType): string {
	switch (t.kind) {
		case 'string':
			return 'string'
		case 'literal':
			return 'string'
		case 'string-enum':
			return 'string'
		case 'enum-ref':
			return t.ref
		case 'union-ref':
			return t.ref
		case 'boolean':
			return 'bool'
		case 'integer':
			return t.format === 'int64' ? 'int64' : 'int32'
		case 'number':
			return 'float64'
		case 'date-time':
			return 'time.Time'
		case 'url':
			return 'string'
		case 'unknown':
			return 'json.RawMessage'
	}
}

/**
 * Convert an enum value string to a valid Go identifier suffix.
 * For values that are already valid identifiers (e.g. "SHOPIFY"), this is a no-op.
 * For dotted namespaced values (e.g. "sync.external_order_updated"), the leading
 * namespace segment (everything up to and including the first ".") is stripped before
 * uppercasing + replacing remaining non-identifier chars with "_". This currently
 * serves the only dotted enum in the contracts: SyncEventName.
 * "sync.external_order_updated" → strip "sync." → "external_order_updated" → "EXTERNAL_ORDER_UPDATED"
 */
function toGoEnumIdent(v: string): string {
	// If already a valid Go identifier suffix (letters, digits, underscores; no leading digit)
	if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(v)) return v
	// Strip the leading namespace segment (up to and including the first dot), then
	// uppercase and replace any remaining non-identifier characters with underscores.
	const stripped = v.includes('.') ? v.slice(v.indexOf('.') + 1) : v
	return stripped.toUpperCase().replace(/[^A-Z0-9_]/g, '_')
}

export function emitGoEnums(enums: ParsedEnum[]): string {
	const lines: string[] = [HEADER, 'package wire', '', 'import "fmt"', '']
	for (const e of enums) {
		lines.push(`type ${e.name} string`)
		lines.push('')
		lines.push('const (')
		for (const v of e.values) lines.push(`\t${e.name}${toGoEnumIdent(v)} ${e.name} = "${v}"`)
		lines.push(')')
		lines.push('')
		lines.push(`func Parse${e.name}(s string) (${e.name}, error) {`)
		lines.push(`\tswitch ${e.name}(s) {`)
		const cases = e.values.map(v => `${e.name}${toGoEnumIdent(v)}`).join(', ')
		lines.push(`\tcase ${cases}:`)
		lines.push(`\t\treturn ${e.name}(s), nil`)
		lines.push('\tdefault:')
		lines.push(`\t\treturn "", fmt.Errorf("invalid ${e.name}: %q", s)`)
		lines.push('\t}')
		lines.push('}')
		lines.push('')
	}
	return lines.join('\n')
}

export function emitGoUnions(unions: ParsedUnion[]): string {
	const lines: string[] = [HEADER, 'package wire', '']
	for (const u of unions) {
		lines.push(`// ${u.name} is a cross-category union of platform enums.`)
		if (u.doc) lines.push(`// ${u.doc}`)
		// Bridge annotation: read by core/pkg/openapi to emit a oneOf component.
		// `values=` lists the member enum TYPE names (each becomes a $ref).
		lines.push(`// @oneof values=${u.refs.join(',')}`)
		lines.push(`type ${u.name} string`)
		lines.push('')
		lines.push(`// Valid reports whether the value is a member of any variant enum.`)
		lines.push(`func (p ${u.name}) Valid() bool {`)
		for (const r of u.refs) {
			lines.push(`\tif _, err := Parse${r}(string(p)); err == nil {`)
			lines.push(`\t\treturn true`)
			lines.push(`\t}`)
		}
		lines.push(`\treturn false`)
		lines.push(`}`)
		lines.push('')
	}
	return lines.join('\n')
}

const ENVELOPE_FIELDS = new Set(['name', 'entityId', 'ownerId', 'occurredAt'])

export function emitGoEvents(events: ParsedEvent[]): string {
	const lines: string[] = [HEADER, 'package wire', '']
	const needsTime = events.some(e => e.fields.some(f => f.type.kind === 'date-time'))
	const needsJson = events.some(e => e.fields.some(f => f.type.kind === 'unknown'))
	const imports: string[] = []
	if (needsTime) imports.push('"time"')
	if (needsJson) imports.push('"encoding/json"')
	if (imports.length > 0) {
		lines.push('import (')
		for (const i of imports) lines.push(`\t${i}`)
		lines.push(')')
		lines.push('')
	}

	for (const ev of events) {
		lines.push(`// ${ev.modelName}Name is the wire discriminator for ${ev.modelName}.`)
		lines.push(`const ${ev.modelName}Name = "${ev.wireName}"`)
		lines.push('')
		lines.push(`// ${ev.modelName} — wire shape of ${ev.wireName}.`)
		if (ev.doc) lines.push(`// ${ev.doc}`)
		lines.push(`type ${ev.modelName} struct {`)
		// Name discriminator field first
		lines.push(`\tName       string    \`json:"name"\``)
		// Envelope fields
		lines.push(`\tEntityID   string    \`json:"entityId"\``)
		lines.push(`\tOwnerID    string    \`json:"ownerId"\``)
		lines.push(`\tOccurredAt time.Time \`json:"occurredAt"\``)
		// Payload fields (everything that's not envelope or name)
		for (const f of ev.fields) {
			if (ENVELOPE_FIELDS.has(f.name)) continue
			const goField = pascalToGoField(f.name)
			const ty = goType(f.type)
			const ptr = f.required ? '' : '*'
			const tag = f.required ? f.name : `${f.name},omitempty`
			lines.push(`\t${goField} ${ptr}${ty} \`json:"${tag}"\``)
		}
		lines.push('}')
		lines.push('')
		lines.push(`func (e ${ev.modelName}) EventName() string { return ${ev.modelName}Name }`)
		lines.push('')
	}
	return lines.join('\n')
}

export function emitGoEnvelope(events: ParsedEvent[]): string {
	const lines: string[] = [HEADER, 'package wire', '', 'import (', '\t"encoding/json"', '\t"fmt"', ')', '']
	lines.push('// IntegrationEvent is the discriminator interface — all event structs satisfy it.')
	lines.push('type IntegrationEvent interface {')
	lines.push('\tEventName() string')
	lines.push('}')
	lines.push('')
	lines.push('// UnmarshalIntegrationEvent parses a wire envelope and dispatches to the right struct.')
	lines.push('func UnmarshalIntegrationEvent(data []byte) (IntegrationEvent, error) {')
	lines.push('\tvar discriminator struct {')
	lines.push('\t\tName string `json:"name"`')
	lines.push('\t}')
	lines.push('\tif err := json.Unmarshal(data, &discriminator); err != nil {')
	lines.push('\t\treturn nil, err')
	lines.push('\t}')
	lines.push('\tswitch discriminator.Name {')
	for (const ev of events) {
		lines.push(`\tcase "${ev.wireName}":`)
		lines.push(`\t\tvar v ${ev.modelName}`)
		lines.push('\t\tif err := json.Unmarshal(data, &v); err != nil {')
		lines.push('\t\t\treturn nil, err')
		lines.push('\t\t}')
		lines.push('\t\treturn v, nil')
	}
	lines.push('\tdefault:')
	lines.push('\t\treturn nil, fmt.Errorf("unknown integration event: %q", discriminator.Name)')
	lines.push('\t}')
	lines.push('}')
	lines.push('')
	lines.push('// ParseIntegrationEvent is an alias for UnmarshalIntegrationEvent.')
	lines.push('// It decodes a wire JSON envelope into the concrete typed event by switching on the `name` field.')
	lines.push('func ParseIntegrationEvent(raw []byte) (IntegrationEvent, error) {')
	lines.push('\treturn UnmarshalIntegrationEvent(raw)')
	lines.push('}')
	return `${lines.join('\n')}\n`
}

async function run() {
	const yamlText = await readFile(INPUT, 'utf-8')
	const parsed = parseContractsOpenapi(yamlText)
	await rm(OUTPUT, { recursive: true, force: true })
	await mkdir(OUTPUT, { recursive: true })
	await writeFile(join(OUTPUT, 'enums.go'), emitGoEnums(parsed.enums))
	if (parsed.unions.length > 0) {
		await writeFile(join(OUTPUT, 'unions.go'), emitGoUnions(parsed.unions))
	}
	await writeFile(join(OUTPUT, 'events.go'), emitGoEvents(parsed.events))
	await writeFile(join(OUTPUT, 'envelope.go'), emitGoEnvelope(parsed.events))
	console.log(`✔ emitted Go bindings: ${parsed.enums.length} enums, ${parsed.unions.length} unions, ${parsed.events.length} events`)
}

if (import.meta.main) {
	await run()
}

