import { describe, expect, it } from 'bun:test'
import { BaseError } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { testId } from '@test/support'
import { ProductCost, ProductCostSchema } from './ProductCost'

const STORE = testId('store', '1')
const INTEGRATION = testId('integration', '1')
const PRODUCT = testId('product', '1')
const VARIANT = testId('variant', '1')
const OPT = testId('opt', '1')
const ITEM = testId('item', '1')

const baseProps = {
	storeId: STORE,
	storeIntegrationId: INTEGRATION,
	productId: PRODUCT,
	costType: ProductCostType.SINGLE,
	displayName: 'Acme Widget',
	options: [
		{
			id: OPT,
			currency: CurrencyCode.USD,
			country: 'US',
			startDate: '2026-01-01',
			endDate: '2026-12-31',
			shipping: { amountCents: 500, currency: CurrencyCode.USD },
			items: [
				{
					id: ITEM,
					variantIds: [VARIANT],
					quantity: 1,
					quantityModifier: QuantityModifier.EQ,
					unitCost: { amountCents: 1000, currency: CurrencyCode.USD },
					shipping: { amountCents: 0, currency: CurrencyCode.USD },
					variantsHash: VARIANT,
				},
			],
		},
	],
	deletedAt: null,
}

describe('ProductCost entity schema', () => {
	it('accepts a valid props shape', () => {
		const r = ProductCostSchema.safeParse(baseProps)
		expect(r.success).toBe(true)
	})

	it('rejects an empty options array', () => {
		expect(() => ProductCostSchema.parse({ ...baseProps, options: [{ ...baseProps.options[0]!, items: [] }] })).toThrow()
	})

	it('keeps deletedAt nullable', () => {
		const r = ProductCostSchema.safeParse({ ...baseProps, deletedAt: null })
		expect(r.success).toBe(true)
	})

	it('exports ProductCost class', () => {
		expect(ProductCost).toBeDefined()
	})
})

describe('ProductCostOptionSchema — date-range invariant', () => {
	const makeOption = (startDate: string, endDate?: string) => ({
		...baseProps.options[0]!,
		startDate,
		endDate,
	})

	it('rejects startDate > endDate via schema', () => {
		// ProductCostOptionSchema uses z.instance(ProductCostOption), which
		// calls new ProductCostOption(opt) inside a .transform(). The VO
		// constructor throws BaseError('INVALID_DATE_RANGE') on an invalid date
		// range — that throw escapes Zod's safeParse boundary. Assert the throw
		// directly (this IS the intended architecture, not a workaround).
		expect(() =>
			ProductCostSchema.parse({
				...baseProps,
				options: [makeOption('2026-12-31', '2026-01-01')],
			}),
		).toThrowError(expect.objectContaining({ name: 'INVALID_DATE_RANGE' }))
	})

	it('accepts startDate === endDate', () => {
		const r = ProductCostSchema.safeParse({
			...baseProps,
			options: [makeOption('2026-06-01', '2026-06-01')],
		})
		expect(r.success).toBe(true)
	})

	it('accepts startDate < endDate', () => {
		const r = ProductCostSchema.safeParse({
			...baseProps,
			options: [makeOption('2026-01-01', '2026-12-31')],
		})
		expect(r.success).toBe(true)
	})

	it('accepts a missing endDate (open-ended)', () => {
		const r = ProductCostSchema.safeParse({
			...baseProps,
			options: [makeOption('2026-01-01', undefined)],
		})
		expect(r.success).toBe(true)
	})

	it('ProductCost.create() throws INVALID_DATE_RANGE when startDate > endDate', () => {
		expect(() =>
			ProductCost.create({
				storeId: STORE,
				storeIntegrationId: INTEGRATION,
				productId: PRODUCT,
				costType: ProductCostType.SINGLE,
				options: [
					{
						currency: CurrencyCode.USD,
						startDate: '2026-12-31',
						endDate: '2026-01-01',
						shipping: { amountCents: 0, currency: CurrencyCode.USD },
						items: [
							{
								variantIds: [VARIANT],
								quantity: 1,
								quantityModifier: QuantityModifier.EQ,
								unitCost: { amountCents: 1000, currency: CurrencyCode.USD },
								shipping: { amountCents: 0, currency: CurrencyCode.USD },
							},
						],
					},
				],
			}),
		).toThrowError(expect.objectContaining({ name: 'INVALID_DATE_RANGE' }))
	})
})

