export interface FeesConfiguration extends FeesConfigurationProps {}

import { BaseError, type BaseDomainErrors } from '@bk-dash/core-typescript'

/** Anything carrying a half-open `[startDate, endDate)` window. `endDate` null = +∞. */
export interface TimeWindowed {
	startDate: Date
	endDate: Date | null
}

/**
 * Immutable last-write-wins interval series. `place(entry)` overwrites exactly
 * `[entry.startDate, entry.endDate)` and trims/splits/removes overlapping
 * entries so the series stays sorted and non-overlapping. Entries are plain
 * windowed objects (the `z.historical`-inferred shapes), cloned via spread on
 * trim/split. Scope a Timeline per logical key (e.g. one per gateway
 * platform×method) — placing into one Timeline never affects another.
 */
export class Timeline<T extends TimeWindowed> {
	constructor(public readonly entries: readonly T[]) {
		const sorted = [...entries].sort((a, b) => a.startDate.getTime() - b.startDate.getTime())
		for (let i = 1; i < sorted.length; i++) {
			const prev = sorted[i - 1]!
			const cur = sorted[i]!
			if (prev.endDate === null || prev.endDate > cur.startDate) {
				throw new BaseError<BaseDomainErrors>('INVALID_DATE_RANGE' as BaseDomainErrors)
			}
		}
		this.entries = sorted
	}

	static empty<T extends TimeWindowed>(): Timeline<T> {
		return new Timeline<T>([])
	}

	place(entry: T): Timeline<T> {
		const s = entry.startDate
		const e = entry.endDate
		const next: T[] = []
		for (const ex of this.entries) {
			const a = ex.startDate
			const b = ex.endDate
			const noOverlap = (b !== null && b <= s) || (e !== null && a >= e)
			if (noOverlap) {
				next.push(ex)
				continue
			}
			if (a < s) next.push({ ...ex, startDate: a, endDate: s })
			if (e !== null && (b === null || e < b)) next.push({ ...ex, startDate: e, endDate: b })
		}
		next.push(entry)
		return new Timeline<T>(next)
	}

	activeAt(date: Date): T | undefined {
		return this.entries.find(en => en.startDate <= date && (en.endDate === null || date < en.endDate))
	}

	current(): T | undefined {
		return this.entries.find(en => en.endDate === null)
	}
}

import { BaseDomainEvent, z } from '@bk-dash/core-typescript'
import { FeesConfigurationSchema } from '../entities/FeesConfiguration'

export const FeesConfigurationUpdatedEventSchema = z.domainEvent({
	feesConfiguration: FeesConfigurationSchema.input(),
	effectiveStartDate: z.date(),
	previousFeesConfigurationId: z.uuid().nullable(),
})

export class FeesConfigurationUpdatedEvent extends BaseDomainEvent<typeof FeesConfigurationUpdatedEventSchema> {
	static override readonly name = 'finance.fees_configuration.updated' as const
	static readonly schema = FeesConfigurationUpdatedEventSchema
}

import { injectable } from 'tsyringe-neo'
import { and, eq, isNull } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { feesConfiguration } from '@bk-dash/contracts/db'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

/**
 * Drizzle-backed FeesConfigurationRepository (iter 307 — paired with
 * the 0024 schema rename `shipping_fees`→`shipping_fee` + DROP NOT
 * NULL, bringing the table into agreement with the entity's singular
 * nullable `shippingFee` field).
 *
 * `findActiveByStoreId` returns the row with `endDate IS NULL` —
 * matches the supersede-on-write pattern UpdateFeesConfiguration uses
 * (the prior active row's endDate is stamped + a new row inserted;
 * the "active" pointer is "the one with null endDate").
 *
 * The three fee collections (gatewayFees, checkoutFees, shippingFee)
 * stay opaque at the repository layer — the entity validates them as
 * `unknown` arrays / scalar so the JSON shape is preserved verbatim
 * through the round-trip.
 */
@injectable()
export class DrizzleFeesConfigurationRepository extends FeesConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findActiveByStoreId(storeId: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(feesConfiguration)
				.where(and(eq(feesConfiguration.storeId, storeId), isNull(feesConfiguration.endDate)))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: FeesConfiguration, tx?: DrizzleClient): Promise<FeesConfiguration> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(feesConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: feesConfiguration.id,
					set: {
						storeId: data.storeId,
						gatewayFees: data.gatewayFees,
						checkoutFees: data.checkoutFees,
						shippingFee: data.shippingFee,
						startDate: data.startDate,
						endDate: data.endDate,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(feesConfiguration).where(eq(feesConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof feesConfiguration.$inferSelect): FeesConfiguration {
		return new FeesConfiguration({
			id: row.id,
			storeId: row.storeId,
			gatewayFees: (row.gatewayFees as unknown[]) ?? [],
			checkoutFees: (row.checkoutFees as unknown[]) ?? [],
			shippingFee: row.shippingFee ?? null,
			startDate: row.startDate,
			endDate: row.endDate,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: FeesConfiguration): typeof feesConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			gatewayFees: entity.gatewayFees,
			checkoutFees: entity.checkoutFees,
			shippingFee: entity.shippingFee,
			startDate: entity.startDate,
			endDate: entity.endDate,
			version: entity.version,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

@injectable()
export class MockFeesConfigurationRepository extends FeesConfigurationRepository {
	private rows = new Map<string, FeesConfiguration>()

	async findById(id: string, _tx?: Transaction): Promise<FeesConfiguration | undefined> {
		return this.rows.get(id)
	}

	async findActiveByStoreId(storeId: string, _tx?: Transaction): Promise<FeesConfiguration | undefined> {
		for (const f of this.rows.values()) {
			if (f.storeId.value === storeId && f.isActive) return f
		}
		return undefined
	}

	async save(entity: FeesConfiguration, _tx?: Transaction): Promise<FeesConfiguration> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: FeesConfiguration): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}

import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, doublePrecision, index } from 'drizzle-orm/pg-core'

/**
 * `finance` is BK Dash's BC8 Finance schema.
 *
 * All TS-owned merchant aggregates — no Go writes here. The Go-side
 * sync engine emits provider-reported amounts (gateway fees inline in
 * OrderTransaction, etc.); Finance owns the merchant-side
 * configuration that turns those amounts into profit margins.
 *
 * Tables:
 *   - `taxes`               — Store-scoped, time-effective tax regime
 *   - `fees_configuration`  — Store-scoped header + typed sub-fee
 *                             jsonb arrays (gateway / checkout / shipping)
 *   - `operational_costs`   — merchant cost ledger w/ status overrides
 *   - `warranty_reserves`   — % of revenue reserved per Store (time-effective)
 *   - `fx_rates`            — append-only, query by (from, to, startDate ≤ at)
 */
export const financeSchema = pgSchema('finance')

/**
 * `taxes` — one row per (storeId, startDate slice). `endDate` nullable
 * means "still effective". Queries pick the row matching
 * `startDate <= date AND (endDate IS NULL OR endDate > date)`.
 */
export const taxes = financeSchema.table(
	'taxes',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// TaxType enum (NONE | PRESUMED_PROFIT | REAL_PROFIT).
		type: text('type').notNull(),
		// TaxDeductionType enum (NONE | PRODUCT_COST | PRODUCT_COST_AND_MARKETING).
		deductionType: text('deduction_type').notNull(),

		// Effective tax rate as a fraction 0..1 (e.g. 0.085 = 8.5%). Stored
		// as double precision because tax calculations vary in precision
		// per jurisdiction and a fixed-point representation would force
		// us to pick a unit per market.
		rate: doublePrecision('rate').notNull(),

		// Spec §4 BC8 `Taxes` aggregate: per-Store profit multiplier
		// applied to revenue tax (e.g. 1.0 = neutral, 1.15 = 15% safety
		// buffer). Stored alongside `rate` to keep T25 reads to a single
		// SELECT. Default 1.0 = no multiplier so historical rows backfill
		// to a neutral value.
		revenueTaxMultiplier: doublePrecision('revenue_tax_multiplier').notNull().default(1.0),

		// Spec §4 BC8 + T25: per-platform marketing-tax overrides keyed by
		// MarketingPlatform (META | GOOGLE_ADS | TIKTOK). Empty map = no
		// per-platform overrides — fall back to `rate`. JSONB shape is
		// `Partial<Record<MarketingPlatform, number>>` per spec line 836.
		marketingTaxRatePerPlatform: jsonb('marketing_tax_rate_per_platform').notNull().default({}),

		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('taxes_store_id_idx').on(t.storeId),
		// Time-effective lookup index.
		storeStartDateIdx: index('taxes_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `fees_configuration` — single header row per Store with three typed
 * jsonb arrays of sub-fees:
 *
 *   - gateway_fees: GatewayFee[]
 *       { platform: PaymentGateway, paymentMethod: PaymentMethod,
 *         percentage: number, fixed: { amountCents, currency }[] }
 *   - checkout_fees: CheckoutFee[]
 *       { platform: CheckoutPlatform, rate: number }
 *   - shipping_fees: ShippingFee[]
 *       { type: ShippingCostType, value: ShippingCostValue }
 *
 * jsonb chosen over separate child tables because (a) read shape is
 * always "the full configuration for one Store", and (b) the
 * per-platform sub-shapes vary (e.g. ShippingCostValue is a 4-variant
 * discriminated union from spec — modeling it relationally would
 * require multiple child tables for a write that happens N×/year.)
 */
export const feesConfiguration = financeSchema.table(
	'fees_configuration',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		gatewayFees: jsonb('gateway_fees').notNull(),
		checkoutFees: jsonb('checkout_fees').notNull(),
		// Singular: the spec's FeesConfiguration carries one shipping
		// fee per row (matches the entity's `shippingFee` field).
		// Stored as a nullable jsonb so the "no shipping fee
		// configured yet" state encodes as JSON null.
		shippingFee: jsonb('shipping_fee'),

		// Spec §4 BC8 + C40: time-effective semantics matching `taxes`.
		// Multiple rows per Store; the active one has `endDate IS NULL`.
		// C40 closes the previous row's endDate and inserts a new one.
		// Default startDate = row insertion time (safe for historical
		// single-row data migrated forward — it becomes the first slice).
		startDate: timestamp('start_date', { withTimezone: true }).notNull().defaultNow(),
		endDate: timestamp('end_date', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Time-effective lookup: (storeId, startDate) replaces the previous
		// `(storeId) UNIQUE` constraint. Active-row lookup uses
		// `WHERE storeId = ? AND endDate IS NULL`.
		storeStartDateIdx: index('fees_configuration_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `operational_costs` — merchant cost ledger. Each row is one cost
 * line item with its own recurrence pattern. Occurrences are derived
 * at runtime (never stored); `status_overrides` is a jsonb array of
 * { occurrenceDate, status } holding only the per-occurrence deviations
 * from the default status (e.g. mark October's RENT as CANCELLED).
 */
export const operationalCosts = financeSchema.table(
	'operational_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Free-form merchant description ("November salary advance",
		// "Adobe CC", …). category is the enum classification.
		description: text('description').notNull(),
		category: text('category').notNull(),

		// OperationalCostFlow enum (CREDIT = money in | DEBIT = money out).
		// Entity always supplies it; migration backfills existing rows to DEBIT.
		flow: text('flow').notNull(),

		// OperationalCostRecurrency enum (ONCE | DAILY | WEEKLY | … |
		// YEARLY | NONE).
		recurrency: text('recurrency').notNull(),

		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// First occurrence date. For recurring costs the date implies
		// each future occurrence (e.g. MONTHLY starting Jan 15 →
		// Feb 15, Mar 15, …).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		// Optional terminator for recurring costs ("stop billing this
		// after X"); nullable = still recurring.
		endDate: timestamp('end_date', { withTimezone: true }),

		// jsonb array of { occurrenceDate, status } — only the per-occurrence
		// deviations from the default status, matching the OperationalCost
		// entity's statusOverrides shape verbatim. Status uses
		// OperationalCostPaymentStatus (PAID | UNPAID | OVERDUE | CANCELLED).
		statusOverrides: jsonb('status_overrides').notNull(),

		// Soft-delete timestamp. T27 ListOperationalCosts filters out
		// rows where this is non-null — the entity uses `deletedAt`
		// alone as the "is this row visible?" signal (no separate
		// `active` flag).
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('operational_costs_store_id_idx').on(t.storeId),
		categoryIdx: index('operational_costs_category_idx').on(t.category),
		// Date scans for analytics rollups.
		startDateIdx: index('operational_costs_start_date_idx').on(t.startDate),
	}),
)

/**
 * `warranty_reserves` — per-Store percentage of revenue reserved for
 * warranty claims. Time-effective (multiple rows per Store; queries
 * pick the row whose start_date ≤ now AND (end_date IS NULL OR
 * end_date > now)).
 */
export const warrantyReserves = financeSchema.table(
	'warranty_reserves',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Fraction 0..1 of revenue to reserve. Same precision rationale as
		// `taxes.rate`.
		rate: doublePrecision('rate').notNull(),

		// Spec § BC8 BC and the WarrantyReserve entity name the
		// time-effective window `effectiveFrom`/`effectiveTo` to
		// distinguish it from the soft-delete `deletedAt` timestamp.
		// (Taxes uses `start_date`/`end_date` because it has no soft
		// delete; reusing the same names here would conflate the two
		// audit dimensions.)
		effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
		effectiveTo: timestamp('effective_to', { withTimezone: true }),
		// Soft-delete timestamp. listByStoreId filters out rows where
		// this is non-null; the supersession path uses effectiveTo
		// (not deletedAt) so historical analytics keep the row
		// visible.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeEffectiveFromIdx: index('warranty_reserves_store_effective_from_idx').on(t.storeId, t.effectiveFrom),
	}),
)

/**
 * `fx_rates` — append-only currency conversion source of truth.
 *
 * Hourly CaptureFxRates cron emits rows from CURRENCY_API; merchants
 * may insert MANUAL overrides; providers may report rates inline
 * (PROVIDER_REPORTED, captured during transaction ingest).
 *
 * Queried with the canonical pattern:
 *   SELECT * FROM fx_rates
 *    WHERE from_currency = ? AND to_currency = ?
 *      AND start_date <= ?
 *    ORDER BY start_date DESC LIMIT 1
 *
 * The composite index on (from_currency, to_currency, start_date DESC)
 * makes that query a single-page seek.
 */
export const fxRates = financeSchema.table(
	'fx_rates',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		fromCurrency: text('from_currency').notNull(),
		toCurrency: text('to_currency').notNull(),

		// Conversion rate: 1 unit of fromCurrency = `rate` units of
		// toCurrency. Stored as `text` to preserve provider-side
		// decimal precision verbatim (e.g. '5.10' stays '5.10', not
		// coerced to 5.1). Queries never sort or aggregate on rate
		// (ORDER BY runs on start_date) so the lack of numeric
		// semantics is fine. The FxRate entity carries `rate: string`
		// matching this column.
		rate: text('rate').notNull(),

		// FxRateSource enum (CURRENCY_API | MANUAL | PROVIDER_REPORTED).
		source: text('source').notNull(),

		// When this rate became effective. Multiple rows may exist for
		// the same currency pair; queries pick the most recent ≤ desired
		// timestamp.
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		// Canonical query index — covers the "find rate at time T" path.
		pairStartDateIdx: index('fx_rates_pair_start_date_idx').on(t.fromCurrency, t.toCurrency, t.startDate),
		sourceIdx: index('fx_rates_source_idx').on(t.source),
	}),
)

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { UpdateFeesConfiguration } from './UpdateFeesConfiguration'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('FeesConfiguration (C40 Update)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let update: UpdateFeesConfiguration
	let repo: FeesConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		update = testBed.resolve(UpdateFeesConfiguration)
		repo = testBed.resolve(FeesConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(FeesConfigurationUpdatedEvent)
	}

	it('first UpdateFeesConfiguration materialises + emits event with previousFeesConfigurationId=null', async () => {
		const out = await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: 'STRIPE', rate: 0.029 }],
			checkoutFees: [{ platform: 'STRIPE', rate: 0.03 }],
			shippingFee: { type: 'FLAT', amountCents: 500 },
			effectiveFrom: new Date('2026-05-22T00:00:00.000Z'),
		})
		expect(out.feesConfigurationId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findActiveByStoreId(STORE)
		expect(saved?.gatewayFees).toEqual([{ platform: 'STRIPE', rate: 0.029 }])
		expect(saved?.shippingFee).toEqual({ type: 'FLAT', amountCents: 500 })

		const emitted = await readEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.previousFeesConfigurationId).toBeNull()
		expect(emitted[0]!.payload.feesConfiguration).toBeDefined()
		expect(emitted[0]!.payload.feesConfiguration.storeId).toBe(STORE)
	})

	it('second UpdateFeesConfiguration supersedes + carries forward non-supplied collections', async () => {
		const first = await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: 'STRIPE', rate: 0.029 }],
			checkoutFees: [{ platform: 'STRIPE', rate: 0.03 }],
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})
		const second = await update.execute({
			userId: USER,
			storeId: STORE,
			shippingFee: { type: 'FLAT', amountCents: 700 },
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const oldRow = await repo.findById(first.feesConfigurationId)
		expect(oldRow?.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		const newRow = await repo.findById(second.feesConfigurationId)
		expect(newRow?.endDate).toBeNull()
		expect(newRow?.gatewayFees).toEqual([{ platform: 'STRIPE', rate: 0.029 }]) // carried forward
		expect(newRow?.shippingFee).toEqual({ type: 'FLAT', amountCents: 700 })

		const emitted = await readEvents()
		expect(emitted[1]!.payload.previousFeesConfigurationId).toBe(first.feesConfigurationId)
		expect(emitted[1]!.payload.feesConfiguration).toBeDefined()
		expect(emitted[1]!.payload.feesConfiguration.storeId).toBe(STORE)
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

describe('DrizzleFeesConfigurationRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: FeesConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(FeesConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: {
		storeId?: string
		gatewayFees?: unknown[]
		checkoutFees?: unknown[]
		shippingFee?: unknown
		startDate?: Date
	}): FeesConfiguration {
		return FeesConfiguration.create({
			storeId: opts.storeId ?? STORE_A,
			gatewayFees: opts.gatewayFees,
			checkoutFees: opts.checkoutFees,
			shippingFee: opts.shippingFee,
			startDate: opts.startDate ?? new Date('2026-05-01T00:00:00.000Z'),
		})
	}

	describe('save + findById', () => {
		it('round-trips the 3 fee collections as jsonb verbatim', async () => {
			const entity = build({
