				],
				checkoutFees: [{ platform: 'CARTPANDA', rate: 0.015 }],
				shippingFee: { type: 'FIXED', value: { amountCents: 1500, currency: 'USD' } },
			})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.gatewayFees).toHaveLength(1)
			expect((fetched?.gatewayFees[0] as any).platform).toBe('STRIPE')
			expect(fetched?.checkoutFees).toHaveLength(1)
			expect((fetched?.checkoutFees[0] as any).rate).toBe(0.015)
			expect((fetched?.shippingFee as any).type).toBe('FIXED')
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})

		it('round-trips nullable shippingFee (iter 307 singular column rebuild)', async () => {
			const entity = build({})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.shippingFee).toBeNull()
		})

		it('UPSERT persists supersede() — endDate set + version bumped', async () => {
			const entity = build({ startDate: new Date('2026-04-01T00:00:00.000Z') })
			await repo.save(entity)

			entity.supersede(new Date('2026-05-01T00:00:00.000Z'))
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.endDate?.toISOString()).toBe('2026-05-01T00:00:00.000Z')
			expect(fetched?.version).toBeGreaterThan(1)
		})
	})

	describe('findActiveByStoreId', () => {
		it('returns undefined when no active row exists', async () => {
			const r = await repo.findActiveByStoreId(STORE_A)
			expect(r).toBeUndefined()
		})

		it('returns the row with endDate IS NULL', async () => {
			const superseded = build({ startDate: new Date('2026-04-01T00:00:00.000Z') })
			superseded.supersede(new Date('2026-05-01T00:00:00.000Z'))
			await repo.save(superseded)

			const active = build({ startDate: new Date('2026-05-01T00:00:00.000Z') })
			await repo.save(active)

			const r = await repo.findActiveByStoreId(STORE_A)
			expect(r?.id.value).toBe(active.id.value)
		})

		it('isolates by storeId', async () => {
			await repo.save(build({ storeId: STORE_A }))
			await repo.save(build({ storeId: STORE_B }))

			const a = await repo.findActiveByStoreId(STORE_A)
			const b = await repo.findActiveByStoreId(STORE_B)
			expect(a?.storeId.value).toBe(STORE_A)
			expect(b?.storeId.value).toBe(STORE_B)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
