import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { FeesConfiguration } from '../entities/FeesConfiguration'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

export const UpdateFeesConfigurationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	gatewayFees: z.array(z.unknown()).optional(),
	checkoutFees: z.array(z.unknown()).optional(),
	shippingFee: z.unknown().optional(),
	effectiveFrom: z.date(),
})

export const UpdateFeesConfigurationOutputSchema = z.object({
	feesConfigurationId: z.uuid(),
	effectiveFrom: z.date(),
})

/**
 * C40 UpdateFeesConfiguration. Time-effective insert covering the three
 * fee blocks. Mirrors the UpdateTaxes shape: supersede the active row,
 * insert a fresh one carrying forward non-supplied fee collections, and
 * emit FeesConfigurationUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateFeesConfiguration extends Handler<
	typeof UpdateFeesConfigurationInputSchema,
	typeof UpdateFeesConfigurationOutputSchema
> {
	readonly name = 'update_fees_configuration' as const
	readonly inputSchema = UpdateFeesConfigurationInputSchema
	readonly outputSchema = UpdateFeesConfigurationOutputSchema

	constructor(private readonly fees: FeesConfigurationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.fees.findActiveByStoreId(input.storeId, tx)

			const gatewayFees = input.gatewayFees ?? previous?.gatewayFees ?? []
			const checkoutFees = input.checkoutFees ?? previous?.checkoutFees ?? []
			const shippingFee = input.shippingFee !== undefined ? input.shippingFee : (previous?.shippingFee ?? null)

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.fees.save(previous, tx)
			}

			const fresh = FeesConfiguration.create({
				storeId: input.storeId,
				gatewayFees,
				checkoutFees,
				shippingFee,
				startDate: input.effectiveFrom,
			})
			await this.fees.save(fresh, tx)

			await this.domainEventRepository.save(
				new FeesConfigurationUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						feesConfiguration: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousFeesConfigurationId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { feesConfigurationId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

