import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { Timeline } from '../../shared/objects'
import { GatewayFeeSchema, CheckoutFeeSchema, ShippingFeeSchema } from '../objects'

type GatewayFeeEntry = Z.infer<typeof GatewayFeeSchema>
type CheckoutFeeEntry = Z.infer<typeof CheckoutFeeSchema>
type ShippingFeeEntry = Z.infer<typeof ShippingFeeSchema>

export const FeesConfigurationSchema = z.object({
	storeId: z.instance(Id),
	gatewayFees: z.array(GatewayFeeSchema).default([]),
	checkoutFee: z.array(CheckoutFeeSchema).default([]),
	shippingFee: z.array(ShippingFeeSchema).default([]),
})

export type FeesConfigurationProps = Z.infer<typeof FeesConfigurationSchema>

const gatewayKey = (f: GatewayFeeEntry) => `${f.platform}|${f.paymentMethod}`

/**
 * One row per Store. Each fee block is a time-effective series. Gateway fees
 * are a Timeline per (platform, paymentMethod) key; checkout and shipping are
 * single Timelines.
 *
 * NOTE: the place* methods intentionally depart from the push-style
 * collection-mutation convention. A Timeline is a last-write-wins interval
 * series, so mutation trims/splits/removes entries via Timeline.place rather
 * than appending an item and returning it (spec Decision 3).
 */
export class FeesConfiguration extends AggregateRoot<typeof FeesConfigurationSchema> {
	static override schema = FeesConfigurationSchema

	static create(data: { storeId: string }): FeesConfiguration {
		return new FeesConfiguration({ storeId: data.storeId, gatewayFees: [], checkoutFee: [], shippingFee: [] })
	}

	placeGatewayFee(fee: GatewayFeeEntry): void {
		const key = gatewayKey(fee)
		const sameKey = this.gatewayFees.filter(f => gatewayKey(f) === key)
		const others = this.gatewayFees.filter(f => gatewayKey(f) !== key)
		const painted = new Timeline<GatewayFeeEntry>(sameKey).place(fee)
		this.gatewayFees = [...others, ...painted.entries]
		this.validate()
	}

	placeCheckoutFee(fee: CheckoutFeeEntry): void {
		this.checkoutFee = [...new Timeline<CheckoutFeeEntry>(this.checkoutFee).place(fee).entries]
		this.validate()
	}

	placeShippingFee(fee: ShippingFeeEntry): void {
		this.shippingFee = [...new Timeline<ShippingFeeEntry>(this.shippingFee).place(fee).entries]
		this.validate()
	}
}

export interface FeesConfiguration extends FeesConfigurationProps {}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { PaymentGateway, PaymentMethod, CheckoutPlatform, ShippingCostMode } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'
import { FeesConfiguration } from '../entities/FeesConfiguration'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

export const GatewayFeeBodySchema = z.object({
	platform: z.enum(PaymentGateway),
	paymentMethod: z.enum(PaymentMethod),
	variable: z.number().min(0).max(1),
	fixed: MonetaryAmountSchema,
})
export const CheckoutFeeBodySchema = z.object({ platform: z.enum(CheckoutPlatform), rate: z.number().min(0).max(1) })
export const ShippingFeeBodySchema = z.discriminatedUnion('mode', [
	z.object({ mode: z.literal(ShippingCostMode.NONE) }),
	z.object({ mode: z.literal(ShippingCostMode.PAID_BY_CUSTOMER_AT_CHECKOUT) }),
	z.object({ mode: z.literal(ShippingCostMode.AVERAGE_PER_SALE), value: MonetaryAmountSchema }),
	z.object({ mode: z.literal(ShippingCostMode.BY_PRODUCT_QUANTITY), value: MonetaryAmountSchema }),
])

export const UpdateFeesConfigurationInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	gatewayFees: z.array(GatewayFeeBodySchema).optional(),
	checkoutFee: CheckoutFeeBodySchema.optional(),
	shippingFee: ShippingFeeBodySchema.optional(),
	effectiveFrom: z.date(),
})

export const UpdateFeesConfigurationOutputSchema = z.object({ feesConfigurationId: z.uuid(), effectiveFrom: z.date() })

/**
 * UpdateFeesConfiguration. Find-or-create the store's single
 * FeesConfiguration row, then place each supplied fee block onto its
 * Timeline. Emits FeesConfigurationUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateFeesConfiguration extends Handler<
	typeof UpdateFeesConfigurationInputSchema,
	typeof UpdateFeesConfigurationOutputSchema
> {
	readonly name = 'update_fees_configuration' as const
	readonly inputSchema = UpdateFeesConfigurationInputSchema
	readonly outputSchema = UpdateFeesConfigurationOutputSchema

	constructor(private readonly fees: FeesConfigurationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const fc = (await this.fees.findByStoreId(input.storeId, tx)) ?? FeesConfiguration.create({ storeId: input.storeId })
			const at = { startDate: input.effectiveFrom, endDate: null as Date | null }
			for (const g of input.gatewayFees ?? []) fc.placeGatewayFee({ ...g, ...at })
			if (input.checkoutFee) fc.placeCheckoutFee({ ...input.checkoutFee, ...at })
			if (input.shippingFee) fc.placeShippingFee({ ...input.shippingFee, ...at })
			await this.fees.save(fc, tx)
			await this.domainEventRepository.save(
				new FeesConfigurationUpdatedEvent({
					entityId: fc.id.value,
					ownerId: input.storeId,
					payload: { feesConfiguration: fc.toJSON(), effectiveStartDate: input.effectiveFrom, previousFeesConfigurationId: null },
				}),
				tx,
			)
			return { feesConfigurationId: fc.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { feesConfiguration } from '@bk-dash/contracts/db'
import { FeesConfiguration } from '../../entities/FeesConfiguration'
import { FeesConfigurationRepository } from './FeesConfigurationRepository'

/**
 * Drizzle-backed FeesConfigurationRepository.
 *
 * One row per Store (UNIQUE on store_id). The three fee collections are
 * embedded jsonb timeline arrays — `z.coerce.date()` in the entity
 * schema rehydrates stored ISO strings back to Date on read, so
 * `toDomain` passes raw jsonb straight through `new FeesConfiguration`.
 *
 * `save` upserts on `id` (the aggregate's own PK) so a second call on
 * the same entity updates rather than inserts. The unique index on
 * `store_id` is the DB-level guard that enforces one-row-per-store.
 */
@injectable()
export class DrizzleFeesConfigurationRepository extends FeesConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<FeesConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(feesConfiguration).where(eq(feesConfiguration.storeId, storeId)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: FeesConfiguration, tx?: DrizzleClient): Promise<FeesConfiguration> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(feesConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: feesConfiguration.id,
					set: {
						storeId: data.storeId,
						gatewayFees: data.gatewayFees,
						checkoutFee: data.checkoutFee,
						shippingFee: data.shippingFee,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(feesConfiguration).where(eq(feesConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof feesConfiguration.$inferSelect): FeesConfiguration {
		// z.coerce.date() in GatewayFeeSchema / CheckoutFeeSchema / ShippingFeeSchema
		// converts stored ISO strings back to Date objects during entity validation.
		return new FeesConfiguration({
			id: row.id,
			storeId: row.storeId,
			gatewayFees: (row.gatewayFees as unknown[]) ?? [],
			checkoutFee: (row.checkoutFee as unknown[]) ?? [],
			shippingFee: (row.shippingFee as unknown[]) ?? [],
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: FeesConfiguration): typeof feesConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			gatewayFees: entity.gatewayFees,
			checkoutFee: entity.checkoutFee,
			shippingFee: entity.shippingFee,
			version: entity.version,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { MarketingPlatform, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from '../entities/Taxes'
import { TaxesRepository } from '../repositories/TaxesRepository'
import { TaxesUpdatedEvent } from '../events'

export const UpdateTaxesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	revenueTaxType: z.enum(TaxType).optional(),
	revenueTaxDeductionType: z.enum(TaxDeductionType).optional(),
	/** Effective rate as a 0..100 percentage. Persisted as 0..1 fraction. */
	revenueTaxRate: z.number().min(0).max(100).optional(),
	revenueTaxMultiplier: z.number().min(0).optional(),
	marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).optional(),
	effectiveFrom: z.date(),
})

export const UpdateTaxesOutputSchema = z.object({
	taxesId: z.uuid(),
	effectiveFrom: z.date(),
})

/**
 * C39 UpdateTaxes. Time-effective insert: opens a new row with the
 * supplied effectiveFrom + any patched fields (carrying defaults forward
 * from the previously-active row when present), and supersedes the
 * previous row by stamping its endDate with the new effectiveFrom.
 *
 * The supersession + insert are persisted in a single transaction so
 * reads always see exactly one active row per store.
 */
@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxes: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.taxes.findActiveByStoreId(input.storeId, tx)

			const type = input.revenueTaxType ?? previous?.type ?? TaxType.NONE
			const deductionType = input.revenueTaxDeductionType ?? previous?.deductionType ?? TaxDeductionType.NONE
			const ratePct = input.revenueTaxRate ?? (previous ? previous.rate * 100 : 0)
			const rate = ratePct / 100
			const revenueTaxMultiplier = input.revenueTaxMultiplier ?? previous?.revenueTaxMultiplier ?? 1.0
			const marketingTaxRatePerPlatform = input.marketingTaxRatePerPlatform ?? previous?.marketingTaxRatePerPlatform ?? {}

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.taxes.save(previous, tx)
			}

			const fresh = Taxes.create({
				storeId: input.storeId,
				type,
				deductionType,
				rate,
				revenueTaxMultiplier,
				marketingTaxRatePerPlatform,
				startDate: input.effectiveFrom,
			})
			await this.taxes.save(fresh, tx)

			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						taxes: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousTaxesId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { taxesId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import type { FinanceDomainErrors } from '../errors'

export const TaxesSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(TaxType),
	deductionType: z.enum(TaxDeductionType),
	rate: z.number().min(0).max(1),
	revenueTaxMultiplier: z.number().min(0).default(1.0),
	marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).default({}),
	startDate: z.date(),
	endDate: z.date().nullable(),
})

export type TaxesProps = Z.infer<typeof TaxesSchema>

/**
 * `Taxes` aggregate per spec § BC8 Finance. Per-Store time-effective
 * tax configuration. `startDate` is when this row takes effect;
 * `endDate` is null while the row is the current active one and gets
 * stamped with the next row's `startDate` when superseded.
 *
 * `rate` is stored as a 0..1 fraction (controller exposes 0..100 %).
 */
export class Taxes extends AggregateRoot<typeof TaxesSchema> {
	static override schema = TaxesSchema

	static create(data: {
		storeId: string
		type: TaxType
		deductionType: TaxDeductionType
		rate: number
		revenueTaxMultiplier?: number
		marketingTaxRatePerPlatform?: Partial<Record<MarketingPlatform, number>>
		startDate: Date
	}): Taxes {
		return new Taxes({
			storeId: data.storeId,
			type: data.type,
			deductionType: data.deductionType,
			rate: data.rate,
			revenueTaxMultiplier: data.revenueTaxMultiplier ?? 1.0,
			marketingTaxRatePerPlatform: data.marketingTaxRatePerPlatform ?? {},
			startDate: data.startDate,
			endDate: null,
		})
	}

	/** Closes this row by stamping its `endDate` with the supersession instant. Refuses re-supersession. */
	supersede(at: Date): void {
		if (this.endDate !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'Taxes row already superseded')
		}
		if (at <= this.startDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'supersession instant must be after startDate')
		}
		this.endDate = at
		this.validate()
	}

	get isActive(): boolean {
		return this.endDate === null
	}
}

export interface Taxes extends TaxesProps {}

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { MarketingPlatform, Role, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { RequireStoreRole } from '@tenancy/middlewares/RequireStoreRole'
import { UpdateTaxes, UpdateTaxesOutputSchema } from '../usecases/UpdateTaxes'

export const UpdateTaxesControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
		membership: z.object({ storeId: z.uuid() }),
	}),
	body: z.object({
		revenueTaxType: z.enum(TaxType).optional(),
		revenueTaxDeductionType: z.enum(TaxDeductionType).optional(),
		revenueTaxRate: z.number().min(0).max(100).optional(),
		revenueTaxMultiplier: z.number().min(0).optional(),
		marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).optional(),
		effectiveFrom: z.stringToDate(),
	}),
})

export const UpdateTaxesControllerOutputSchema = UpdateTaxesOutputSchema

@injectable()
export class UpdateTaxesController extends Controller<typeof UpdateTaxesControllerInputSchema, typeof UpdateTaxesControllerOutputSchema> {
	readonly path = '/taxes-settings'
	readonly method = 'put' as const
	readonly description = 'Update Taxes configuration; appends a new time-effective row (C39 UpdateTaxes)'
	readonly inputSchema = UpdateTaxesControllerInputSchema
	readonly outputSchema = UpdateTaxesControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private cmd: UpdateTaxes) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.membership.storeId,
			revenueTaxType: request.body.revenueTaxType,
			revenueTaxDeductionType: request.body.revenueTaxDeductionType,
			revenueTaxRate: request.body.revenueTaxRate,
			revenueTaxMultiplier: request.body.revenueTaxMultiplier,
			marketingTaxRatePerPlatform: request.body.marketingTaxRatePerPlatform,
			effectiveFrom: request.body.effectiveFrom,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

