	placeGatewayFee(input: { platform: PaymentGateway; paymentMethod: PaymentMethod } & GatewayFeeRateEntry): void {
		const { platform, paymentMethod, ...rate } = input
		const container = this.gatewayFees.find(g => g.platform === platform)
		const painted = new Timeline<GatewayFeeRateEntry>(container?.methods[paymentMethod] ?? []).place(rate)
		const methods = { ...(container?.methods ?? {}), [paymentMethod]: [...painted.entries] }
		this.gatewayFees = container
			? this.gatewayFees.map(g => (g.platform === platform ? { platform, methods } : g))
			: [...this.gatewayFees, { platform, methods }]
		this.validate()
	}

	placeCheckoutFee(fee: CheckoutFeeEntry): void {
		this.checkoutFee = [...new Timeline<CheckoutFeeEntry>(this.checkoutFee).place(fee).entries]
		this.validate()
