import { describe, it, expect } from 'bun:test'
import { CurrencyCode, PaymentGateway, PaymentMethod, CheckoutPlatform, ShippingCostMode } from '@bk-dash/contracts-typescript/wire/enums'
import { FeesConfiguration } from './FeesConfiguration'

const gw = (
	variable: number,
	s: Date,
	e: Date | null,
	platform = PaymentGateway.STRIPE,
	method = PaymentMethod.CREDIT_CARD,
) => ({
	platform,
	paymentMethod: method,
	variable,
	fixed: { amountCents: 30, currency: CurrencyCode.USD },
	startDate: s,
	endDate: e,
})
// leaf timeline for a (platform, method) key
const rates = (fc: FeesConfiguration, platform: PaymentGateway, method: PaymentMethod) =>
	fc.gatewayFees.find(g => g.platform === platform)?.methods[method] ?? []

describe('FeesConfiguration', () => {
	it('places a gateway fee onto its (platform,method) leaf timeline', () => {
		const fc = FeesConfiguration.create({ storeId: 'store-1' })
		fc.placeGatewayFee(gw(0.029, new Date('2026-01-01'), null))
		expect(fc.gatewayFees).toHaveLength(1) // one platform container
		expect(rates(fc, PaymentGateway.STRIPE, PaymentMethod.CREDIT_CARD)).toHaveLength(1)
	})

	it('superseding one gateway key never cuts another key', () => {
		const fc = FeesConfiguration.create({ storeId: 'store-1' })
		fc.placeGatewayFee(gw(0.029, new Date('2026-01-01'), null))
		fc.placeGatewayFee(gw(0.015, new Date('2026-01-01'), null, PaymentGateway.PAYPAL, PaymentMethod.PIX))
		// paint a new STRIPE/CREDIT_CARD fee from 2026-06-01 → trims that leaf only
		fc.placeGatewayFee(gw(0.031, new Date('2026-06-01'), null))
		expect(rates(fc, PaymentGateway.STRIPE, PaymentMethod.CREDIT_CARD)).toHaveLength(2) // trimmed + new
		expect(rates(fc, PaymentGateway.PAYPAL, PaymentMethod.PIX)).toHaveLength(1) // untouched
	})

	it('checkout and shipping are single timelines', () => {
		const fc = FeesConfiguration.create({ storeId: 'store-1' })
		fc.placeCheckoutFee({ platform: CheckoutPlatform.YAMPI, rate: 0.02, startDate: new Date('2026-01-01'), endDate: null })
		fc.placeShippingFee({
			mode: ShippingCostMode.AVERAGE_PER_SALE,
			value: { amountCents: 1500, currency: CurrencyCode.BRL },
			startDate: new Date('2026-01-01'),
			endDate: null,
		})
		expect(fc.checkoutFee).toHaveLength(1)
		expect(fc.shippingFee).toHaveLength(1)
	})
})

