import { BaseDomainEvent, z } from '@bk-dash/core-typescript'
import { FeesConfigurationSchema } from '../entities/FeesConfiguration'

export const FeesConfigurationUpdatedEventSchema = z.domainEvent({
	feesConfiguration: FeesConfigurationSchema.input(),
	effectiveStartDate: z.date(),
	previousFeesConfigurationId: z.uuid().nullable(),
})

export class FeesConfigurationUpdatedEvent extends BaseDomainEvent<typeof FeesConfigurationUpdatedEventSchema> {
	static override readonly name = 'finance.fees_configuration.updated' as const
	static readonly schema = FeesConfigurationUpdatedEventSchema
}

import { z } from '@bk-dash/core-typescript'
import type Z from 'zod'
import { PaymentGateway, PaymentMethod } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'

// Keys are structural, only the value is historical: the (platform, method)
// identity stays OUTSIDE the window; the changing {variable, fixed} is the
// leaf timeline value.
export const GatewayFeeRateSchema = z.historical({
	/** Variable fee as a 0..1 fraction of transaction amount. */
	variable: z.number().min(0).max(1),
	/** Flat per-transaction fee (currency + value). */
	fixed: MonetaryAmountSchema,
})
export type GatewayFeeRate = Z.infer<typeof GatewayFeeRateSchema>

export const GatewayFeeSchema = z.object({
	platform: z.enum(PaymentGateway),
	/** Per payment method: a Timeline (array) of windowed {variable, fixed} values. */
	methods: z.partialRecord(z.enum(PaymentMethod), z.array(GatewayFeeRateSchema)),
})
export type GatewayFee = Z.infer<typeof GatewayFeeSchema>

