	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(FeesConfigurationUpdatedEvent)
	}

	it('first UpdateFeesConfiguration materialises + emits event with previousFeesConfigurationId=null', async () => {
		const out = await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: 'STRIPE', rate: 0.029 }],
			checkoutFees: [{ platform: 'STRIPE', rate: 0.03 }],
			shippingFee: { type: 'FLAT', amountCents: 500 },
			effectiveFrom: new Date('2026-05-22T00:00:00.000Z'),
		})
		expect(out.feesConfigurationId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findActiveByStoreId(STORE)
		expect(saved?.gatewayFees).toEqual([{ platform: 'STRIPE', rate: 0.029 }])
		expect(saved?.shippingFee).toEqual({ type: 'FLAT', amountCents: 500 })

		const emitted = await readEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.previousFeesConfigurationId).toBeNull()
		expect(emitted[0]!.payload.feesConfiguration).toBeDefined()
		expect(emitted[0]!.payload.feesConfiguration.storeId).toBe(STORE)
	})

	it('second UpdateFeesConfiguration supersedes + carries forward non-supplied collections', async () => {
		const first = await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: 'STRIPE', rate: 0.029 }],
			checkoutFees: [{ platform: 'STRIPE', rate: 0.03 }],
