		})
		const second = await update.execute({
			userId: USER,
			storeId: STORE,
			shippingFee: { type: 'FLAT', amountCents: 700 },
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const oldRow = await repo.findById(first.feesConfigurationId)
		expect(oldRow?.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		const newRow = await repo.findById(second.feesConfigurationId)
		expect(newRow?.endDate).toBeNull()
		expect(newRow?.gatewayFees).toEqual([{ platform: 'STRIPE', rate: 0.029 }]) // carried forward
		expect(newRow?.shippingFee).toEqual({ type: 'FLAT', amountCents: 700 })

		const emitted = await readEvents()
		expect(emitted[1]!.payload.previousFeesConfigurationId).toBe(first.feesConfigurationId)
		expect(emitted[1]!.payload.feesConfiguration).toBeDefined()
		expect(emitted[1]!.payload.feesConfiguration.storeId).toBe(STORE)
	})
})

