import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import {
	UpdateFeesConfiguration,
	UpdateFeesConfigurationOutputSchema,
	GatewayFeeBodySchema,
	CheckoutFeeBodySchema,
	ShippingFeeBodySchema,
} from '../usecases/UpdateFeesConfiguration'

export const UpdateFeesConfigurationControllerInputSchema = z.object({
	ctx: z.object({ user: z.object({ id: z.string() }), membership: z.object({ storeId: z.uuid() }) }),
	body: z.object({
		gatewayFees: z.array(GatewayFeeBodySchema).optional(),
		checkoutFee: CheckoutFeeBodySchema.optional(),
		shippingFee: ShippingFeeBodySchema.optional(),
		effectiveFrom: z.stringToDate(),
	}),
})

export const UpdateFeesConfigurationControllerOutputSchema = UpdateFeesConfigurationOutputSchema

@injectable()
export class UpdateFeesConfigurationController extends Controller<
	typeof UpdateFeesConfigurationControllerInputSchema,
	typeof UpdateFeesConfigurationControllerOutputSchema
> {
	readonly path = '/fees-configuration'
	readonly method = 'put' as const
	readonly description = 'Update FeesConfiguration; time-effective insert via Timeline.place (C40)'
	readonly inputSchema = UpdateFeesConfigurationControllerInputSchema
	readonly outputSchema = UpdateFeesConfigurationControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember]

	constructor(private cmd: UpdateFeesConfiguration) {
		super()
	}

