import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { PaymentGateway, PaymentMethod, CheckoutPlatform, ShippingCostMode } from '@bk-dash/contracts-typescript/wire/enums'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateFeesConfiguration } from './UpdateFeesConfiguration'
import { FeesConfigurationRepository } from '../repositories/FeesConfigurationRepository'
import { FeesConfigurationUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

const FIXED = { amountCents: 30, currency: CurrencyCode.USD }

describe('FeesConfiguration (C40 UpdateFeesConfiguration)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let update: UpdateFeesConfiguration
	let repo: FeesConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		update = testBed.resolve(UpdateFeesConfiguration)
		repo = testBed.resolve(FeesConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readEvents() {
		return testBed.resolve(DomainEventRepository).findByType(FeesConfigurationUpdatedEvent)
	}

	it('AC-11/AC-14 gateway per-(platform,method)-key timeline isolation', async () => {
		// Place STRIPE/CREDIT_CARD fee from 2026-01-01 (open-ended)
		await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: PaymentGateway.STRIPE, paymentMethod: PaymentMethod.CREDIT_CARD, variable: 0.029, fixed: FIXED }],
			effectiveFrom: new Date('2026-01-01T00:00:00.000Z'),
		})

		// Place PAYPAL/PIX fee from 2026-03-01 (between the two STRIPE dates)
		await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: PaymentGateway.PAYPAL, paymentMethod: PaymentMethod.PIX, variable: 0.015, fixed: FIXED }],
			effectiveFrom: new Date('2026-03-01T00:00:00.000Z'),
		})

		// Place another STRIPE/CREDIT_CARD fee from 2026-06-01 — should trim the first STRIPE entry
		await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: PaymentGateway.STRIPE, paymentMethod: PaymentMethod.CREDIT_CARD, variable: 0.031, fixed: FIXED }],
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const fc = await repo.findByStoreId(STORE)
		expect(fc).toBeDefined()

		// STRIPE/CREDIT_CARD timeline must have 2 entries: first trimmed to end 2026-06-01, second open-ended
		const stripeContainer = fc!.gatewayFees.find(g => g.platform === PaymentGateway.STRIPE)
		expect(stripeContainer).toBeDefined()
		const stripeCcEntries = stripeContainer!.methods[PaymentMethod.CREDIT_CARD]
		expect(stripeCcEntries).toHaveLength(2)
		// First entry trimmed: endDate = 2026-06-01
		expect(stripeCcEntries![0]!.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		expect(stripeCcEntries![0]!.variable).toBeCloseTo(0.029)
		// Second entry: open-ended
		expect(stripeCcEntries![1]!.endDate).toBeNull()
		expect(stripeCcEntries![1]!.variable).toBeCloseTo(0.031)

		// PAYPAL/PIX must be untouched (1 entry)
		const paypalContainer = fc!.gatewayFees.find(g => g.platform === PaymentGateway.PAYPAL)
		expect(paypalContainer).toBeDefined()
		const paypalPixEntries = paypalContainer!.methods[PaymentMethod.PIX]
		expect(paypalPixEntries).toHaveLength(1)
		expect(paypalPixEntries![0]!.variable).toBeCloseTo(0.015)
	})

	it('AC-14 checkout single timeline supersedes on second placement', async () => {
		// First checkout fee
		await update.execute({
			userId: USER,
			storeId: STORE,
			checkoutFee: { platform: CheckoutPlatform.YAMPI, rate: 0.02 },
			effectiveFrom: new Date('2026-01-01T00:00:00.000Z'),
		})

		// Second checkout fee — same platform, supersedes (open-ended paint trims first)
		await update.execute({
			userId: USER,
			storeId: STORE,
			checkoutFee: { platform: CheckoutPlatform.YAMPI, rate: 0.025 },
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const fc = await repo.findByStoreId(STORE)
		expect(fc).toBeDefined()
		// Single timeline: 2 entries (first trimmed, second open-ended)
		expect(fc!.checkoutFee).toHaveLength(2)
		expect(fc!.checkoutFee[0]!.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		expect(fc!.checkoutFee[1]!.endDate).toBeNull()
		expect(fc!.checkoutFee[1]!.rate).toBeCloseTo(0.025)
	})

	it('AC-11 shipping AVERAGE_PER_SALE places one entry on the timeline', async () => {
		await update.execute({
			userId: USER,
			storeId: STORE,
			shippingFee: { mode: ShippingCostMode.AVERAGE_PER_SALE, value: { amountCents: 1500, currency: CurrencyCode.BRL } },
			effectiveFrom: new Date('2026-01-01T00:00:00.000Z'),
		})

		const fc = await repo.findByStoreId(STORE)
		expect(fc).toBeDefined()
		expect(fc!.shippingFee).toHaveLength(1)
		expect(fc!.shippingFee[0]!.endDate).toBeNull()
		// @ts-ignore — mode discriminant
		expect(fc!.shippingFee[0]!.mode).toBe(ShippingCostMode.AVERAGE_PER_SALE)
	})

	it('emits FeesConfigurationUpdatedEvent on each update', async () => {
		await update.execute({
			userId: USER,
			storeId: STORE,
			gatewayFees: [{ platform: PaymentGateway.STRIPE, paymentMethod: PaymentMethod.CREDIT_CARD, variable: 0.029, fixed: FIXED }],
			effectiveFrom: new Date('2026-01-01T00:00:00.000Z'),
		})

		const events = await readEvents()
		expect(events).toHaveLength(1)
		expect(events[0]!.payload.previousFeesConfigurationId).toBeNull()
		expect(events[0]!.payload.feesConfiguration).toBeDefined()
		expect(events[0]!.payload.effectiveStartDate).toEqual(new Date('2026-01-01T00:00:00.000Z'))
	})
})

