export const GatewayFeeBodySchema = z.object({

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import type { FinanceDomainErrors } from '../errors'

export const TaxesSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(TaxType),
	deductionType: z.enum(TaxDeductionType),
	rate: z.number().min(0).max(1),
	revenueTaxMultiplier: z.number().min(0).default(1.0),
	marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).default({}),
	startDate: z.date(),
	endDate: z.date().nullable(),
})

export type TaxesProps = Z.infer<typeof TaxesSchema>

/**
 * `Taxes` aggregate per spec § BC8 Finance. Per-Store time-effective
 * tax configuration. `startDate` is when this row takes effect;
 * `endDate` is null while the row is the current active one and gets
 * stamped with the next row's `startDate` when superseded.
 *
 * `rate` is stored as a 0..1 fraction (controller exposes 0..100 %).
 */
export class Taxes extends AggregateRoot<typeof TaxesSchema> {
	static override schema = TaxesSchema

	static create(data: {
		storeId: string
		type: TaxType
		deductionType: TaxDeductionType
		rate: number
		revenueTaxMultiplier?: number
		marketingTaxRatePerPlatform?: Partial<Record<MarketingPlatform, number>>
		startDate: Date
	}): Taxes {
		return new Taxes({
			storeId: data.storeId,
			type: data.type,
			deductionType: data.deductionType,
			rate: data.rate,
			revenueTaxMultiplier: data.revenueTaxMultiplier ?? 1.0,
			marketingTaxRatePerPlatform: data.marketingTaxRatePerPlatform ?? {},
			startDate: data.startDate,
			endDate: null,
		})
	}

	/** Closes this row by stamping its `endDate` with the supersession instant. Refuses re-supersession. */
	supersede(at: Date): void {
		if (this.endDate !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'Taxes row already superseded')
		}
		if (at <= this.startDate) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'supersession instant must be after startDate')
		}
		this.endDate = at
		this.validate()
	}

	get isActive(): boolean {
		return this.endDate === null
	}
}

