export const TaxesUpdatedEventSchema = z.domainEvent({
	taxes: TaxesSchema.input(),
	effectiveStartDate: z.date(),
	previousTaxesId: z.uuid().nullable(),
})

export class TaxesUpdatedEvent extends BaseDomainEvent<typeof TaxesUpdatedEventSchema> {
	static override readonly name = 'finance.taxes.updated' as const
	static readonly schema = TaxesUpdatedEventSchema
}

import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, doublePrecision, index, uniqueIndex } from 'drizzle-orm/pg-core'

/**
 * `finance` is BK Dash's BC8 Finance schema.
 *
 * All TS-owned merchant aggregates — no Go writes here. The Go-side
 * sync engine emits provider-reported amounts (gateway fees inline in
 * OrderTransaction, etc.); Finance owns the merchant-side
 * configuration that turns those amounts into profit margins.
 *
 * Tables:
 *   - `taxes`               — Store-scoped, time-effective tax regime
 *   - `fees_configuration`  — Store-scoped header + typed sub-fee
 *                             jsonb arrays (gateway / checkout / shipping)
 *   - `operational_costs`   — merchant cost ledger w/ status overrides
 *   - `warranty_reserves`   — % of revenue reserved per Store (time-effective)
 *   - `fx_rates`            — append-only, query by (from, to, startDate ≤ at)
 */
export const financeSchema = pgSchema('finance')

/**
 * `taxes` — one row per (storeId, startDate slice). `endDate` nullable
 * means "still effective". Queries pick the row matching
 * `startDate <= date AND (endDate IS NULL OR endDate > date)`.
 */
export const taxes = financeSchema.table(
	'taxes',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// TaxType enum (NONE | PRESUMED_PROFIT | REAL_PROFIT).
		type: text('type').notNull(),
		// TaxDeductionType enum (NONE | PRODUCT_COST | PRODUCT_COST_AND_MARKETING).
		deductionType: text('deduction_type').notNull(),

		// Effective tax rate as a fraction 0..1 (e.g. 0.085 = 8.5%). Stored
		// as double precision because tax calculations vary in precision
		// per jurisdiction and a fixed-point representation would force
		// us to pick a unit per market.
		rate: doublePrecision('rate').notNull(),

		// Spec §4 BC8 `Taxes` aggregate: per-Store profit multiplier
		// applied to revenue tax (e.g. 1.0 = neutral, 1.15 = 15% safety
		// buffer). Stored alongside `rate` to keep T25 reads to a single
		// SELECT. Default 1.0 = no multiplier so historical rows backfill
		// to a neutral value.
		revenueTaxMultiplier: doublePrecision('revenue_tax_multiplier').notNull().default(1.0),

		// Spec §4 BC8 + T25: per-platform marketing-tax overrides keyed by
		// MarketingPlatform (META | GOOGLE_ADS | TIKTOK). Empty map = no
		// per-platform overrides — fall back to `rate`. JSONB shape is
		// `Partial<Record<MarketingPlatform, number>>` per spec line 836.
		marketingTaxRatePerPlatform: jsonb('marketing_tax_rate_per_platform').notNull().default({}),

		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		endDate: timestamp('end_date', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('taxes_store_id_idx').on(t.storeId),
		// Time-effective lookup index.
		storeStartDateIdx: index('taxes_store_start_date_idx').on(t.storeId, t.startDate),
	}),
)

/**
 * `fees_configuration` — one row per Store (unique on store_id) with three
 * typed jsonb arrays of sub-fees embedding per-key timelines:
 *
 *   - gateway_fees: GatewayFee[]
 *       { platform: PaymentGateway, methods: Partial<Record<PaymentMethod,
 *         GatewayFeeRate[]>> } where GatewayFeeRate = { variable, fixed,
 *         startDate, endDate } — keys structural, only values historical.
 *   - checkout_fee: CheckoutFee[]
 *       Array is a Timeline<CheckoutFee> = [{ platform, rate, startDate, endDate }, ...]
 *   - shipping_fee: ShippingFee[]
 *       Array is a Timeline<ShippingFee>; each entry is a discriminated
 *       union keyed by ShippingCostMode (NONE | AVERAGE_PER_SALE |
 *       PAID_BY_CUSTOMER_AT_CHECKOUT | BY_PRODUCT_QUANTITY) plus a
 *       { startDate, endDate } window from z.historical.
 *
 * jsonb chosen over separate child tables because (a) read shape is
 * always "the full configuration for one Store", and (b) the
 * per-platform sub-shapes vary — modeling them relationally would
 * require multiple child tables for a write that happens N×/year.
 *
 * The row-level start_date / end_date time-effective pattern has been
 * replaced by the embedded Timeline arrays above (Task T6).
 */
export const feesConfiguration = financeSchema.table(
	'fees_configuration',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// GatewayFee[] — one container per platform with per-method leaf timelines.
		gatewayFees: jsonb('gateway_fees').notNull().default([]),
		// CheckoutFee[] — whole-value Timeline; entries carry {startDate, endDate}.
		checkoutFee: jsonb('checkout_fee').notNull().default([]),
		// ShippingFee[] — whole-value Timeline; discriminated by ShippingCostMode.
		shippingFee: jsonb('shipping_fee').notNull().default([]),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// One row per Store — unique constraint replaces the old time-effective
		// multi-row pattern (Task T6: row-level start/end_date dropped).
		storeIdx: uniqueIndex('fees_configuration_store_id_idx').on(t.storeId),
	}),
)

/**
 * `operational_costs` — merchant cost ledger. Each row is one cost
 * line item with its own recurrence pattern. Occurrences are derived
 * at runtime (never stored); `status_overrides` is a jsonb array of
 * { occurrenceDate, status } holding only the per-occurrence deviations
 * from the default status (e.g. mark October's RENT as CANCELLED).
 */
export const operationalCosts = financeSchema.table(
	'operational_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Free-form merchant description ("November salary advance",
		// "Adobe CC", …). category is the enum classification.
		description: text('description').notNull(),
		category: text('category').notNull(),

		// OperationalCostFlow enum (CREDIT = money in | DEBIT = money out).
		// Entity always supplies it; migration backfills existing rows to DEBIT.
		flow: text('flow').notNull(),

		// OperationalCostRecurrency enum (ONCE | DAILY | WEEKLY | … |
		// YEARLY | NONE).
		recurrency: text('recurrency').notNull(),

		amountCents: bigint('amount_cents', { mode: 'bigint' }).notNull(),
		currency: text('currency').notNull(),

		// First occurrence date. For recurring costs the date implies
		// each future occurrence (e.g. MONTHLY starting Jan 15 →
		// Feb 15, Mar 15, …).
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),
		// Optional terminator for recurring costs ("stop billing this
		// after X"); nullable = still recurring.
		endDate: timestamp('end_date', { withTimezone: true }),

		// jsonb array of { occurrenceDate, status } — only the per-occurrence
		// deviations from the default status, matching the OperationalCost
		// entity's statusOverrides shape verbatim. Status uses
		// OperationalCostPaymentStatus (PAID | UNPAID | OVERDUE | CANCELLED).
		statusOverrides: jsonb('status_overrides').notNull(),

		// Soft-delete timestamp. T27 ListOperationalCosts filters out
		// rows where this is non-null — the entity uses `deletedAt`
		// alone as the "is this row visible?" signal (no separate
		// `active` flag).
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeIdx: index('operational_costs_store_id_idx').on(t.storeId),
		categoryIdx: index('operational_costs_category_idx').on(t.category),
		// Date scans for analytics rollups.
		startDateIdx: index('operational_costs_start_date_idx').on(t.startDate),
	}),
)

/**
 * `warranty_reserves` — per-Store percentage of revenue reserved for
 * warranty claims. Time-effective (multiple rows per Store; queries
 * pick the row whose start_date ≤ now AND (end_date IS NULL OR
 * end_date > now)).
 */
export const warrantyReserves = financeSchema.table(
	'warranty_reserves',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),

		// Fraction 0..1 of revenue to reserve. Same precision rationale as
		// `taxes.rate`.
		rate: doublePrecision('rate').notNull(),

		// Spec § BC8 BC and the WarrantyReserve entity name the
		// time-effective window `effectiveFrom`/`effectiveTo` to
		// distinguish it from the soft-delete `deletedAt` timestamp.
		// (Taxes uses `start_date`/`end_date` because it has no soft
		// delete; reusing the same names here would conflate the two
		// audit dimensions.)
		effectiveFrom: timestamp('effective_from', { withTimezone: true }).notNull(),
		effectiveTo: timestamp('effective_to', { withTimezone: true }),
		// Soft-delete timestamp. listByStoreId filters out rows where
		// this is non-null; the supersession path uses effectiveTo
		// (not deletedAt) so historical analytics keep the row
		// visible.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		storeEffectiveFromIdx: index('warranty_reserves_store_effective_from_idx').on(t.storeId, t.effectiveFrom),
	}),
)

/**
 * `fx_rates` — append-only currency conversion source of truth.
 *
 * Hourly CaptureFxRates cron emits rows from CURRENCY_API; merchants
 * may insert MANUAL overrides; providers may report rates inline
 * (PROVIDER_REPORTED, captured during transaction ingest).
 *
 * Queried with the canonical pattern:
 *   SELECT * FROM fx_rates
 *    WHERE from_currency = ? AND to_currency = ?
 *      AND start_date <= ?
 *    ORDER BY start_date DESC LIMIT 1
 *
 * The composite index on (from_currency, to_currency, start_date DESC)
 * makes that query a single-page seek.
 */
export const fxRates = financeSchema.table(
	'fx_rates',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		fromCurrency: text('from_currency').notNull(),
		toCurrency: text('to_currency').notNull(),

		// Conversion rate: 1 unit of fromCurrency = `rate` units of
		// toCurrency. Stored as `text` to preserve provider-side
		// decimal precision verbatim (e.g. '5.10' stays '5.10', not
		// coerced to 5.1). Queries never sort or aggregate on rate
		// (ORDER BY runs on start_date) so the lack of numeric
		// semantics is fine. The FxRate entity carries `rate: string`
		// matching this column.
		rate: text('rate').notNull(),

		// FxRateSource enum (CURRENCY_API | MANUAL | PROVIDER_REPORTED).
		source: text('source').notNull(),

		// When this rate became effective. Multiple rows may exist for
		// the same currency pair; queries pick the most recent ≤ desired
		// timestamp.
		startDate: timestamp('start_date', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		// Canonical query index — covers the "find rate at time T" path.
		pairStartDateIdx: index('fx_rates_pair_start_date_idx').on(t.fromCurrency, t.toCurrency, t.startDate),
		sourceIdx: index('fx_rates_source_idx').on(t.source),
	}),
)

import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { MarketingPlatform, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from '../entities/Taxes'
import { TaxesRepository } from '../repositories/TaxesRepository'
import { TaxesUpdatedEvent } from '../events'

export const UpdateTaxesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	revenueTaxType: z.enum(TaxType).optional(),
	revenueTaxDeductionType: z.enum(TaxDeductionType).optional(),
	/** Effective rate as a 0..100 percentage. Persisted as 0..1 fraction. */
	revenueTaxRate: z.number().min(0).max(100).optional(),
	revenueTaxMultiplier: z.number().min(0).optional(),
	marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).optional(),
	effectiveFrom: z.date(),
})

export const UpdateTaxesOutputSchema = z.object({
	taxesId: z.uuid(),
	effectiveFrom: z.date(),
})

/**
 * C39 UpdateTaxes. Time-effective insert: opens a new row with the
 * supplied effectiveFrom + any patched fields (carrying defaults forward
 * from the previously-active row when present), and supersedes the
 * previous row by stamping its endDate with the new effectiveFrom.
 *
 * The supersession + insert are persisted in a single transaction so
 * reads always see exactly one active row per store.
 */
@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxes: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.taxes.findActiveByStoreId(input.storeId, tx)

			const type = input.revenueTaxType ?? previous?.type ?? TaxType.NONE
			const deductionType = input.revenueTaxDeductionType ?? previous?.deductionType ?? TaxDeductionType.NONE
			const ratePct = input.revenueTaxRate ?? (previous ? previous.rate * 100 : 0)
			const rate = ratePct / 100
			const revenueTaxMultiplier = input.revenueTaxMultiplier ?? previous?.revenueTaxMultiplier ?? 1.0
			const marketingTaxRatePerPlatform = input.marketingTaxRatePerPlatform ?? previous?.marketingTaxRatePerPlatform ?? {}

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.taxes.save(previous, tx)
			}

			const fresh = Taxes.create({
				storeId: input.storeId,
				type,
				deductionType,
				rate,
				revenueTaxMultiplier,
				marketingTaxRatePerPlatform,
				startDate: input.effectiveFrom,
			})
			await this.taxes.save(fresh, tx)

			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						taxes: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousTaxesId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { taxesId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateTaxes } from './UpdateTaxes'
import { TaxesRepository } from '../repositories/TaxesRepository'
import { TaxesUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('Taxes (C39 UpdateTaxes)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let update: UpdateTaxes
	let repo: TaxesRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		update = testBed.resolve(UpdateTaxes)
		repo = testBed.resolve(TaxesRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(TaxesUpdatedEvent)
	}

	it('first UpdateTaxes creates the active row + emits TaxesUpdatedEvent (previousTaxesId=null)', async () => {
		const out = await update.execute({
			userId: USER,
			storeId: STORE,
			revenueTaxType: TaxType.PRESUMED_PROFIT,
			revenueTaxDeductionType: TaxDeductionType.PRODUCT_COST,
			revenueTaxRate: 8.5,
			revenueTaxMultiplier: 1.15,
			marketingTaxRatePerPlatform: { META: 0.07 },
			effectiveFrom: new Date('2026-05-22T00:00:00.000Z'),
		})

		expect(out.taxesId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findActiveByStoreId(STORE)
		expect(saved?.type).toBe(TaxType.PRESUMED_PROFIT)
		expect(saved?.rate).toBeCloseTo(0.085) // 8.5% → 0.085
		expect(saved?.revenueTaxMultiplier).toBe(1.15)
		expect(saved?.marketingTaxRatePerPlatform).toEqual({ META: 0.07 })

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.previousTaxesId).toBeNull()
		expect(emitted[0]!.payload.taxes).toBeDefined()
		expect(emitted[0]!.payload.taxes.storeId).toBe(STORE)
	})

	it('second UpdateTaxes supersedes the previous row (endDate stamped) + previousTaxesId carries on event', async () => {
		const first = await update.execute({
			userId: USER,
			storeId: STORE,
			revenueTaxType: TaxType.PRESUMED_PROFIT,
			revenueTaxDeductionType: TaxDeductionType.PRODUCT_COST,
			revenueTaxRate: 8.5,
			effectiveFrom: new Date('2026-05-01T00:00:00.000Z'),
		})
		const second = await update.execute({
			userId: USER,
			storeId: STORE,
			revenueTaxRate: 9.0,
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		// The old row is now superseded
		const oldRow = await repo.findById(first.taxesId)
		expect(oldRow?.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		// The new row is active and inherits non-supplied fields
		const newRow = await repo.findById(second.taxesId)
		expect(newRow?.endDate).toBeNull()
		expect(newRow?.type).toBe(TaxType.PRESUMED_PROFIT) // carried forward
		expect(newRow?.rate).toBeCloseTo(0.09)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(2)
		expect(emitted[1]!.payload.previousTaxesId).toBe(first.taxesId)
		expect(emitted[1]!.payload.taxes).toBeDefined()
		expect(emitted[1]!.payload.taxes.storeId).toBe(STORE)
	})
})

import { injectable } from 'tsyringe-neo'
import { Controller, HttpStatusCode, z } from '@bk-dash/core-typescript'
import { MarketingPlatform, Role, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { AuthAccountMiddleware } from '@auth/middlewares/AuthAccountMiddleware'
import { RequireStoreMember } from '@auth/middlewares/RequireStoreMember'
import { RequireStoreRole } from '@tenancy/middlewares/RequireStoreRole'
import { UpdateTaxes, UpdateTaxesOutputSchema } from '../usecases/UpdateTaxes'

export const UpdateTaxesControllerInputSchema = z.object({
	ctx: z.object({
		user: z.object({ id: z.string() }),
		membership: z.object({ storeId: z.uuid() }),
	}),
	body: z.object({
		revenueTaxType: z.enum(TaxType).optional(),
		revenueTaxDeductionType: z.enum(TaxDeductionType).optional(),
		revenueTaxRate: z.number().min(0).max(100).optional(),
		revenueTaxMultiplier: z.number().min(0).optional(),
		marketingTaxRatePerPlatform: z.partialRecord(z.enum(MarketingPlatform), z.number()).optional(),
		effectiveFrom: z.stringToDate(),
	}),
})

export const UpdateTaxesControllerOutputSchema = UpdateTaxesOutputSchema

@injectable()
export class UpdateTaxesController extends Controller<typeof UpdateTaxesControllerInputSchema, typeof UpdateTaxesControllerOutputSchema> {
	readonly path = '/taxes-settings'
	readonly method = 'put' as const
	readonly description = 'Update Taxes configuration; appends a new time-effective row (C39 UpdateTaxes)'
	readonly inputSchema = UpdateTaxesControllerInputSchema
	readonly outputSchema = UpdateTaxesControllerOutputSchema

	override middlewares = [AuthAccountMiddleware, RequireStoreMember, RequireStoreRole([Role.OWNER, Role.ADMIN])]

	constructor(private cmd: UpdateTaxes) {
		super()
	}

	async handle(request: this['input']): Promise<this['output']> {
		const data = await this.cmd.execute({
			userId: request.ctx.user.id,
			storeId: request.ctx.membership.storeId,
			revenueTaxType: request.body.revenueTaxType,
			revenueTaxDeductionType: request.body.revenueTaxDeductionType,
			revenueTaxRate: request.body.revenueTaxRate,
			revenueTaxMultiplier: request.body.revenueTaxMultiplier,
			marketingTaxRatePerPlatform: request.body.marketingTaxRatePerPlatform,
			effectiveFrom: request.body.effectiveFrom,
		})
		return { status: HttpStatusCode.OK, data }
	}
}

