import { describe, it, expect } from 'bun:test'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import { TaxConfiguration } from './TaxConfiguration'

const startDate = (y: number, m: number, d: number) => new Date(y, m - 1, d)

describe('TaxConfiguration', () => {
	it('placeRevenueTax twice supersedes the single timeline (open-ended entry trimmed)', () => {
		const tc = TaxConfiguration.create({ storeId: 'store-1' })

		tc.placeRevenueTax({
			type: TaxType.PRESUMED_PROFIT,
			deductionType: TaxDeductionType.PRODUCT_COST,
			rate: 0.08,
			multiplier: 1.0,
			startDate: startDate(2026, 1, 1),
			endDate: null,
		})

		// Second placement supersedes the first (interval paint trims [Jan-1, ∞) to [Jan-1, Jun-1))
		tc.placeRevenueTax({
			type: TaxType.PRESUMED_PROFIT,
			deductionType: TaxDeductionType.PRODUCT_COST,
			rate: 0.09,
			multiplier: 1.0,
			startDate: startDate(2026, 6, 1),
			endDate: null,
		})

		// revenueTax timeline has 2 entries: the first trimmed + the new one
		expect(tc.revenueTax).toHaveLength(2)
		const sorted = [...tc.revenueTax].sort((a, b) => a.startDate.getTime() - b.startDate.getTime())
		expect(sorted[0]!.rate).toBe(0.08)
		expect(sorted[0]!.endDate).toEqual(startDate(2026, 6, 1))
		expect(sorted[1]!.rate).toBe(0.09)
		expect(sorted[1]!.endDate).toBeNull()
	})

	it('placeMarketingTax — META timeline grows; GOOGLE_ADS untouched (per-platform isolation, AC-8)', () => {
		const tc = TaxConfiguration.create({ storeId: 'store-1' })

		// Place META initial rate
		tc.placeMarketingTax({
			platform: MarketingPlatform.META,
			rates: [{ rate: 0.07, startDate: startDate(2026, 1, 1), endDate: null }],
		})

		// Place GOOGLE_ADS rate
		tc.placeMarketingTax({
			platform: MarketingPlatform.GOOGLE_ADS,
			rates: [{ rate: 0.05, startDate: startDate(2026, 1, 1), endDate: null }],
		})

		// Place new META rate — supersedes the previous META entry
		tc.placeMarketingTax({
			platform: MarketingPlatform.META,
			rates: [{ rate: 0.08, startDate: startDate(2026, 6, 1), endDate: null }],
		})

		const metaEntries = tc.marketingTax.filter(m => m.platform === MarketingPlatform.META)
		const googleEntries = tc.marketingTax.filter(m => m.platform === MarketingPlatform.GOOGLE_ADS)

		// META has 2 entries (first trimmed + new)
		expect(metaEntries).toHaveLength(2)
		// GOOGLE_ADS untouched (1 entry)
		expect(googleEntries).toHaveLength(1)
