import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { taxConfiguration } from '@bk-dash/contracts/db'
import { TaxConfiguration, TaxConfigurationSchema } from '../../entities/TaxConfiguration'
import { TaxConfigurationRepository } from './TaxConfigurationRepository'

/**
 * Drizzle-backed implementation of TaxConfigurationRepository.
 * One row per Store — UPSERT on save via deterministic id;
 * `incrementVersion` bumps the optimistic-concurrency counter.
 *
 * `findByStoreId` returns the single row for the store (the old
 * multi-row time-effective pattern is replaced by embedded Timeline
 * arrays; Task T11).
 *
 * `toDomain` feeds the raw jsonb arrays through `TaxConfigurationSchema`
 * so `z.coerce.date()` (from z.historical) rehydrates ISO-string dates
 * back to Date objects without manual parsing.
 */
@injectable()
export class DrizzleTaxConfigurationRepository extends TaxConfigurationRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<TaxConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(taxConfiguration).where(eq(taxConfiguration.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<TaxConfiguration | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(taxConfiguration).where(eq(taxConfiguration.storeId, storeId)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: TaxConfiguration, tx?: DrizzleClient): Promise<TaxConfiguration> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(taxConfiguration)
				.values(data)
				.onConflictDoUpdate({
					target: taxConfiguration.id,
					set: {
						storeId: data.storeId,
						revenueTax: data.revenueTax,
						marketingTax: data.marketingTax,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(taxConfiguration).where(eq(taxConfiguration.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof taxConfiguration.$inferSelect): TaxConfiguration {
		// `TaxConfigurationSchema` parses the jsonb arrays; z.coerce.date() in
		// z.historical rehydrates ISO-string dates → Date without manual parsing.
		const parsed = TaxConfigurationSchema.parse({
			storeId: row.storeId,
			revenueTax: row.revenueTax,
			marketingTax: row.marketingTax,
		})
		return new TaxConfiguration({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: TaxConfiguration): typeof taxConfiguration.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			revenueTax: entity.revenueTax,
			marketingTax: entity.marketingTax,
			version: entity.version,
		}
	}
}

