import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import { TaxConfiguration } from '../../entities/TaxConfiguration'
import { TaxConfigurationRepository } from './TaxConfigurationRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

const d = (y: number, m: number, day: number) => new Date(y, m - 1, day)

describe('DrizzleTaxConfigurationRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: TaxConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(TaxConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: { storeId?: string } = {}): TaxConfiguration {
		return TaxConfiguration.create({ storeId: opts.storeId ?? STORE_A })
	}

	describe('save + findById', () => {
		it('round-trips a TaxConfiguration aggregate with empty timelines', async () => {
			const entity = build()
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched).toBeDefined()
			expect(fetched?.storeId.value).toBe(STORE_A)
			expect(fetched?.revenueTax).toEqual([])
			expect(fetched?.marketingTax).toEqual([])
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})

		it('UPSERT semantics — saving twice updates the row', async () => {
			const entity = build()
			await repo.save(entity)
			const v1 = entity.version

			// Place a revenue tax and save again
			entity.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.08,
				multiplier: 1.0,
				startDate: d(2026, 1, 1),
				endDate: null,
			})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.version).toBeGreaterThan(v1)
			expect(fetched?.revenueTax).toHaveLength(1)
		})

		it('round-trips a gateway fee timeline with two entries and rehydrates Date windows (AC-9)', async () => {
			const entity = build()
			// Place two revenue tax entries to create a two-entry timeline
			entity.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.08,
				multiplier: 1.0,
				startDate: d(2026, 1, 1),
				endDate: null,
			})
			entity.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.09,
				multiplier: 1.0,
				startDate: d(2026, 6, 1),
				endDate: null,
			})
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.revenueTax).toHaveLength(2)

			// Rehydration: dates must be Date instances (z.coerce.date in z.historical)
			const sorted = [...(fetched?.revenueTax ?? [])].sort(
				(a, b) => a.startDate.getTime() - b.startDate.getTime(),
			)
			expect(sorted[0]!.startDate).toBeInstanceOf(Date)
			expect(sorted[0]!.endDate).toBeInstanceOf(Date)
			expect(sorted[1]!.startDate).toBeInstanceOf(Date)
			expect(sorted[1]!.endDate).toBeNull()
		})

		it('round-trips marketing tax per-platform containers with rate timelines', async () => {
			const entity = build()
			entity.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: d(2026, 1, 1), endDate: null })
			entity.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.08, startDate: d(2026, 6, 1), endDate: null })
			entity.placeMarketingTax({ platform: MarketingPlatform.GOOGLE_ADS, rate: 0.05, startDate: d(2026, 1, 1), endDate: null })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			const metaContainer = fetched?.marketingTax.find(m => m.platform === MarketingPlatform.META)
			const googleContainer = fetched?.marketingTax.find(m => m.platform === MarketingPlatform.GOOGLE_ADS)

			expect(metaContainer?.rates).toHaveLength(2)
			expect(googleContainer?.rates).toHaveLength(1)
			// Dates rehydrated
			expect(metaContainer?.rates[0]?.startDate).toBeInstanceOf(Date)
		})
	})

	describe('findByStoreId', () => {
		it('returns undefined when no row exists', async () => {
			const r = await repo.findByStoreId(STORE_A)
			expect(r).toBeUndefined()
		})

		it('returns the row for the correct store', async () => {
			const entity = build({ storeId: STORE_A })
			entity.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.07,
				multiplier: 1.0,
				startDate: d(2026, 1, 1),
				endDate: null,
			})
			await repo.save(entity)

			const fetched = await repo.findByStoreId(STORE_A)
			expect(fetched?.id.value).toBe(entity.id.value)
			expect(fetched?.revenueTax).toHaveLength(1)
		})

		it('isolates by storeId (cross-store leak protection)', async () => {
			await repo.save(build({ storeId: STORE_A }))
			await repo.save(build({ storeId: STORE_B }))

			const a = await repo.findByStoreId(STORE_A)
			const b = await repo.findByStoreId(STORE_B)
			expect(a?.storeId.value).toBe(STORE_A)
			expect(b?.storeId.value).toBe(STORE_B)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const entity = build()
			await repo.save(entity)
			await repo.delete(entity.id.value)
			expect(await repo.findById(entity.id.value)).toBeUndefined()
		})
	})
})

