import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { TaxType, TaxDeductionType, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateTaxes } from './UpdateTaxes'
import { TaxConfigurationRepository } from '../repositories/TaxConfigurationRepository'
import { TaxesUpdatedEvent } from '../events'

const STORE = testId('store', '1')
const USER = testId('user', '1')

describe('UpdateTaxes (C39 typed revenue+marketing timeline)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let update: UpdateTaxes
	let repo: TaxConfigurationRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		update = testBed.resolve(UpdateTaxes)
		repo = testBed.resolve(TaxConfigurationRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(TaxesUpdatedEvent)
	}

	/**
	 * AC-11/AC-12/AC-14: place revenue tax @2026-01-01, META marketing @2026-03-01,
	 * new META rate @2026-06-01. Assert:
	 *   - META container rates leaf has 2 entries (first trimmed to end 2026-06-01)
	 *   - revenueTax timeline has 1 entry (unchanged)
	 *   - a TaxesUpdatedEvent is recorded for each update
	 *   - effectiveStartDate on last event equals the change instant (AC-12)
	 */
	it('AC-11/AC-12/AC-14: revenue tax, META marketing timeline isolation + event effectiveStartDate', async () => {
		// Step 1: revenue tax @2026-01-01
		await update.execute({
			userId: USER,
			storeId: STORE,
			revenueTax: { type: TaxType.PRESUMED_PROFIT, deductionType: TaxDeductionType.PRODUCT_COST, rate: 0.12, multiplier: 1 },
			effectiveFrom: new Date('2026-01-01T00:00:00.000Z'),
		})

		// Step 2: META marketing tax @2026-03-01
		await update.execute({
			userId: USER,
			storeId: STORE,
			marketingTax: { platform: MarketingPlatform.META, rate: 0.15 },
			effectiveFrom: new Date('2026-03-01T00:00:00.000Z'),
		})

		// Step 3: new META rate @2026-06-01 — trims first META entry to end 2026-06-01
		await update.execute({
			userId: USER,
			storeId: STORE,
			marketingTax: { platform: MarketingPlatform.META, rate: 0.18 },
			effectiveFrom: new Date('2026-06-01T00:00:00.000Z'),
		})

		const tc = await repo.findByStoreId(STORE)
		expect(tc).toBeDefined()

		// revenueTax: single timeline with 1 entry (open-ended, never superseded)
		expect(tc!.revenueTax).toHaveLength(1)
		expect(tc!.revenueTax[0]!.endDate).toBeNull()

		// META marketing platform container has rates leaf with 2 entries
		const metaContainer = tc!.marketingTax.find(m => m.platform === MarketingPlatform.META)
		expect(metaContainer).toBeDefined()
		expect(metaContainer!.rates).toHaveLength(2)

		// First META entry trimmed: endDate = 2026-06-01
		expect(metaContainer!.rates[0]!.endDate).toEqual(new Date('2026-06-01T00:00:00.000Z'))
		expect(metaContainer!.rates[0]!.rate).toBeCloseTo(0.15)

		// Second META entry: open-ended
		expect(metaContainer!.rates[1]!.endDate).toBeNull()
		expect(metaContainer!.rates[1]!.rate).toBeCloseTo(0.18)

		// AC-12: TaxesUpdatedEvent emitted for each update; last event carries effectiveStartDate = 2026-06-01
		const events = await readUpdatedEvents()
		expect(events).toHaveLength(3)

		const lastEvent = events[2]!
		expect(lastEvent.payload.previousTaxConfigurationId).toBeNull()
		expect(lastEvent.payload.taxConfiguration).toBeDefined()
		// effectiveStartDate stored in jsonb as ISO string; compare via ISO
		expect(new Date(lastEvent.payload.effectiveStartDate as unknown as string).toISOString()).toBe(
			'2026-06-01T00:00:00.000Z',
		)
	})

	it('AC-14: GOOGLE_ADS timeline is isolated from META timeline changes', async () => {
		// Place META rate
		await update.execute({
			userId: USER,
			storeId: STORE,
			marketingTax: { platform: MarketingPlatform.META, rate: 0.15 },
