import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { TaxType, TaxDeductionType, MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { TaxConfiguration } from '../entities/TaxConfiguration'
import { TaxConfigurationRepository } from '../repositories/TaxConfigurationRepository'
import { TaxesUpdatedEvent } from '../events'

export const UpdateTaxesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	revenueTax: z
		.object({
			type: z.enum(TaxType),
			deductionType: z.enum(TaxDeductionType),
			/** Effective rate as a 0..1 fraction. */
			rate: z.number().min(0).max(1),
			/** Profit-margin safety multiplier (1.0 = neutral). */
			multiplier: z.number().min(0).default(1),
		})
		.optional(),
	marketingTax: z
		.object({
			platform: z.enum(MarketingPlatform),
			/** Marketing tax rate as a 0..1 fraction. */
			rate: z.number().min(0).max(1),
		})
		.optional(),
	effectiveFrom: z.date(),
})

export const UpdateTaxesOutputSchema = z.object({
	taxConfigurationId: z.uuid(),
	effectiveFrom: z.date(),
})

@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxRepo: TaxConfigurationRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const tc = (await this.taxRepo.findByStoreId(input.storeId, tx)) ?? TaxConfiguration.create({ storeId: input.storeId })

			const at = { startDate: input.effectiveFrom, endDate: null as Date | null }

			if (input.revenueTax) {
				tc.placeRevenueTax({ ...input.revenueTax, ...at })
			}

			if (input.marketingTax) {
				tc.placeMarketingTax({ ...input.marketingTax, ...at })
			}

			await this.taxRepo.save(tc, tx)

			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: tc.id.value,
					ownerId: input.storeId,
					payload: {
						taxConfiguration: tc.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousTaxConfigurationId: null,
					},
				}),
				tx,
			)

			return { taxConfigurationId: tc.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

