```typescript
import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { RevenueTaxSchema, MarketingTaxSchema, MarketingTaxRateSchema } from '../objects'

type RevenueTaxEntry = Z.infer<typeof RevenueTaxSchema>
type MarketingTaxRateEntry = Z.infer<typeof MarketingTaxRateSchema>

export const TaxConfigurationSchema = z.object({
	storeId: z.instance(Id),
	revenueTax: z.array(RevenueTaxSchema).default([]),
	marketingTax: z.array(MarketingTaxSchema).default([]),
})

export type TaxConfigurationProps = Z.infer<typeof TaxConfigurationSchema>

/**
 * One row per Store. Keys structural, only values historical:
 *   - revenueTax: a single whole-value Timeline<RevenueTax>.
 *   - marketingTax: one container per platform; each `rates` a
 *     Timeline<MarketingTaxRate> ({rate} over time).
 * place* methods are interval paints (Timeline.place), not appends (Decision 3).
 */
export class TaxConfiguration extends AggregateRoot<typeof TaxConfigurationSchema> {
	static override schema = TaxConfigurationSchema

	static create(data: { storeId: string }): TaxConfiguration {
		return new TaxConfiguration({ storeId: data.storeId, revenueTax: [], marketingTax: [] })
	}

	placeRevenueTax(entry: RevenueTaxEntry): void {
		this.revenueTax = [...new Timeline<RevenueTaxEntry>(this.revenueTax).place(entry).entries]
		this.validate()
	}

	/** Paint a {rate} value onto the platform's leaf timeline. */
	placeMarketingTax(input: { platform: MarketingPlatform } & MarketingTaxRateEntry): void {
		const { platform, ...rate } = input
		const container = this.marketingTax.find(m => m.platform === platform)
		const painted = new Timeline<MarketingTaxRateEntry>(container?.rates ?? []).place(rate)
		this.marketingTax = container
			? this.marketingTax.map(m => (m.platform === platform ? { platform, rates: [...painted.entries] } : m))
			: [...this.marketingTax, { platform, rates: [...painted.entries] }]
		this.validate()
	}
}

export interface TaxConfiguration extends TaxConfigurationProps {}
```

