import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier, CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	displayName: z.string().max(120).optional(),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

export const ProductCostOptionItemInputSchema = z.object({
	variantIds: z.array(z.uuid()).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: MonetaryAmountSchema,
	shipping: MonetaryAmountSchema,
})

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.string().length(2).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	shipping: MonetaryAmountSchema,
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency, country, and date range —
 * which in turn hold `ProductCostOptionItem`s with per-variant × qty-tier
 * cost amounts.
 *
 * - Invariant: date ranges within a given (currency × country) pair must not overlap.
 * - Invariant: startDate ≤ endDate when endDate is present.
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		displayName?: string
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Map first so computed fields (id, variantsHash) are present, then
		// validate through the schema (including the refine) the same way
		// validate() does — throwing the issue message directly as the error code.
		const options = data.options.map(opt => ({
			id: crypto.randomUUID(),
			currency: opt.currency,
			country: opt.country,
			startDate: opt.startDate,
			endDate: opt.endDate ?? null,
			shipping: opt.shipping,
			items: opt.items.map(item => ({
				id: crypto.randomUUID(),
				variantIds: item.variantIds,
				quantity: item.quantity,
				quantityModifier: item.quantityModifier,
				unitCost: item.unitCost,
				shipping: item.shipping,
				variantsHash: hashVariantIds(item.variantIds),
			})),
		}))

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			displayName: data.displayName,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — displayName and/or the full options set. */
	update(data: { displayName?: string; options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.displayName !== undefined) {
			this.displayName = data.displayName
		}
		if (data.options !== undefined) {
			const options = data.options.map(opt => ({
				id: crypto.randomUUID(),
				currency: opt.currency,
				country: opt.country,
				startDate: opt.startDate,
				endDate: opt.endDate ?? null,
				shipping: opt.shipping,
				items: opt.items.map(item => ({
					id: crypto.randomUUID(),
					variantIds: item.variantIds,
					quantity: item.quantity,
					quantityModifier: item.quantityModifier,
					unitCost: item.unitCost,
					shipping: item.shipping,
					variantsHash: hashVariantIds(item.variantIds),
				})),
			}))
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

import { pgSchema, uuid, text, timestamp, integer, bigint, jsonb, boolean, index, uniqueIndex } from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'

/**
 * `catalog` is BK Dash's BC5 Catalog schema.
 *
 * Two ownership models live in the same schema:
 *   - `products` + `variants` are **Go-owned** canonical projections,
 *     written via UPSERT by go-worker every time a provider catalog
 *     sync lands. Deterministic UUIDv5 PK + unique (platform,
 *     external_id) lets the (xmax = 0) is_new detection ride alongside.
 *   - `product_costs` (+ `product_cost_options`) is **TS-owned** —
 *     merchant-entered cost data, no provider source. Joined to
 *     products at analytics-query time to derive profit margin.
 */
export const catalogSchema = pgSchema('catalog')

export const products = catalogSchema.table(
	'products',
	{
		id: uuid('id').primaryKey(),

		storeId: uuid('store_id').notNull(),
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),

		// Provider-side identifiers + presentation.
		title: text('title').notNull(),
		handle: text('handle'),
		description: text('description'),
		vendor: text('vendor'),
		productType: text('product_type'),
		imageUrl: text('image_url'),

		// Status enum value from spec ProductStatus (ACTIVE/ARCHIVED/DRAFT)
		// — stored as text rather than pgEnum so we don't lock the
		// migration to one snapshot of the enum.
		status: text('status').notNull(),

		// Aggregated price range across all variants — cheap to denormalize
		// here so list views don't fan out to variant rows.
		minPriceCents: bigint('min_price_cents', { mode: 'bigint' }),
		maxPriceCents: bigint('max_price_cents', { mode: 'bigint' }),
		currency: text('currency'),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		// Audit / optimistic concurrency.
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('products_platform_external_id_unq').on(t.platform, t.externalId),
		storeIdx: index('products_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('products_store_integration_id_idx').on(t.storeIntegrationId),
		statusIdx: index('products_status_idx').on(t.status),
	}),
)

/**
 * TS-owned merchant overlay on canonical Product (SPEC-10). Carries
 * fields the merchant edits without the Go sync pipeline overwriting:
 * starts with `tags`, future extensions go here (custom descriptions, etc.).
 * Unique on (product_id, store_id) — 1:1 with Product per Store.
 */
export const productOverrides = catalogSchema.table(
	'product_overrides',
	{
		id: uuid('id').primaryKey(),
		productId: uuid('product_id').notNull(),
		storeId: uuid('store_id').notNull(),

		// Merchant-curated tag list (moved off canonical Product).
		tags: jsonb('tags').notNull().default(sql`'[]'::jsonb`),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		productStoreUnq: uniqueIndex('product_overrides_product_id_store_id_unq').on(t.productId, t.storeId),
		storeIdx: index('product_overrides_store_id_idx').on(t.storeId),
	}),
)

export const variants = catalogSchema.table(
	'variants',
	{
		id: uuid('id').primaryKey(),

		// Parent product. Intentionally NO FK reference (Go writes variants
		// concurrently with products during a backfill; a strict FK would
		// require ordering writes by parent-then-child which `sqlc` doesn't
		// naturally express). Drizzle queries JOIN by product_id explicitly.
		productId: uuid('product_id').notNull(),

		// No storeId — the canonical ProductVariant aggregate (spec § BC5)
		// scopes by productId; the store is reachable by JOINing the parent
		// catalog.products. Dropped to keep the table aligned with the aggregate.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		storeIntegrationExternalId: text('store_integration_external_id').notNull(),

		platform: text('platform').notNull(),
		externalId: text('external_id').notNull(),
		productExternalId: text('product_external_id').notNull(),

		// Option labels — providers expose these as ordered key/value pairs
		// (Color/Red, Size/M, …). Stored as jsonb so 1- to N-option variants
		// share one column without schema churn.
		optionLabels: jsonb('option_labels'),

		title: text('title'),
		sku: text('sku'),
		imageUrl: text('image_url'),

		compareAtPriceCents: bigint('compare_at_price_cents', { mode: 'bigint' }),

		// Provider inventory quantity. Sentinel-free — null = provider
		// doesn't track inventory for this variant.
		quantityAvailable: integer('quantity_available'),

		status: text('status').notNull(),
		isDefault: boolean('is_default').notNull().default(false),

		externalCreatedAt: timestamp('external_created_at', { withTimezone: true }).notNull(),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		platformExternalIdUnq: uniqueIndex('variants_platform_external_id_unq').on(t.platform, t.externalId),
		productIdx: index('variants_product_id_idx').on(t.productId),
		storeIntegrationIdx: index('variants_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

/**
 * `product_costs` is the merchant-owned cost aggregate per Store ×
 * Product. The header carries scope + type; the `product_cost_options`
 * child table carries the time-effective / per-country / per-variant
 * cost tiers (one option = one (currency, country?, dateRange) slice).
 *
 * Spec rule: at most one ProductCost per (storeId, productId). The
 * variant-level granularity is encoded in `product_cost_options.items`.
 */
export const productCosts = catalogSchema.table(
	'product_costs',
	{
		id: uuid('id').primaryKey().defaultRandom(),

		storeId: uuid('store_id').notNull(),
		// Scopes the cost row to the StoreIntegration that owns the
		// underlying product/variant ids. Required because the same
		// product can appear under multiple integrations (multi-channel
		// merchant) and merchant cost rules are typically per-channel.
		storeIntegrationId: uuid('store_integration_id').notNull(),
		// References catalog.products.id but no FK — products can be
		// re-synced (re-UPSERTed) without breaking the merchant's cost
		// data; we want costs to survive provider id changes. Nullable
		// for kit-scoped costs (multi-variant bundle priced together).
		productId: uuid('product_id'),

		// Discriminator from spec ProductCostType (SINGLE / MULTIPLE).
		// SINGLE = one cost across all variants; MULTIPLE = per-variant.
		costType: text('cost_type').notNull(),

		// Optional merchant-facing label (used by the BFF list shape).
		displayName: text('display_name'),

		// Time-effective option array, stored inline as jsonb. Each
		// option carries: { id, currency, country?, startDate, endDate?,
		// shipping: {amountCents, currency}, items: [{id, variantIds,
		// quantity, quantityModifier, unitCost, shipping, variantsHash}] }.
		// Inlined (vs the original product_cost_options child table)
		// because reads always pull the full document; the child-table
		// shape required cascade writes + N+1 reads for no actual
		// normalization benefit.
		options: jsonb('options').notNull().default([]),

		// Soft-delete timestamp. List queries filter by `deleted_at IS NULL`.
		deletedAt: timestamp('deleted_at', { withTimezone: true }),

		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
		updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
		version: integer('version').notNull().default(1),
	},
	t => ({
		// Partial unique — only enforce on live rows so a re-created cost
		// for the same (storeId, productId) after soft-delete doesn't
		// collide with the historical row.
		storeProductUnq: uniqueIndex('product_costs_store_product_unq').on(t.storeId, t.productId).where(sql`${t.deletedAt} IS NULL`),
		storeIdx: index('product_costs_store_id_idx').on(t.storeId),
		storeIntegrationIdx: index('product_costs_store_integration_id_idx').on(t.storeIntegrationId),
	}),
)

// `product_cost_options` removed iter 320 — options now stored inline
// as a jsonb column on `product_costs`. The child-table normalization
// added cascade write complexity for no read-side benefit (the
// aggregate is always read as a complete document).

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { ProductCost, ProductCostOptionInputSchema } from '../entities/ProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostCreatedEvent } from '../events'
import type { CatalogDomainErrors } from '../errors'
import { ProductCostType } from '@bk-dash/contracts-typescript/wire/enums'

export const CreateProductCostInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	storeIntegrationId: z.uuid(),
	productId: z.uuid().nullable(),
	costType: z.enum(ProductCostType),
	displayName: z.string().max(120).optional(),
	options: z.array(ProductCostOptionInputSchema).min(1),
})

export const CreateProductCostOutputSchema = z.object({
	productCostId: z.uuid(),
})

/**
 * C27 CreateProductCost. Spec invariant "at most one ProductCost per
 * (storeId, productId)" is enforced via a `findByStoreAndProduct` gate
 * before construction. The entity's `create()` validates date-range
 * shape per option; cross-row overlap protection (PRODUCT_COST_RULE_OVERLAP)
 * is the entity's responsibility only when applied to a single rule's
 * options — multi-rule overlap can't apply here because at most one rule
 * exists per (storeId, productId) after the uniqueness gate.
 */
@injectable()
export class CreateProductCost extends Handler<typeof CreateProductCostInputSchema, typeof CreateProductCostOutputSchema> {
	readonly name = 'create_product_cost' as const
	readonly inputSchema = CreateProductCostInputSchema
	readonly outputSchema = CreateProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const existing = await this.productCosts.findByStoreAndProduct(input.storeId, input.productId, tx)
		if (existing) {
			throw new BaseError<CatalogDomainErrors>('PRODUCT_COST_ALREADY_EXISTS')
		}

		return this.withTransaction(tx, async tx => {
			const productCost = ProductCost.create({
				storeId: input.storeId,
				storeIntegrationId: input.storeIntegrationId,
				productId: input.productId,
				costType: input.costType,
				displayName: input.displayName,
				options: input.options,
			})

			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostCreatedEvent({
					entityId: productCost.id.value,
					ownerId: input.storeId,
					payload: { productCost: productCost.toJSON() },
				}),
				tx,
			)

			return { productCostId: productCost.id.value }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { ProductCostOptionInputSchema } from '../entities/ProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostUpdatedEvent } from '../events'
import type { CatalogApplicationErrors } from '../errors'

export const UpdateProductCostInputSchema = z.object({
	userId: z.uuid(),
	productCostId: z.uuid(),
	options: z.array(ProductCostOptionInputSchema).optional(),
	displayName: z.string().max(120).optional(),
})

export const UpdateProductCostOutputSchema = z.void()

/**
 * C28 UpdateProductCost. Loads the existing aggregate, applies the
 * (displayName / options) patch via `entity.update()` — which re-validates
 * the date-range invariant on the new options — then persists + emits
 * ProductCostUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateProductCost extends Handler<typeof UpdateProductCostInputSchema, typeof UpdateProductCostOutputSchema> {
	readonly name = 'update_product_cost' as const
	readonly inputSchema = UpdateProductCostInputSchema
	readonly outputSchema = UpdateProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const productCost = await this.productCosts.findById(input.productCostId, tx)
		if (!productCost || productCost.isDeleted) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			productCost.update({ displayName: input.displayName, options: input.options })
			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostUpdatedEvent({
					entityId: productCost.id.value,
					ownerId: productCost.storeId.value,
					payload: { productCost: productCost.toJSON() },
				}),
				tx,
			)
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostDeletedEvent } from '../events'
import type { CatalogApplicationErrors } from '../errors'

export const DeleteProductCostInputSchema = z.object({
	userId: z.uuid(),
	productCostId: z.uuid(),
})

export const DeleteProductCostOutputSchema = z.void()

/**
 * C29 DeleteProductCost. Soft-delete via `entity.delete()` (preserves
 * the row for historical COGS attribution per spec). Emits
 * ProductCostDeletedEvent for downstream consumers (analytics
 * invalidations, reporting). Refuses a second delete with
 * PRODUCT_COST_NOT_FOUND — the entity rejects double-delete inside
 * delete(); this layer just translates that to the application
 * lookup-failure shape.
 */
@injectable()
export class DeleteProductCost extends Handler<typeof DeleteProductCostInputSchema, typeof DeleteProductCostOutputSchema> {
	readonly name = 'delete_product_cost' as const
	readonly inputSchema = DeleteProductCostInputSchema
	readonly outputSchema = DeleteProductCostOutputSchema

	constructor(private readonly productCosts: ProductCostRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const productCost = await this.productCosts.findById(input.productCostId, tx)
		if (!productCost || productCost.isDeleted) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}

		await this.withTransaction(tx, async tx => {
			productCost.delete()
			await this.productCosts.save(productCost, tx)

			await this.domainEventRepository.save(
				new ProductCostDeletedEvent({
					entityId: productCost.id.value,
					ownerId: productCost.storeId.value,
					payload: {
						productCost: productCost.toJSON(),
					},
				}),
				tx,
			)
		})

		return
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, tryCatch, z, type Transaction, type BaseDomainEvent } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCost } from '../entities/ProductCost'
import { ProductCostCsvProvider } from '../enums'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostCsvParser } from '../services/ProductCostCsvParser'
import { ProductCostCreatedEvent, ProductCostUpdatedEvent } from '../events'

const baseFields = {
	userId: z.uuid(),
	storeId: z.uuid(),
	storeIntegrationId: z.uuid(),
	csvContent: z.string().min(1),
}

export const BulkImportProductCostsFromCsvInputSchema = z.discriminatedUnion('provider', [
	z.object({ provider: z.literal(ProductCostCsvProvider.MANUAL), ...baseFields }),
	z.object({
		provider: z.literal(ProductCostCsvProvider.SHOPIFY),
		...baseFields,
		currency: z.enum(CurrencyCode),
		effectiveDate: z.iso.date(),
		endDate: z.iso.date().optional(),
	}),
])

export const BulkImportProductCostsFromCsvOutputSchema = z.object({
	createdCount: z.number().int().min(0),
	updatedCount: z.number().int().min(0),
	skippedCount: z.number().int().min(0),
	errors: z.array(
		z.object({
			row: z.number().int().min(0),
			/** A CatalogCsvImportErrors code (registered, i18n-able) — never a raw message. */
			code: z.string(),
			/** The offending raw cell value, for display/debug. */
			value: z.string().optional(),
		}),
	),
})

/**
 * C30 BulkImportProductCostsFromCsv. Routes on `provider` through the
 * ProductCostCsvParser facade (parser + processor per provider), then persists
 * the resulting per-product builds in one transaction via saveMany +
 * DomainEventRepository.saveMany — one Created/Updated event per aggregate.
 * Partial-success: per-row failures accumulate as typed `errors[]` codes.
 */
@injectable()
export class BulkImportProductCostsFromCsv extends Handler<
	typeof BulkImportProductCostsFromCsvInputSchema,
	typeof BulkImportProductCostsFromCsvOutputSchema
> {
	readonly name = 'bulk_import_product_costs_from_csv' as const
	readonly inputSchema = BulkImportProductCostsFromCsvInputSchema
	readonly outputSchema = BulkImportProductCostsFromCsvOutputSchema

	constructor(
		private readonly productCosts: ProductCostRepository,
		private readonly csvParser: ProductCostCsvParser,
	) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const { builds, errors } = await this.csvParser.parse({
			provider: input.provider,
			csvContent: input.csvContent,
			storeId: input.storeId,
			storeIntegrationId: input.storeIntegrationId,
			currency: input.provider === ProductCostCsvProvider.SHOPIFY ? input.currency : undefined,
			effectiveDate: input.provider === ProductCostCsvProvider.SHOPIFY ? input.effectiveDate : undefined,
			endDate: input.provider === ProductCostCsvProvider.SHOPIFY ? input.endDate : undefined,
		})

		const rowErrors: { row: number; code: string; value?: string }[] = [...errors]
		const toSave: ProductCost[] = []
		const events: BaseDomainEvent[] = []
		let createdCount = 0
		let updatedCount = 0

		await this.withTransaction(tx, async tx => {
			const productIds = [...new Set(builds.map(b => b.productId))]
			const existingList = productIds.length > 0 ? await this.productCosts.findByStoreAndProducts(input.storeId, productIds, tx) : []
			const existingByProduct = new Map<string | null, ProductCost>(existingList.map(e => [e.productId?.value ?? null, e]))

			for (const build of builds) {
				const existing = existingByProduct.get(build.productId)
				if (existing) {
					const r = tryCatch(() =>
						existing.update({
							displayName: build.displayName,
							options: [
								...existing.options.map(o => {
									const json = o.toJSON()
									return {
										...json,
										startDate: new Date(json.startDate).toISOString().slice(0, 10),
										endDate: json.endDate != null ? new Date(json.endDate).toISOString().slice(0, 10) : undefined,
									}
								}),
								...build.options,
							],
						}),
					)
					if (!r.success) {
						rowErrors.push({ row: build.sourceRows[0]!, code: 'CSV_ROW_INVALID', value: errorMessage(r.error) })
						continue
					}
					toSave.push(existing)
					events.push(
						new ProductCostUpdatedEvent({
							entityId: existing.id.value,
							ownerId: existing.storeId.value,
							payload: { productCost: existing.toJSON() },
						}),
					)
					updatedCount++
				} else {
					const r = tryCatch(() =>
						ProductCost.create({
							storeId: input.storeId,
							storeIntegrationId: input.storeIntegrationId,
							productId: build.productId,
							costType: build.costType,
							displayName: build.displayName,
							options: build.options,
						}),
					)
					if (!r.success) {
						rowErrors.push({ row: build.sourceRows[0]!, code: 'CSV_ROW_INVALID', value: errorMessage(r.error) })
						continue
					}
					toSave.push(r.data)
					events.push(
						new ProductCostCreatedEvent({
							entityId: r.data.id.value,
							ownerId: r.data.storeId.value,
							payload: { productCost: r.data.toJSON() },
						}),
					)
					createdCount++
				}
			}

			if (toSave.length > 0) await this.productCosts.saveMany(toSave, tx)
			if (events.length > 0) await this.domainEventRepository.saveMany(events, tx)
		})

		return { createdCount, updatedCount, skippedCount: rowErrors.length, errors: rowErrors }
	}
}

function errorMessage(e: unknown): string {
	if (e instanceof Error) return e.message || e.name
	return String(e)
}

