import type { ApplicableProductCost } from './ApplicableProductCost'

export interface FindApplicableProductCostsInput {
	storeId: string
	/** Canonical product UUIDs present on the order. When omitted, all store costs are returned. */
	productIds?: string[]
	/** Order date used to filter costs by their effective interval. */
	at?: Date
}

/**
 * Cross-BC read port: surfaces catalog cost rules in the solver's
 * `ApplicableProductCost` shape so the sales-side ProductCostApplicationHandler
 * can resolve per-line costs without depending on catalog internals.
 * (Naming + Zod-return convention per feedback_query_service_naming_and_zod.)
 */
export abstract class ProductCostQueryService {
	abstract findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]>
}

import { injectable } from 'tsyringe-neo'
import { and, eq, inArray, isNull } from 'drizzle-orm'
import { DrizzleClient } from '@bk-dash/core-typescript'
import { productCosts } from '@bk-dash/contracts/db'
import type { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { ApplicableProductCostSchema, ApplicableProductCostItemSchema } from './ApplicableProductCost'
import type { ApplicableProductCost } from './ApplicableProductCost'
import { ProductCostQueryService, type FindApplicableProductCostsInput } from './ProductCostQueryService'

/** Serialized shape of a MonetaryAmount after JSONB round-trip. */
interface StoredMonetaryAmount {
	amountCents: number
	currency: string
}

/** Serialized shape of a ProductCostOptionItem after JSONB round-trip.
 *  Id.toJSON() → raw UUID string; MonetaryAmount.toJSON() → {amountCents, currency}. */
interface StoredProductCostOptionItem {
	id: string
	variantIds: string[]
	quantity: number
	quantityModifier: QuantityModifier
	unitCost: StoredMonetaryAmount
	shipping: StoredMonetaryAmount
	variantsHash: string
}

/** Serialized shape of a ProductCostOption after JSONB round-trip. */
interface StoredProductCostOption {
	id: string
	currency: string
	country?: string
	startDate: string
	endDate?: string | null
	shipping: StoredMonetaryAmount
	items: StoredProductCostOptionItem[]
}

@injectable()
export class DrizzleProductCostQueryService extends ProductCostQueryService {
	constructor(private readonly db: DrizzleClient) {
		super()
	}

	async findApplicable(input: FindApplicableProductCostsInput): Promise<ApplicableProductCost[]> {
		const filters = [eq(productCosts.storeId, input.storeId), isNull(productCosts.deletedAt)]
		if (input.productIds && input.productIds.length > 0) {
			filters.push(inArray(productCosts.productId, input.productIds))
		}
		const rows = await this.db
			.select()
			.from(productCosts)
			.where(and(...filters))

		const out: ApplicableProductCost[] = []
		for (const row of rows) {
			const options = (row.options as StoredProductCostOption[]) ?? []
			for (const option of options) {
				const startDate = new Date(option.startDate)
				const endDate = option.endDate ? new Date(option.endDate) : null
				if (input.at) {
					if (input.at < startDate) continue
					if (endDate && input.at > endDate) continue
				}
				const data = option.items.map(item =>
					ApplicableProductCostItemSchema.parse({
						cost: item.unitCost.amountCents,
						costOptionItemId: item.id,
						currency: item.unitCost.currency,
						productId: row.productId ?? undefined,
						quantity: item.quantity,
						quantityModifier: item.quantityModifier,
						shipping: item.shipping.amountCents,
						variants: item.variantIds,
					}),
				)
				out.push(
					ApplicableProductCostSchema.parse({
						costId: row.id,
						costOptionId: option.id,
						type: row.costType,
						country: option.country,
						startDate,
						endDate,
						data,
						productId: row.productId ?? undefined,
						shipping: option.shipping.amountCents,
						variants: data.flatMap(d => d.variants ?? []),
					}),
				)
			}
		}
		return out
	}
}

import Papa from 'papaparse'
import type { ParseContext, ParsedProductCostRow, ProductCostCsvRowError } from '../types'

export type RowResult = { ok: true; value: ParsedProductCostRow } | { ok: false; error: ProductCostCsvRowError }

/**
 * Shared CSV tokenization for provider parsers. papaparse handles quoted
 * fields, embedded commas/newlines, and BOM. Subclasses declare their required
 * columns, header normalization (MANUAL preserves camelCase; SHOPIFY lowercases),
 * and per-row validation.
 */
export abstract class BaseProductCostCsvParser {
	protected abstract readonly requiredColumns: readonly string[]
	protected abstract normalizeHeader(header: string): string
	protected abstract validateRow(row: Record<string, string>, rowIndex: number, ctx: ParseContext): RowResult

	parse(csvContent: string, ctx: ParseContext): { rows: ParsedProductCostRow[]; errors: ProductCostCsvRowError[] } {
		const parsed = Papa.parse<Record<string, string>>(csvContent, {
			header: true,
			skipEmptyLines: 'greedy',
			transformHeader: h => this.normalizeHeader(h),
		})

		// Non-empty header names only — a whitespace-only header line trims to ''.
		const fields = (parsed.meta.fields ?? []).map(f => f.trim()).filter(f => f.length > 0)
		if (fields.length === 0) {
			return { rows: [], errors: [{ row: 0, code: 'CSV_EMPTY' }] }
		}
		for (const col of this.requiredColumns) {
			if (!fields.includes(col)) {
				return { rows: [], errors: [{ row: 0, code: 'CSV_MISSING_REQUIRED_COLUMN', value: col }] }
			}
		}

		const rows: ParsedProductCostRow[] = []
		const errors: ProductCostCsvRowError[] = []
		parsed.data.forEach((raw, i) => {
			const rowIndex = i + 1 // 1-based, header excluded
			const result = this.validateRow(raw, rowIndex, ctx)
			if (result.ok) rows.push(result.value)
			else errors.push(result.error)
		})
		return { rows, errors }
	}
}

import { injectable } from 'tsyringe-neo'
import type { ParsedProductCostRow, ProductCostBuildInput, ProductCostCsvParseResult, ProductCostCsvProcessor } from '../types'

const KIT_KEY = ' kit'

@injectable()
export class ManualProductCostCsvProcessor implements ProductCostCsvProcessor {
	async process(rows: ParsedProductCostRow[]): Promise<ProductCostCsvParseResult> {
		const byProduct = new Map<string, ProductCostBuildInput>()
		for (const r of rows) {
			const key = r.productId === null || r.productId === undefined ? KIT_KEY : r.productId
			const option = {
				currency: r.currency,
				country: r.country,
				startDate: r.startDate,
				endDate: r.endDate,
				shipping: r.shipping,
				items: [
					{
						variantIds: r.variantIds!,
						quantity: r.quantity,
						quantityModifier: r.quantityModifier,
						unitCost: r.unitCost,
						shipping: r.shipping,
					},
				],
			}
			const existing = byProduct.get(key)
			if (existing) {
				existing.options.push(option)
				existing.sourceRows.push(r.row)
			} else {
				byProduct.set(key, {
					productId: r.productId ?? null,
					costType: r.costType,
					displayName: r.displayName,
					options: [option],
					sourceRows: [r.row],
				})
			}
		}
		return { builds: [...byProduct.values()], errors: [] }
	}
}

import { injectable } from 'tsyringe-neo'
import { ProductCostType } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductQueryService } from '../../ProductQueryService'
import type { ProductCostOptionInput } from '../../../entities/ProductCost'
import type {
	ParseContext,
	ParsedProductCostRow,
	ProductCostBuildInput,
	ProductCostCsvParseResult,
	ProductCostCsvProcessor,
	ProductCostCsvRowError,
} from '../types'

/**
 * Groups Shopify rows by handle, bulk-resolves (handle → product + variants by
 * title) via ProductQueryService, and emits one SINGLE-cost build per resolved
 * product. Unknown handle / blank or unmatched variant name → typed skip rows.
 */
@injectable()
export class ShopifyProductCostCsvProcessor implements ProductCostCsvProcessor {
	constructor(private readonly products: ProductQueryService) {}

	async process(rows: ParsedProductCostRow[], ctx: ParseContext): Promise<ProductCostCsvParseResult> {
		const errors: ProductCostCsvRowError[] = []
		const byHandle = new Map<string, ParsedProductCostRow[]>()
		for (const r of rows) {
			const list = byHandle.get(r.handle!) ?? []
			list.push(r)
			byHandle.set(r.handle!, list)
		}

		const resolved = await this.products.resolveProductsWithVariantsByHandles(ctx.storeIntegrationId, [...byHandle.keys()])
		const byHandleResolved = new Map(resolved.map(p => [p.handle, p]))

		const builds: ProductCostBuildInput[] = []
		for (const [handle, handleRows] of byHandle) {
			const product = byHandleResolved.get(handle)
			if (!product) {
				for (const r of handleRows) errors.push({ row: r.row, code: 'CSV_UNKNOWN_HANDLE', value: handle })
				continue
			}
			const variantByTitle = new Map(product.variants.map(v => [v.title, v.variantId]))
			const items: ProductCostOptionInput['items'] = []
			const sourceRows: number[] = []
			for (const r of handleRows) {
				if (!r.variantName) {
					errors.push({ row: r.row, code: 'CSV_BLANK_VARIANT_NAME', value: handle })
					continue
				}
				const variantId = variantByTitle.get(r.variantName)
				if (!variantId) {
					errors.push({ row: r.row, code: 'CSV_UNRESOLVED_VARIANT', value: r.variantName })
					continue
				}
				items.push({
					variantIds: [variantId],
					quantity: r.quantity,
					quantityModifier: r.quantityModifier,
					unitCost: r.unitCost,
					shipping: r.shipping,
				})
				sourceRows.push(r.row)
			}
			if (items.length === 0) continue
			const first = handleRows[0]!
			builds.push({
				productId: product.productId,
				costType: ProductCostType.SINGLE,
				options: [
					{
						currency: first.currency,
						startDate: first.startDate,
						endDate: first.endDate,
						shipping: { amountCents: 0, currency: first.currency },
						items,
					},
				],
				sourceRows,
			})
		}

		return { builds, errors }
	}
}

