import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import type Z from 'zod'
import { type MarketingPlatform } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { RevenueTaxSchema, MarketingTaxSchema, MarketingTaxRateSchema } from '../objects'

type RevenueTaxEntry = Z.infer<typeof RevenueTaxSchema>
type MarketingTaxRate = Z.infer<typeof MarketingTaxRateSchema>
type MarketingTaxEntry = Z.infer<typeof MarketingTaxSchema>

/** Flat input accepted by placeMarketingTax — the entity unpacks it into the nested structure. */
export interface MarketingTaxInput {
	platform: MarketingPlatform
	rate: number
	startDate: Date
	endDate: Date | null
}

export const TaxesSchema = z.object({
	storeId: z.instance(Id),
	revenueTax: z.array(RevenueTaxSchema).default([]),
	marketingTax: z.array(MarketingTaxSchema).default([]),
})

export type TaxesProps = Z.infer<typeof TaxesSchema>

/**
 * One row per Store. Each tax block is a time-effective series.
 *
 * `revenueTax` is a single Timeline (whole-value historical) — each entry
 * holds the full revenue-tax configuration (type, deductionType, rate,
 * multiplier) for a given window. `placeRevenueTax` paints a new entry
 * onto this single Timeline.
 *
 * `marketingTax` is indexed by platform. Each entry holds a `rates`
 * array that is a leaf `MarketingTaxRate[]` Timeline for that platform.
 * `placeMarketingTax` accepts a flat input (platform + rate + window)
 * and routes the rate into the correct per-platform leaf Timeline,
 * mirroring how `Fees.placeGatewayFee` routes into per-method Timelines.
 *
 * NOTE: the place* methods intentionally depart from the push-style
 * collection-mutation convention. A Timeline is a last-write-wins interval
 * series, so mutation trims/splits/removes entries via Timeline.place rather
 * than appending an item and returning it (spec Decision 3).
 */
export class Taxes extends AggregateRoot<typeof TaxesSchema> {
	static override schema = TaxesSchema

	static create(data: { storeId: string }): Taxes {
		return new Taxes({ storeId: data.storeId, revenueTax: [], marketingTax: [] })
	}

	/**
	 * Places a full revenue-tax entry onto the single whole-value Timeline.
	 * Each call paints an interval — overlapping entries get trimmed/split.
	 */
	placeRevenueTax(entry: RevenueTaxEntry): void {
		this.revenueTax = [...new Timeline<RevenueTaxEntry>(this.revenueTax).place(entry).entries]
		this.validate()
	}

	/**
	 * Places a marketing-tax rate into the correct per-platform leaf Timeline.
	 * Isolates per platform — placing a new META rate never touches GOOGLE_ADS.
	 */
	placeMarketingTax(input: MarketingTaxInput): void {
		const rate: MarketingTaxRate = {
			rate: input.rate,
			startDate: input.startDate,
			endDate: input.endDate,
		}

		// Find or create the MarketingTax entry for this platform.
		const existing = this.marketingTax.find(m => m.platform === input.platform)
		const others = this.marketingTax.filter(m => m.platform !== input.platform)

		const currentRates: MarketingTaxRate[] = existing?.rates ?? []
		const updatedRates = new Timeline<MarketingTaxRate>(currentRates).place(rate).entries as MarketingTaxRate[]

		const updatedEntry: MarketingTaxEntry = {
			platform: input.platform,
			rates: updatedRates,
		}

		this.marketingTax = [...others, updatedEntry]
		this.validate()
	}
}

export interface Taxes extends TaxesProps {}

