import { injectable } from 'tsyringe-neo'
import { eq } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { taxes } from '@bk-dash/contracts/db'
import type Z from 'zod'
import { Taxes, TaxesSchema } from '../../entities/Taxes'
import { TaxesRepository } from './TaxesRepository'

type TaxesInput = Z.input<typeof TaxesSchema>

/**
 * Drizzle-backed TaxesRepository.
 *
 * One row per Store (UNIQUE on store_id). The two tax collections are
 * embedded jsonb timeline arrays — `z.coerce.date()` in the entity
 * schema rehydrates stored ISO strings back to Date on read, so
 * `toDomain` passes raw jsonb straight through `new Taxes`.
 *
 * `save` upserts on `id` (the aggregate's own PK) so a second call on
 * the same entity updates rather than inserts. The unique index on
 * `store_id` is the DB-level guard that enforces one-row-per-store.
 */
@injectable()
export class DrizzleTaxesRepository extends TaxesRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<Taxes | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(taxes).where(eq(taxes.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findByStoreId(storeId: string, tx?: DrizzleClient): Promise<Taxes | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(taxes).where(eq(taxes.storeId, storeId)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async save(entity: Taxes, tx?: DrizzleClient): Promise<Taxes> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(taxes)
				.values(data)
				.onConflictDoUpdate({
					target: taxes.id,
					set: {
						storeId: data.storeId,
						revenueTax: data.revenueTax,
						marketingTax: data.marketingTax,
						updatedAt: new Date(),
						version: data.version,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(taxes).where(eq(taxes.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof taxes.$inferSelect): Taxes {
		// z.coerce.date() in RevenueTaxSchema / MarketingTaxRateSchema
		// converts stored ISO strings back to Date objects during entity validation.
		return new Taxes({
			id: row.id,
			storeId: row.storeId,
			revenueTax: (row.revenueTax ?? []) as TaxesInput['revenueTax'],
			marketingTax: (row.marketingTax ?? []) as TaxesInput['marketingTax'],
			createdAt: row.createdAt,
			updatedAt: row.updatedAt,
			version: row.version,
		})
	}

	private toPersistence(entity: Taxes): typeof taxes.$inferInsert {
		return {
			id: entity.id.value,
			storeId: entity.storeId.value,
			revenueTax: entity.revenueTax,
			marketingTax: entity.marketingTax,
			version: entity.version,
		}
	}
}

