import { injectable } from 'tsyringe-neo'
import { Handler, z, type Transaction } from '@bk-dash/core-typescript'
import { MarketingPlatform, TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from '../entities/Taxes'
import { TaxesRepository } from '../repositories/TaxesRepository'
import { TaxesUpdatedEvent } from '../events'

export const RevenueTaxBodySchema = z.object({
	type: z.enum(TaxType),
	deductionType: z.enum(TaxDeductionType),
	/** Effective rate as a 0..1 fraction. */
	rate: z.number().min(0).max(1),
	/** Profit-margin safety multiplier (1.0 = neutral). */
	multiplier: z.number().min(0).default(1),
})

export const MarketingTaxBodySchema = z.object({
	platform: z.enum(MarketingPlatform),
	/** Effective rate as a 0..1 fraction. */
	rate: z.number().min(0).max(1),
})

export const UpdateTaxesInputSchema = z.object({
	userId: z.uuid(),
	storeId: z.uuid(),
	revenueTax: RevenueTaxBodySchema.optional(),
	marketingTax: MarketingTaxBodySchema.optional(),
	effectiveFrom: z.date(),
})

export const UpdateTaxesOutputSchema = z.object({ taxesId: z.uuid(), effectiveFrom: z.date() })

/**
 * UpdateTaxes. Find-or-create the store's single
 * Taxes row, then place each supplied tax block onto its
 * Timeline. Emits TaxesUpdatedEvent unconditionally.
 */
@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxesRepo: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const t = (await this.taxesRepo.findByStoreId(input.storeId, tx)) ?? Taxes.create({ storeId: input.storeId })
			const at = { startDate: input.effectiveFrom, endDate: null as Date | null }
			if (input.revenueTax) t.placeRevenueTax({ ...input.revenueTax, ...at })
			if (input.marketingTax) t.placeMarketingTax({ ...input.marketingTax, ...at })
			await this.taxesRepo.save(t, tx)
			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: t.id.value,
					ownerId: input.storeId,
					payload: { taxes: t.toJSON(), effectiveStartDate: input.effectiveFrom, previousTaxesId: null },
				}),
				tx,
			)
			return { taxesId: t.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

