/**
 * C39 UpdateTaxes. Time-effective insert: opens a new row with the
 * supplied effectiveFrom + any patched fields (carrying defaults forward
 * from the previously-active row when present), and supersedes the
 * previous row by stamping its endDate with the new effectiveFrom.
 *
 * The supersession + insert are persisted in a single transaction so
 * reads always see exactly one active row per store.
 */
@injectable()
export class UpdateTaxes extends Handler<typeof UpdateTaxesInputSchema, typeof UpdateTaxesOutputSchema> {
	readonly name = 'update_taxes' as const
	readonly inputSchema = UpdateTaxesInputSchema
	readonly outputSchema = UpdateTaxesOutputSchema

	constructor(private readonly taxes: TaxesRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		return this.withTransaction(tx, async tx => {
			const previous = await this.taxes.findActiveByStoreId(input.storeId, tx)

			const type = input.revenueTaxType ?? previous?.type ?? TaxType.NONE
			const deductionType = input.revenueTaxDeductionType ?? previous?.deductionType ?? TaxDeductionType.NONE
			const ratePct = input.revenueTaxRate ?? (previous ? previous.rate * 100 : 0)
			const rate = ratePct / 100
			const revenueTaxMultiplier = input.revenueTaxMultiplier ?? previous?.revenueTaxMultiplier ?? 1.0
			const marketingTaxRatePerPlatform = input.marketingTaxRatePerPlatform ?? previous?.marketingTaxRatePerPlatform ?? {}

			if (previous) {
				previous.supersede(input.effectiveFrom)
				await this.taxes.save(previous, tx)
			}

			const fresh = Taxes.create({
				storeId: input.storeId,
				type,
				deductionType,
				rate,
				revenueTaxMultiplier,
				marketingTaxRatePerPlatform,
				startDate: input.effectiveFrom,
			})
			await this.taxes.save(fresh, tx)

			await this.domainEventRepository.save(
				new TaxesUpdatedEvent({
					entityId: fresh.id.value,
					ownerId: input.storeId,
					payload: {
						taxes: fresh.toJSON(),
						effectiveStartDate: input.effectiveFrom,
						previousTaxesId: previous?.id.value ?? null,
					},
				}),
				tx,
			)

			return { taxesId: fresh.id.value, effectiveFrom: input.effectiveFrom }
		})
	}
}

