import { describe, it, expect } from 'bun:test'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from './Taxes'

const rev = (startDate: Date, endDate: Date | null = null) => ({
	type: TaxType.PRESUMED_PROFIT,
	deductionType: TaxDeductionType.PRODUCT_COST,
	rate: 0.085,
	multiplier: 1.15,
	startDate,
	endDate,
})

describe('Taxes', () => {
	describe('placeRevenueTax', () => {
		it('places the first revenue tax entry — one entry in the timeline', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeRevenueTax(rev(new Date('2026-01-01'), null))
			expect(t.revenueTax).toHaveLength(1)
			expect(t.revenueTax[0]?.type).toBe(TaxType.PRESUMED_PROFIT)
			expect(t.revenueTax[0]?.rate).toBe(0.085)
		})

		it('supersedes the previous revenue entry when a later one is placed', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeRevenueTax(rev(new Date('2026-01-01'), null))
			t.placeRevenueTax(rev(new Date('2026-06-01'), null))
			// Timeline: [Jan→Jun) + [Jun→∞)
			expect(t.revenueTax).toHaveLength(2)
			// The earlier entry should now be closed (endDate stamped)
			const jan = t.revenueTax.find(e => e.startDate.getTime() === new Date('2026-01-01').getTime())
			expect(jan?.endDate).not.toBeNull()
			const jun = t.revenueTax.find(e => e.startDate.getTime() === new Date('2026-06-01').getTime())
			expect(jun?.endDate).toBeNull()
		})
	})

	describe('placeMarketingTax', () => {
		it('places the first META rate — one platform entry, one rate', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: new Date('2026-01-01'), endDate: null })
			expect(t.marketingTax).toHaveLength(1)
			const meta = t.marketingTax[0]!
			expect(meta.platform).toBe(MarketingPlatform.META)
			expect(meta.rates).toHaveLength(1)
		})

		it('places a GOOGLE_ADS rate independently of META', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: new Date('2026-01-01'), endDate: null })
			t.placeMarketingTax({ platform: MarketingPlatform.GOOGLE_ADS, rate: 0.05, startDate: new Date('2026-01-01'), endDate: null })
			expect(t.marketingTax).toHaveLength(2)
			const meta = t.marketingTax.find(m => m.platform === MarketingPlatform.META)!
			const gads = t.marketingTax.find(m => m.platform === MarketingPlatform.GOOGLE_ADS)!
			expect(meta.rates).toHaveLength(1)
			expect(gads.rates).toHaveLength(1)
		})

		it('superseding META via a new rate adds a second rate entry, GOOGLE_ADS is untouched', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: new Date('2026-01-01'), endDate: null })
			t.placeMarketingTax({ platform: MarketingPlatform.GOOGLE_ADS, rate: 0.05, startDate: new Date('2026-01-01'), endDate: null })
			// New META rate from Jun → trims META timeline only
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.08, startDate: new Date('2026-06-01'), endDate: null })

			const meta = t.marketingTax.find(m => m.platform === MarketingPlatform.META)!
			const gads = t.marketingTax.find(m => m.platform === MarketingPlatform.GOOGLE_ADS)!
			// META: [Jan→Jun) + [Jun→∞)
			expect(meta.rates).toHaveLength(2)
			// GOOGLE_ADS: untouched — one entry
			expect(gads.rates).toHaveLength(1)
		})

		it('revenueTax is untouched when only marketingTax is placed', () => {
			const t = Taxes.create({ storeId: 'store-1' })
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: new Date('2026-01-01'), endDate: null })
			expect(t.revenueTax).toHaveLength(0)
		})
	})
})

