			t.placeMarketingTax({ platform: MarketingPlatform.GOOGLE_ADS, rate: 0.05, startDate: new Date('2026-01-01'), endDate: null })
			// New META rate from Jun → trims META timeline only
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.08, startDate: new Date('2026-06-01'), endDate: null })

			const meta = t.marketingTax.find(m => m.platform === MarketingPlatform.META)!
			const gads = t.marketingTax.find(m => m.platform === MarketingPlatform.GOOGLE_ADS)!
			// META: [Jan→Jun) + [Jun→∞)
			expect(meta.rates).toHaveLength(2)
			// GOOGLE_ADS: untouched — one entry
			expect(gads.rates).toHaveLength(1)
		})

		it('revenueTax is untouched when only marketingTax is placed', () => {
