import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { MarketingPlatform, TaxDeductionType, TaxType } from '@bk-dash/contracts-typescript/wire/enums'
import { Taxes } from '../../entities/Taxes'
import { TaxesRepository } from './TaxesRepository'

const STORE_A = testId('store', 'a')
const STORE_B = testId('store', 'b')

describe('DrizzleTaxesRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: TaxesRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(TaxesRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	describe('save + findById', () => {
		it('round-trips revenue timeline with coerced Date windows', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			t.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.085,
				multiplier: 1.15,
				startDate: new Date('2026-01-01T00:00:00.000Z'),
				endDate: new Date('2026-06-01T00:00:00.000Z'),
			})
			t.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.09,
				multiplier: 1.0,
				startDate: new Date('2026-06-01T00:00:00.000Z'),
				endDate: null,
			})
			await repo.save(t)

			const fetched = await repo.findById(t.id.value)
			expect(fetched?.revenueTax).toHaveLength(2)
			expect(fetched?.revenueTax[0]?.startDate).toBeInstanceOf(Date)
			expect(fetched?.revenueTax[0]?.endDate).toBeInstanceOf(Date)
