				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.085,
				multiplier: 1.15,
				startDate: new Date('2026-01-01T00:00:00.000Z'),
				endDate: new Date('2026-06-01T00:00:00.000Z'),
			})
			t.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.09,
				multiplier: 1.0,
				startDate: new Date('2026-06-01T00:00:00.000Z'),
				endDate: null,
			})
			await repo.save(t)

			const fetched = await repo.findById(t.id.value)
			expect(fetched?.revenueTax).toHaveLength(2)
			expect(fetched?.revenueTax[0]?.startDate).toBeInstanceOf(Date)
			expect(fetched?.revenueTax[0]?.endDate).toBeInstanceOf(Date)
			expect(fetched?.revenueTax[1]?.endDate).toBeNull()
			expect(fetched?.revenueTax[0]?.rate).toBe(0.085)
			expect(fetched?.revenueTax[1]?.rate).toBe(0.09)
		})

		it('round-trips marketing timeline with coerced Date windows', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			t.placeMarketingTax({ platform: MarketingPlatform.META, rate: 0.07, startDate: new Date('2026-01-01T00:00:00.000Z'), endDate: null })
			t.placeMarketingTax({ platform: MarketingPlatform.GOOGLE_ADS, rate: 0.05, startDate: new Date('2026-01-01T00:00:00.000Z'), endDate: null })
			await repo.save(t)

			const fetched = await repo.findById(t.id.value)
			expect(fetched?.marketingTax).toHaveLength(2)
			const meta = fetched?.marketingTax.find(m => m.platform === MarketingPlatform.META)
			expect(meta?.rates).toHaveLength(1)
			expect(meta?.rates[0]?.startDate).toBeInstanceOf(Date)
			expect(meta?.rates[0]?.rate).toBe(0.07)
		})

		it('round-trips empty timeline arrays', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			await repo.save(t)

			const fetched = await repo.findById(t.id.value)
			expect(fetched?.revenueTax).toEqual([])
			expect(fetched?.marketingTax).toEqual([])
		})

		it('returns undefined when no row matches', async () => {
			expect(await repo.findById(testId())).toBeUndefined()
		})

		it('UPSERT on save bumps version', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			await repo.save(t)
			await repo.save(t)

			const fetched = await repo.findById(t.id.value)
			expect(fetched?.version).toBeGreaterThan(1)
		})
	})

	describe('findByStoreId', () => {
		it('returns undefined when no row exists for that store', async () => {
			expect(await repo.findByStoreId(STORE_A)).toBeUndefined()
		})

		it('returns the single row for the store', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			t.placeRevenueTax({
				type: TaxType.PRESUMED_PROFIT,
				deductionType: TaxDeductionType.PRODUCT_COST,
				rate: 0.085,
				multiplier: 1.0,
				startDate: new Date('2026-01-01T00:00:00.000Z'),
				endDate: null,
			})
			await repo.save(t)

			const found = await repo.findByStoreId(STORE_A)
			expect(found?.id.value).toBe(t.id.value)
			expect(found?.revenueTax).toHaveLength(1)
		})

		it('isolates by storeId', async () => {
			const a = Taxes.create({ storeId: STORE_A })
			const b = Taxes.create({ storeId: STORE_B })
			await repo.save(a)
			await repo.save(b)

			const ra = await repo.findByStoreId(STORE_A)
			const rb = await repo.findByStoreId(STORE_B)
			expect(ra?.storeId.value).toBe(STORE_A)
			expect(rb?.storeId.value).toBe(STORE_B)
		})
	})

	describe('delete', () => {
		it('removes the row + subsequent findById returns undefined', async () => {
			const t = Taxes.create({ storeId: STORE_A })
			await repo.save(t)
			await repo.delete(t.id.value)
			expect(await repo.findById(t.id.value)).toBeUndefined()
		})
	})
})

