	// Zod v4: def.type is 'union' for discriminated unions; use instanceof instead.
	if (schema instanceof ZodDiscriminatedUnion) {
		// Access def via unknown cast — Zod v4 generics are complex; we only need
		// the discriminator string and the options array of ZodObjects at runtime.
		const du = schema as unknown as { def: { discriminator: string; options: ZodObject<ZodRawShape>[] } }
		const widened = du.def.options.map(o => o.extend(TimeWindowShape))
		return (z.discriminatedUnion(du.def.discriminator, widened as never) as ZodTypeAny).refine(windowIsValid, INVALID_RANGE)
	}
	// Plain ZodObject or any other schema — extend + refine
	return (schema as ZodObject<ZodRawShape>).extend(TimeWindowShape).refine(windowIsValid, INVALID_RANGE)
}

/**
 * Creates a schema that parses input and transforms it into a class instance.
 * The class must have a static `schema` property (BaseValueObject, BasePrimitiveValueObject, or BaseEntity).
 *
 * @example
 * ```ts
 * crm: z.instance(CRM),
 * userId: z.instance(Id),
 * specialties: z.array(z.instance(DoctorSpecialty)).default([]),
 * ```
 */
function instance<S extends ZodTypeAny, T>(Cls: { schema: S; new (props: any): T }): z.ZodType<T, T | z.input<S>> {
	// Accept already-constructed instances (idempotent for re-validation via
	// this.validate()) OR raw input (the constructor validates via static
	// schema). The declared input type mirrors both runtime branches so
	// call sites can pass either an instance or a props object without casts.
	return z.unknown().transform((v: any) => (v instanceof Cls ? v : new Cls(v))) as z.ZodType<T, T | z.input<S>>
}

// Export all extra schema types with camelCase naming to match Zod convention
export const ExtraSchemaTypes = {
	paginatedQuery,
	paginatedResponse,
	baseEvent,
	domainEvent,
	integrationEvent,
	instance,
	historical,
}

import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import type Z from 'zod'
import { type PaymentGateway, type PaymentMethod, type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { GatewayFeeRateSchema, GatewayFeeSchema, CheckoutFeeSchema, ShippingFeeSchema } from '../objects'

type GatewayFeeEntry = Z.infer<typeof GatewayFeeSchema>
type GatewayFeeRate = Z.infer<typeof GatewayFeeRateSchema>
type CheckoutFeeEntry = Z.infer<typeof CheckoutFeeSchema>
type ShippingFeeEntry = Z.infer<typeof ShippingFeeSchema>

/** Flat input accepted by placeGatewayFee — the entity unpacks it into the nested structure. */
export interface GatewayFeeInput {
	platform: PaymentGateway
	paymentMethod: PaymentMethod
	variable: number
	fixed: { amountCents: number; currency: CurrencyCode }
	startDate: Date
	endDate: Date | null
}

export const FeesSchema = z.object({
	storeId: z.instance(Id),
	gatewayFees: z.array(GatewayFeeSchema).default([]),
	checkoutFee: z.array(CheckoutFeeSchema).default([]),
	shippingFee: z.array(ShippingFeeSchema).default([]),
})

export type FeesProps = Z.infer<typeof FeesSchema>

/**
 * One row per Store. Each fee block is a time-effective series.
 *
 * `gatewayFees` is indexed by platform. Each entry holds a `methods` record
 * mapping each PaymentMethod to its leaf `GatewayFeeRate[]` timeline. The
 * `placeGatewayFee` method accepts a flat input (platform + paymentMethod +
 * variable + fixed + window) and routes the rate into the correct per-method
 * Timeline inside the right platform entry.
 *
 * Checkout and shipping are single Timelines (whole-value historical).
 *
 * NOTE: the place* methods intentionally depart from the push-style
 * collection-mutation convention. A Timeline is a last-write-wins interval
 * series, so mutation trims/splits/removes entries via Timeline.place rather
 * than appending an item and returning it (spec Decision 3).
 */
export class Fees extends AggregateRoot<typeof FeesSchema> {
	static override schema = FeesSchema

	static create(data: { storeId: string }): Fees {
		return new Fees({ storeId: data.storeId, gatewayFees: [], checkoutFee: [], shippingFee: [] })
	}

	/**
	 * Places a flat gateway fee rate into the correct per-platform, per-method
	 * leaf Timeline. Isolates per (platform × paymentMethod) — placing a new
	 * STRIPE/CREDIT_CARD rate never touches PAYPAL/PIX.
	 */
	placeGatewayFee(fee: GatewayFeeInput): void {
		const rate: GatewayFeeRate = {
			variable: fee.variable,
			fixed: fee.fixed,
			startDate: fee.startDate,
			endDate: fee.endDate,
		}

		// Find or create the GatewayFee entry for this platform.
		const existing = this.gatewayFees.find(f => f.platform === fee.platform)
		const others = this.gatewayFees.filter(f => f.platform !== fee.platform)

		const currentMethods = existing?.methods ?? {}
		const currentRates: GatewayFeeRate[] = (currentMethods[fee.paymentMethod] as GatewayFeeRate[] | undefined) ?? []
		const updatedRates = new Timeline<GatewayFeeRate>(currentRates).place(rate).entries as GatewayFeeRate[]

		const updatedEntry: GatewayFeeEntry = {
			platform: fee.platform,
			methods: { ...currentMethods, [fee.paymentMethod]: updatedRates },
		}

		this.gatewayFees = [...others, updatedEntry]
		this.validate()
	}

	placeCheckoutFee(fee: CheckoutFeeEntry): void {
		this.checkoutFee = [...new Timeline<CheckoutFeeEntry>(this.checkoutFee).place(fee).entries]
		this.validate()
	}

	placeShippingFee(fee: ShippingFeeEntry): void {
		this.shippingFee = [...new Timeline<ShippingFeeEntry>(this.shippingFee).place(fee).entries]
		this.validate()
	}
}

export interface Fees extends FeesProps {}

