import { z, type ZodObject, type ZodRawShape, type ZodTypeAny, type ZodLiteral, ZodDiscriminatedUnion } from 'zod'
import { stringToInteger } from './Transforms'
import { BaseEventSchema } from '../../types/BaseEvent'
import { BaseDomainEventSchema } from '../../types/BaseDomainEvent'
import { BaseIntegrationEventSchema } from '../../types/BaseIntegrationEvent'

// Meta options with examples
interface SchemaOptions {
	examples?: unknown[]
}

type IntegrationEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: ZodObject<T> }
>

type IntegrationEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: T }
>

type DomainEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

type DomainEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: T }
>

type BaseEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

// Helper to get examples from schema meta
const getExamples = (schema: ZodTypeAny): unknown[] => {
	// Access meta from the schema definition - Zod v4 uses 'def' property
	const def = (schema as unknown as { def?: { meta?: SchemaOptions } }).def
	return def?.meta?.examples ?? []
}

// Helper function to merge examples from two schemas
const mergeExamples = (baseExamples: unknown[] = [], additionalExamples: unknown[] = []) => {
	if (baseExamples.length === 0) return additionalExamples
	if (additionalExamples.length === 0) return baseExamples

	const merged: unknown[] = []

	// Create all possible combinations
	for (const baseExample of baseExamples) {
		for (const additionalExample of additionalExamples) {
			merged.push({
				...(baseExample as object),
				...(additionalExample as object),
			})
		}
	}

	return merged
}

// PaginatedQuery schema
export const PaginatedQuery = z
	.object({
		page: stringToInteger({ minimum: 1 }).default(1),
		limit: stringToInteger({ minimum: 1, maximum: 100 }).default(10),
		search: z.string().optional(),
	})
	.meta({
		examples: [
			{
				limit: 10,
				page: 1,
				search: 'Kitten drinking coffee.',
			},
		],
	})

/**
 * Builds a paginated query schema with additional properties
 */
export function paginatedQuery(properties?: undefined, options?: SchemaOptions): typeof PaginatedQuery
export function paginatedQuery<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<(typeof PaginatedQuery)['shape'] & T>
export function paginatedQuery<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return PaginatedQuery

	const baseExamples = getExamples(PaginatedQuery)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	return z
		.object({
			...PaginatedQuery.shape,
			...properties,
		})
		.meta({ examples: mergedExamples })
}

// PaginatedData base schema
export const PaginatedData = z
	.object({
		items: z.array(z.unknown()),
		total: z.number(),
		totalPages: z.number(),
	})
	.meta({ examples: [] })

/**
 * Builds a paginated response schema with typed items
 */
export function paginatedResponse<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<{
	items: z.ZodArray<ZodObject<T>>
	total: z.ZodNumber
	totalPages: z.ZodNumber
}> {
	const baseExamples = getExamples(PaginatedData)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	const itemSchema = z.object(properties)
	const itemsArraySchema = z.array(itemSchema)

	return z
		.object({
			items: itemsArraySchema,
			total: z.number(),
			totalPages: z.number(),
		})
		.meta({ examples: mergedExamples }) as any
}

/**
 * Builds a base event schema with custom payload properties
 */
export function baseEvent(properties?: undefined, options?: SchemaOptions): typeof BaseEventSchema
export function baseEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): BaseEventObjectSchema<T>
export function baseEvent<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return BaseEventSchema.meta({ examples: options?.examples ?? [] })

	const payloadSchema = z.object(properties)
	const mergedExamples = options?.examples ?? []

	const { payload: _payload, ...baseShape } = BaseEventSchema.shape

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}

/**
 * Builds a domain event schema with custom payload properties
 */
export function domainEvent(properties?: undefined, options?: SchemaOptions): typeof BaseDomainEventSchema
export function domainEvent<T extends ZodTypeAny>(schema: T, options?: SchemaOptions): DomainEventWithPayloadSchema<T>
export function domainEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): DomainEventObjectSchema<T>
export function domainEvent(properties?: ZodRawShape | ZodTypeAny, options?: SchemaOptions) {
	if (!properties) return BaseDomainEventSchema.meta({ examples: options?.examples ?? [] })

	const mergedExamples = options?.examples ?? []
	const { payload: _payload, ...baseShape } = BaseDomainEventSchema.shape

	const payloadSchema = '_zod' in properties ? properties : z.object(properties as ZodRawShape)

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}
/**
 * Builds an integration event schema with a baked-in z.literal name for discriminatedUnion support.
 */
export function integrationEvent(
	name: string,
	options?: SchemaOptions,
): ZodObject<{
	name: ZodLiteral<string>
	payload: (typeof BaseIntegrationEventSchema)['shape']['payload']
	ownerId: (typeof BaseIntegrationEventSchema)['shape']['ownerId']
}>
export function integrationEvent<T extends ZodTypeAny>(
	name: string,
	schema: T,
	options?: SchemaOptions,
): IntegrationEventWithPayloadSchema<T>
export function integrationEvent<T extends ZodRawShape>(
	name: string,
	properties: T,
	options?: SchemaOptions,
): IntegrationEventObjectSchema<T>
export function integrationEvent(name: string, properties?: ZodRawShape | ZodTypeAny | SchemaOptions, options?: SchemaOptions) {
	// Allow (name) / (name, options) / (name, schema) / (name, schema, options) / (name, properties, options).
	let resolvedProperties: ZodRawShape | ZodTypeAny | undefined
	let resolvedOptions: SchemaOptions | undefined

	if (properties && typeof properties === 'object' && !('_zod' in properties) && !Array.isArray(properties)) {
		// Either ZodRawShape or SchemaOptions (which has only `examples`).
		const keys = Object.keys(properties)
		const looksLikeOptions = keys.length === 1 && keys[0] === 'examples'
		if (looksLikeOptions) {
			resolvedOptions = properties as SchemaOptions
		} else {
			resolvedProperties = properties as ZodRawShape
			resolvedOptions = options
		}
	} else if (properties && '_zod' in (properties as object)) {
		resolvedProperties = properties as ZodTypeAny
		resolvedOptions = options
	} else {
		resolvedOptions = options
	}

	const mergedExamples = resolvedOptions?.examples ?? []
	const { name: _name, payload: _payload, ...baseShape } = BaseIntegrationEventSchema.shape

	if (resolvedProperties === undefined) {
		return z
			.object({ ...baseShape, name: z.literal(name), payload: BaseIntegrationEventSchema.shape.payload })
			.meta({ examples: mergedExamples })
	}

	const payloadSchema =
		'_zod' in (resolvedProperties as object) ? (resolvedProperties as ZodTypeAny) : z.object(resolvedProperties as ZodRawShape)

	return z.object({ ...baseShape, name: z.literal(name), payload: payloadSchema }).meta({ examples: mergedExamples })
}

// Time-effective window appended to any schema by `z.historical`. `endDate`
// null = open-ended / currently active. `z.coerce.date()` lets jsonb-stored
// ISO strings rehydrate to Date on read without manual parsing.
const TimeWindowShape = {
	startDate: z.coerce.date(),
	endDate: z.coerce.date().nullable().default(null),
}

// Cast to the broader refine callback type Zod v4 expects internally.
const windowIsValid = (w: unknown) => {
	const win = w as { startDate: Date; endDate: Date | null }
	return win.endDate === null || win.startDate < win.endDate
}
const INVALID_RANGE = { error: 'INVALID_DATE_RANGE' } as const

/**
 * Extends a schema with a validated `[startDate, endDate)` window.
 * Accepts a raw shape, a ZodObject, or a discriminated union (window
 * applied per-variant so the discriminator stays narrowable).
 *
 * `endDate` is nullable with a default of `null` (open-ended / currently active).
 * `z.coerce.date()` lets jsonb-stored ISO strings rehydrate to Date on read.
 * A `startDate < endDate` refine emits `INVALID_DATE_RANGE` on violation.
 */
export function historical<T extends ZodRawShape>(shape: T): ZodObject<T & typeof TimeWindowShape>
export function historical<T extends ZodTypeAny>(schema: T): z.ZodType<z.output<T> & { startDate: Date; endDate: Date | null }>
export function historical(input: ZodRawShape | ZodTypeAny): ZodTypeAny {
	if (!('_zod' in (input as object))) {
		// Raw shape — wrap in ZodObject then extend + refine
		return (z.object(input as ZodRawShape) as ZodObject<ZodRawShape>)
			.extend(TimeWindowShape)
			.refine(windowIsValid, INVALID_RANGE) as unknown as ZodTypeAny
	}
	const schema = input as ZodTypeAny
	// Discriminated union — extend each variant so the discriminator stays narrowable.
	// Zod v4: def.type is 'union' for discriminated unions; use instanceof instead.
	if (schema instanceof ZodDiscriminatedUnion) {
		// Access def via unknown cast — Zod v4 generics are complex; we only need
		// the discriminator string and the options array of ZodObjects at runtime.
		const du = schema as unknown as { def: { discriminator: string; options: ZodObject<ZodRawShape>[] } }
		const widened = du.def.options.map(o => o.extend(TimeWindowShape))
		return (z.discriminatedUnion(du.def.discriminator, widened as never) as ZodTypeAny).refine(windowIsValid, INVALID_RANGE)
	}
	// Plain ZodObject or any other schema — extend + refine
	return (schema as ZodObject<ZodRawShape>).extend(TimeWindowShape).refine(windowIsValid, INVALID_RANGE)
}

/**
 * Creates a schema that parses input and transforms it into a class instance.
 * The class must have a static `schema` property (BaseValueObject, BasePrimitiveValueObject, or BaseEntity).
 *
 * @example
 * ```ts
 * crm: z.instance(CRM),
 * userId: z.instance(Id),
 * specialties: z.array(z.instance(DoctorSpecialty)).default([]),
 * ```
 */
function instance<S extends ZodTypeAny, T>(Cls: { schema: S; new (props: any): T }): z.ZodType<T, T | z.input<S>> {
	// Accept already-constructed instances (idempotent for re-validation via
	// this.validate()) OR raw input (the constructor validates via static
	// schema). The declared input type mirrors both runtime branches so
	// call sites can pass either an instance or a props object without casts.
	return z.unknown().transform((v: any) => (v instanceof Cls ? v : new Cls(v))) as z.ZodType<T, T | z.input<S>>
}

// Export all extra schema types with camelCase naming to match Zod convention
export const ExtraSchemaTypes = {
	paginatedQuery,
	paginatedResponse,
	baseEvent,
	domainEvent,
	integrationEvent,
	instance,
	historical,
}

import { AggregateRoot, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const FxRateSchema = z.object({
	fromCurrency: z.enum(CurrencyCode),
	toCurrency: z.enum(CurrencyCode),
	/** Rate carried as string to preserve provider-side decimal precision. */
	rate: z.string(),
	startDate: z.date(),
})

export type FxRateProps = Z.infer<typeof FxRateSchema>

/**
 * `FxRate` aggregate per spec § 1.2 FX Management. Captured rates form a
 * historical series; consumers resolve the latest entry
 * with `startDate <= asOf` for a (from, to) pair.
 *
 * Identity rates (from == to) are derived in code (always "1.0"), not
 * persisted.
 */
export class FxRate extends AggregateRoot<typeof FxRateSchema> {
	static override schema = FxRateSchema

	static create(data: {
		fromCurrency: CurrencyCode
		toCurrency: CurrencyCode
		rate: string
		startDate: Date
	}): FxRate {
		return new FxRate({ ...data })
	}
}

export interface FxRate extends FxRateProps {}

import { z } from '@bk-dash/core-typescript'
import type Z from 'zod'
import { TaxType, TaxDeductionType } from '@bk-dash/contracts-typescript/wire/enums'

export const RevenueTaxSchema = z.historical({
	type: z.enum(TaxType),
	deductionType: z.enum(TaxDeductionType),
	/** Effective rate as a 0..1 fraction. */
	rate: z.number().min(0).max(1),
	/** Profit-margin safety multiplier (1.0 = neutral). */
	multiplier: z.number().min(0).default(1),
})

export type RevenueTax = Z.infer<typeof RevenueTaxSchema>

import { injectable } from 'tsyringe-neo'
import { and, count, desc, eq, gte, lte, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { fxRates } from '@bk-dash/contracts/db'
import { type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { FxRate, FxRateSchema } from '../../entities/FxRate'
import { FxRateRepository, type FxRateListQuery, type FxRateListResult } from './FxRateRepository'

/**
 * Drizzle-backed FxRateRepository (iter 303 — closes one more row of
 * the iter-300 known-gap §1). Append-only by design: `save` issues an
 * INSERT keyed by id with `onConflictDoUpdate` for idempotent
 * re-ingest. The DB row has no `updatedAt` or `version` columns
 * (matches the entity's append-only semantics) — `incrementVersion`
 * still bumps in-memory state for the base class invariant but is not
 * persisted.
 *
 * `findEffective` runs the canonical "rate at time T" lookup:
 *   WHERE from_currency=? AND to_currency=? AND start_date<=?
 *   ORDER BY start_date DESC LIMIT 1
 * which the `pair_start_date_idx` covers as a single-page seek.
 */
@injectable()
export class DrizzleFxRateRepository extends FxRateRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(fxRates).where(eq(fxRates.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(fxRates)
				.where(and(eq(fxRates.fromCurrency, fromCurrency), eq(fxRates.toCurrency, toCurrency), lte(fxRates.startDate, asOf)))
				.orderBy(desc(fxRates.startDate))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async list(query: FxRateListQuery, tx?: DrizzleClient): Promise<FxRateListResult> {
		const dbc = tx ?? this.db
		const filters = [] as any[]
		if (query.fromCurrency !== undefined) filters.push(eq(fxRates.fromCurrency, query.fromCurrency))
		if (query.toCurrency !== undefined) filters.push(eq(fxRates.toCurrency, query.toCurrency))
		if (query.from !== undefined) filters.push(gte(fxRates.startDate, query.from))
		if (query.to !== undefined) filters.push(lte(fxRates.startDate, query.to))
		const whereClause = filters.length > 0 ? and(...filters) : sql`true`
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc.select().from(fxRates).where(whereClause).orderBy(desc(fxRates.startDate)).limit(query.limit).offset(offset),
				dbc.select({ value: count() }).from(fxRates).where(whereClause),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: FxRate, tx?: DrizzleClient): Promise<FxRate> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(fxRates)
				.values(data)
				.onConflictDoUpdate({
					target: fxRates.id,
					set: {
						fromCurrency: data.fromCurrency,
						toCurrency: data.toCurrency,
						rate: data.rate,
						startDate: data.startDate,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(fxRates).where(eq(fxRates.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof fxRates.$inferSelect): FxRate {
		const parsed = FxRateSchema.parse({
			fromCurrency: row.fromCurrency,
			toCurrency: row.toCurrency,
			rate: row.rate,
			startDate: row.startDate,
		})
		return new FxRate({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
		})
	}

	private toPersistence(entity: FxRate): typeof fxRates.$inferInsert {
		return {
			id: entity.id.value,
			fromCurrency: entity.fromCurrency,
			toCurrency: entity.toCurrency,
			rate: entity.rate,
			startDate: entity.startDate,
		}
	}
}

import { injectable } from 'tsyringe-neo'
import type { Transaction } from '@bk-dash/core-typescript'
import type { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { FxRate } from '../../entities/FxRate'
import { FxRateRepository, type FxRateListQuery, type FxRateListResult } from './FxRateRepository'

@injectable()
export class MockFxRateRepository extends FxRateRepository {
	private rows = new Map<string, FxRate>()

	async findById(id: string, _tx?: Transaction): Promise<FxRate | undefined> {
		return this.rows.get(id)
	}

	async findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, _tx?: Transaction): Promise<FxRate | undefined> {
		const candidates = [...this.rows.values()]
			.filter(r => r.fromCurrency === fromCurrency && r.toCurrency === toCurrency && r.startDate <= asOf)
			.sort((a, b) => (a.startDate < b.startDate ? 1 : -1))
		return candidates[0]
	}

	async list(query: FxRateListQuery, _tx?: Transaction): Promise<FxRateListResult> {
		const matched = [...this.rows.values()].filter(r => {
			if (query.fromCurrency !== undefined && r.fromCurrency !== query.fromCurrency) return false
			if (query.toCurrency !== undefined && r.toCurrency !== query.toCurrency) return false
			if (query.from !== undefined && r.startDate < query.from) return false
			if (query.to !== undefined && r.startDate > query.to) return false
			return true
		})
		matched.sort((a, b) => (a.startDate < b.startDate ? 1 : -1))
		const start = (query.page - 1) * query.limit
		return { total: matched.length, items: matched.slice(start, start + query.limit) }
	}

	async save(entity: FxRate, _tx?: Transaction): Promise<FxRate> {
		entity.incrementVersion()
		this.rows.set(entity.id.value, entity)
		return entity
	}

	async delete(id: string, _tx?: Transaction): Promise<void> {
		this.rows.delete(id)
	}

	seed(entity: FxRate): void {
		this.rows.set(entity.id.value, entity)
	}

	clear(): void {
		this.rows.clear()
	}
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed } from '@test/support'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { GetFxRates } from './GetFxRates'
import { UpdateFxRates } from './UpdateFxRates'
import { FxRateRepository } from '../repositories/FxRateRepository'
import { FxRate } from '../entities/FxRate'
import { FxRateCapturedEvent } from '../events'

describe('FxRate (C48 UpdateFxRates + T28 GetFxRates)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let list: GetFxRates
	let capture: UpdateFxRates
	let repo: FxRateRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		list = testBed.resolve(GetFxRates)
		capture = testBed.resolve(UpdateFxRates)
		repo = testBed.resolve(FxRateRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seed(rate: {
		from: CurrencyCode
		to: CurrencyCode
		rate: string
		startDate: string
	}): Promise<FxRate> {
		const entity = FxRate.create({
			fromCurrency: rate.from,
			toCurrency: rate.to,
			rate: rate.rate,
			startDate: new Date(rate.startDate),
		})
		await repo.save(entity)
		return entity
	}

	describe('GetFxRates (T28)', () => {
		it('returns total=0 + empty items when no captured rates exist', async () => {
			const r = await list.execute({ page: 1, limit: 10 })
			expect(r.total).toBe(0)
			expect(r.items).toEqual([])
		})

		it('lists captured rates newest-first', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ page: 1, limit: 10 })
			expect(r.items.map(i => i.rate)).toEqual(['5.25', '5.10'])
		})

		it('filters by currency pair', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.EUR, to: CurrencyCode.BRL, rate: '5.60', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ fromCurrency: CurrencyCode.EUR, page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]!.fromCurrency).toBe(CurrencyCode.EUR)
		})

		it('filters by date range', async () => {
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.10', startDate: '2026-04-01T00:00:00.000Z' })
			await seed({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' })

			const r = await list.execute({ from: new Date('2026-05-01'), to: new Date('2026-12-31'), page: 1, limit: 10 })
			expect(r.total).toBe(1)
			expect(r.items[0]!.rate).toBe('5.25')
		})
	})

	describe('UpdateFxRates (C48)', () => {
		async function readCapturedEvents() {
			return testBed.resolve(DomainEventRepository).findByType(FxRateCapturedEvent)
		}

		it('persists each non-identity rate + emits one FxRateCapturedEvent per row', async () => {
			const startDate = new Date('2026-06-15T00:00:00.000Z')
			const out = await capture.execute({
				startDate,
				rates: [
					{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.BRL, rate: '5.25' },
					{ fromCurrency: CurrencyCode.EUR, toCurrency: CurrencyCode.BRL, rate: '5.60' },
					{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.USD, rate: '1.0' }, // identity — filtered out
				],
			})
			expect(out.captured).toBe(2)

			const emitted = await readCapturedEvents()
			expect(emitted).toHaveLength(2)
			expect(emitted.map(e => e.payload.rate).sort()).toEqual(['5.25', '5.60'])

			// Captured rate is now persisted + resolvable via the repo.
			const effective = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-20'))
			expect(effective?.rate).toBe('5.25')
		})

		it('throws FX_RATE_CAPTURE_EMPTY when all supplied pairs are identity', async () => {
			await expect(
				capture.execute({
					startDate: new Date('2026-06-15T00:00:00.000Z'),
					rates: [
						{ fromCurrency: CurrencyCode.USD, toCurrency: CurrencyCode.USD, rate: '1.0' },
						{ fromCurrency: CurrencyCode.BRL, toCurrency: CurrencyCode.BRL, rate: '1.0' },
					],
				}),
			).rejects.toMatchObject({ name: 'FX_RATE_CAPTURE_EMPTY' })
		})
	})
})

import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'

import { FxRate } from '../entities/FxRate'
import { FxRateRepository } from '../repositories/FxRateRepository'
import { FxRateCapturedEvent } from '../events'
import type { FinanceApplicationErrors } from '../errors'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const UpdateFxRatesInputSchema = z.object({
	startDate: z.date(),
	rates: z
		.array(
			z.object({
				fromCurrency: z.enum(CurrencyCode),
				toCurrency: z.enum(CurrencyCode),
				rate: z.string(),
			}),
		)
		.min(1),
})

export const UpdateFxRatesOutputSchema = z.object({
	captured: z.number().int().nonnegative(),
})

/**
 * C48 UpdateFxRates. Per spec § 1.2 FX Management + § Scheduled Flows:
 * "Hourly: UpdateFxRates (TS) → FxRateCaptured." Persists a batch of
 * captured rates as new FxRate aggregates; each emits a
 * FxRateCapturedEvent so Analytics can invalidate profit-margin caches
 * that fold in the rate. Identity rates (from == to) are filtered out —
 * those are always "1.0" by the resolver short-circuit.
 *
 * Input is the rate payload coming from the scheduled fetcher (provider
 * stubbed for offline use). Use case is the seam: the fetcher reads the
 * provider, batches the per-pair list, and calls execute() once per
 * tick.
 */
@injectable()
export class UpdateFxRates extends Handler<typeof UpdateFxRatesInputSchema, typeof UpdateFxRatesOutputSchema> {
	readonly name = 'update_fx_rates' as const
	readonly inputSchema = UpdateFxRatesInputSchema
	readonly outputSchema = UpdateFxRatesOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		const nonIdentity = input.rates.filter(r => r.fromCurrency !== r.toCurrency)
		if (nonIdentity.length === 0) {
			throw new BaseError<FinanceApplicationErrors>('FX_RATE_CAPTURE_EMPTY')
		}

		return this.withTransaction(tx, async tx => {
			let captured = 0
			for (const r of nonIdentity) {
				const entity = FxRate.create({
					fromCurrency: r.fromCurrency,
					toCurrency: r.toCurrency,
					rate: r.rate,
					startDate: input.startDate,
				})
				await this.fxRates.save(entity, tx)
				await this.domainEventRepository.save(
					new FxRateCapturedEvent({
						entityId: entity.id.value,
						payload: {
							fxRateId: entity.id.value,
							fromCurrency: r.fromCurrency,
							toCurrency: r.toCurrency,
							rate: r.rate,
							startDate: input.startDate,
						},
					}),
					tx,
				)
				captured++
			}
			return { captured }
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { Handler, z, DrizzleClient } from '@bk-dash/core-typescript'

import { FxRateRepository } from '../repositories/FxRateRepository'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const GetFxRatesInputSchema = z.object({
	fromCurrency: z.enum(CurrencyCode).optional(),
	toCurrency: z.enum(CurrencyCode).optional(),
	from: z.date().optional(),
	to: z.date().optional(),
	page: z.number().int().min(1).default(1),
	limit: z.number().int().min(1).max(500).default(100),
})

export const GetFxRatesOutputSchema = z.object({
	total: z.number().int().min(0),
	items: z.array(
		z.object({
			fromCurrency: z.enum(CurrencyCode),
			toCurrency: z.enum(CurrencyCode),
			rate: z.string(),
			startDate: z.date(),
		}),
	),
})

/** T28 GetFxRates. Paginated historical series across all (from, to) pairs. */
@injectable()
export class GetFxRates extends Handler<typeof GetFxRatesInputSchema, typeof GetFxRatesOutputSchema> {
	readonly name = 'get_fx_rates' as const
	readonly inputSchema = GetFxRatesInputSchema
	readonly outputSchema = GetFxRatesOutputSchema

	constructor(private readonly fxRates: FxRateRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: DrizzleClient): Promise<this['output']> {
		const result = await this.fxRates.list(
			{
				fromCurrency: input.fromCurrency,
				toCurrency: input.toCurrency,
				from: input.from,
				to: input.to,
				page: input.page,
				limit: input.limit,
			},
			tx,
		)
		return {
			total: result.total,
			items: result.items.map(r => ({
				fromCurrency: r.fromCurrency,
				toCurrency: r.toCurrency,
				rate: r.rate,
				startDate: r.startDate,
			})),
		}
	}
}

import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { BaseDomainEvent, z } from '@bk-dash/core-typescript'

export const FxRateCapturedEventSchema = z.domainEvent({
	fxRateId: z.uuid(),
	fromCurrency: z.enum(CurrencyCode),
	toCurrency: z.enum(CurrencyCode),
	rate: z.string(),
	startDate: z.date(),
})

export class FxRateCapturedEvent extends BaseDomainEvent<typeof FxRateCapturedEventSchema> {
	static override readonly name = 'finance.fx_rate.captured' as const
	static readonly schema = FxRateCapturedEventSchema
}

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { FxRate } from '../../entities/FxRate'
import { FxRateRepository } from './FxRateRepository'

describe('DrizzleFxRateRepository', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let repo: FxRateRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		repo = testBed.resolve(FxRateRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	function build(opts: { from?: CurrencyCode; to?: CurrencyCode; rate?: string; startDate?: string }): FxRate {
		return FxRate.create({
			fromCurrency: opts.from ?? CurrencyCode.USD,
			toCurrency: opts.to ?? CurrencyCode.BRL,
			rate: opts.rate ?? '5.10',
			startDate: new Date(opts.startDate ?? '2026-05-01T00:00:00.000Z'),
		})
	}

	describe('save + findById', () => {
		it('round-trips an FxRate verbatim (rate string precision preserved)', async () => {
			const entity = build({ rate: '5.250000', startDate: '2026-06-15T12:00:00.000Z' })
			await repo.save(entity)

			const fetched = await repo.findById(entity.id.value)
			expect(fetched?.fromCurrency).toBe(CurrencyCode.USD)
			expect(fetched?.toCurrency).toBe(CurrencyCode.BRL)
			// Trailing zeros preserved (iter 303 fix: column is text, not double).
			expect(fetched?.rate).toBe('5.250000')
		})

		it('returns undefined when no row matches', async () => {
			const r = await repo.findById(testId())
			expect(r).toBeUndefined()
		})
	})

	describe('findEffective', () => {
		it('returns undefined when no rate exists for the pair', async () => {
			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r).toBeUndefined()
		})

		it('returns the latest rate with startDate <= asOf', async () => {
			await repo.save(build({ rate: '5.10', startDate: '2026-05-01T00:00:00.000Z' }))
			await repo.save(build({ rate: '5.25', startDate: '2026-06-01T00:00:00.000Z' }))
			await repo.save(build({ rate: '5.30', startDate: '2026-07-01T00:00:00.000Z' }))

			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r?.rate).toBe('5.25')
		})

		it('filters by (fromCurrency, toCurrency) pair', async () => {
			await repo.save(build({ from: CurrencyCode.USD, to: CurrencyCode.BRL, rate: '5.25' }))
			await repo.save(build({ from: CurrencyCode.EUR, to: CurrencyCode.BRL, rate: '5.60' }))

			const usd = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			const eur = await repo.findEffective(CurrencyCode.EUR, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(usd?.rate).toBe('5.25')
			expect(eur?.rate).toBe('5.60')
		})

		it('returns undefined when no rate is on or before asOf', async () => {
			await repo.save(build({ rate: '5.25', startDate: '2026-12-01T00:00:00.000Z' }))

			const r = await repo.findEffective(CurrencyCode.USD, CurrencyCode.BRL, new Date('2026-06-15T00:00:00.000Z'))
			expect(r).toBeUndefined()
		})
	})

	describe('list', () => {
		it('paginates newest-first by startDate', async () => {
