import { injectable } from 'tsyringe-neo'
import { and, count, desc, eq, gte, lte, sql } from 'drizzle-orm'
import { DrizzleClient, tryCatchAsync } from '@bk-dash/core-typescript'
import { fxRates } from '@bk-dash/contracts/db'
import { type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { FxRate, FxRateSchema } from '../../entities/FxRate'
import { FxRateRepository, type FxRateListQuery, type FxRateListResult } from './FxRateRepository'

/**
 * Drizzle-backed FxRateRepository (iter 303 — closes one more row of
 * the iter-300 known-gap §1). Append-only by design: `save` issues an
 * INSERT keyed by id with `onConflictDoUpdate` for idempotent
 * re-ingest. The DB row has no `updatedAt` or `version` columns
 * (matches the entity's append-only semantics) — `incrementVersion`
 * still bumps in-memory state for the base class invariant but is not
 * persisted.
 *
 * `findEffective` runs the canonical "rate at time T" lookup:
 *   WHERE from_currency=? AND to_currency=? AND start_date<=?
 *   ORDER BY start_date DESC LIMIT 1
 * which the `pair_start_date_idx` covers as a single-page seek.
 *
 * `endDate` is always `null` on rehydration: rows are immutable once
 * written; the validity upper bound is the next row's `start_date` in
 * the series, derived at query time, never stored as a column.
 */
@injectable()
export class DrizzleFxRateRepository extends FxRateRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc.select().from(fxRates).where(eq(fxRates.id, id)).limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async findEffective(fromCurrency: CurrencyCode, toCurrency: CurrencyCode, asOf: Date, tx?: DrizzleClient): Promise<FxRate | undefined> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const rows = await dbc
				.select()
				.from(fxRates)
				.where(and(eq(fxRates.fromCurrency, fromCurrency), eq(fxRates.toCurrency, toCurrency), lte(fxRates.startDate, asOf)))
				.orderBy(desc(fxRates.startDate))
				.limit(1)
			return rows[0]
		})
		if (!result.success || !result.data) return undefined
		return this.toDomain(result.data)
	}

	async list(query: FxRateListQuery, tx?: DrizzleClient): Promise<FxRateListResult> {
		const dbc = tx ?? this.db
		const filters = [] as any[]
		if (query.fromCurrency !== undefined) filters.push(eq(fxRates.fromCurrency, query.fromCurrency))
		if (query.toCurrency !== undefined) filters.push(eq(fxRates.toCurrency, query.toCurrency))
		if (query.from !== undefined) filters.push(gte(fxRates.startDate, query.from))
		if (query.to !== undefined) filters.push(lte(fxRates.startDate, query.to))
		const whereClause = filters.length > 0 ? and(...filters) : sql`true`
		const result = await tryCatchAsync(async () => {
			const offset = Math.max(0, (query.page - 1) * query.limit)
			const [items, totalRows] = await Promise.all([
				dbc.select().from(fxRates).where(whereClause).orderBy(desc(fxRates.startDate)).limit(query.limit).offset(offset),
				dbc.select({ value: count() }).from(fxRates).where(whereClause),
			])
			return { items, total: Number(totalRows[0]?.value ?? 0) }
		})
		if (!result.success) throw result.error
		return {
			total: result.data.total,
			items: result.data.items.map(r => this.toDomain(r)),
		}
	}

	async save(entity: FxRate, tx?: DrizzleClient): Promise<FxRate> {
		entity.incrementVersion()
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			const data = this.toPersistence(entity)
			await dbc
				.insert(fxRates)
				.values(data)
				.onConflictDoUpdate({
					target: fxRates.id,
					set: {
						fromCurrency: data.fromCurrency,
						toCurrency: data.toCurrency,
						rate: data.rate,
						startDate: data.startDate,
					},
				})
			return entity
		})
		if (!result.success) throw result.error
		return result.data
	}

	async delete(id: string, tx?: DrizzleClient): Promise<void> {
		const dbc = tx ?? this.db
		const result = await tryCatchAsync(async () => {
			await dbc.delete(fxRates).where(eq(fxRates.id, id))
		})
		if (!result.success) throw result.error
	}

	private toDomain(row: typeof fxRates.$inferSelect): FxRate {
		const parsed = FxRateSchema.parse({
			fromCurrency: row.fromCurrency,
			toCurrency: row.toCurrency,
			rate: row.rate,
			startDate: row.startDate,
			// AC-3: endDate is always null at the data layer — the row-per-rate
			// append-only model has no end_date column. The validity upper bound
			// is the next row's start_date, derived at query time.
			endDate: null,
		})
		return new FxRate({
			...parsed,
			id: row.id,
			createdAt: row.createdAt,
		})
	}

	private toPersistence(entity: FxRate): typeof fxRates.$inferInsert {
		return {
			id: entity.id.value,
			fromCurrency: entity.fromCurrency,
			toCurrency: entity.toCurrency,
			rate: entity.rate,
			startDate: entity.startDate,
