import { injectable } from 'tsyringe-neo'
import { z } from '@bk-dash/core-typescript'
import { Country } from '@bk-dash/contracts-typescript/wire/enums'
import type { ParsedProductCostRow, ProductCostBuildInput, ProductCostCsvParseResult, ProductCostCsvProcessor } from '../types'

const KIT_KEY = ' kit'

@injectable()
export class ManualProductCostCsvProcessor implements ProductCostCsvProcessor {
	async process(rows: ParsedProductCostRow[]): Promise<ProductCostCsvParseResult> {
		const byProduct = new Map<string, ProductCostBuildInput>()
		const errors: { row: number; code: string; value?: string }[] = []

		for (const r of rows) {
			// Validate country: empty string → no country; non-empty must be a valid Country enum value.
			let country: Country | undefined
			if (r.country !== undefined && r.country.length > 0) {
				const parsed = z.enum(Country).safeParse(r.country)
				if (!parsed.success) {
					errors.push({ row: r.row, code: 'CSV_INVALID_COUNTRY', value: r.country })
					continue
				}
				country = parsed.data
			}

			const key = r.productId === null || r.productId === undefined ? KIT_KEY : r.productId
			const option = {
				currency: r.currency,
				country,
				startDate: r.startDate,
				endDate: r.endDate,
				items: [
					{
						variantIds: r.variantIds!,
						quantity: r.quantity,
						quantityModifier: r.quantityModifier,
						unitCost: r.unitCost,
					},
				],
			}
			const existing = byProduct.get(key)
			if (existing) {
				existing.options.push(option)
				existing.sourceRows.push(r.row)
			} else {
				byProduct.set(key, {
					productId: r.productId ?? null,
					costType: r.costType,
					options: [option],
					sourceRows: [r.row],
				})
			}
		}
		return { builds: [...byProduct.values()], errors }
	}
}

