import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { givenStoreIntegration } from '@test/support/given'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { CreateProductCost } from './CreateProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostCreatedEvent } from '../events'
import type { ProductCostOptionInput } from '../entities/ProductCost'

const STORE = testId('store', '1')
const PRODUCT_A = testId('product', 'a')
const PRODUCT_B = testId('product', 'b')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

function singleOption(overrides: Partial<ProductCostOptionInput> = {}): ProductCostOptionInput {
	return {
		currency: CurrencyCode.USD,
		startDate: '2026-05-01',
		items: [
			{
				variantIds: [VARIANT_1],
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				unitCost: { amountCents: 500, currency: CurrencyCode.USD },
			},
		],
		...overrides,
	}
}

describe('CreateProductCost (C27)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: CreateProductCost
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(CreateProductCost)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		// The store's StoreIntegration is derived by the use case from storeId,
		// so it must exist before any CreateProductCost call.
		await givenStoreIntegration(testBed, { storeId: STORE, ownerId: 'integration-tenant' })
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function readCreatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ProductCostCreatedEvent)
	}

	it('persists a new ProductCost + emits ProductCostCreatedEvent', async () => {
		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)

		const saved = await repo.findById(out.productCostId)
		expect(saved?.storeId.value).toBe(STORE)
		expect(saved?.productId?.value).toBe(PRODUCT_A)
		expect(saved?.costType).toBe(ProductCostType.SINGLE)
		expect(saved?.options).toHaveLength(1)
		// Entity stamps an id + variantsHash on each option's items
		const firstItem = saved?.options.at(0)?.items.at(0)
		expect(firstItem?.id.value).toMatch(/^[0-9a-f-]{36}$/)
		expect(firstItem?.variantsHash).toBe(VARIANT_1)

		const emitted = await readCreatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
		expect(emitted[0]!.payload.productCost.productId).toBe(PRODUCT_A)
		expect(emitted[0]!.payload.productCost.costType).toBe(ProductCostType.SINGLE)
	})

	it('throws PRODUCT_COST_ALREADY_EXISTS when a rule already exists for the same (storeId, productId)', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		await expect(
			useCase.execute({
				userId: USER,
				storeId: STORE,
				productId: PRODUCT_A,
				costType: ProductCostType.SINGLE,
				options: [singleOption()],
			}),
		).rejects.toMatchObject({ name: 'PRODUCT_COST_ALREADY_EXISTS' })
	})

	it('allows a second rule for a different product on the same store', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_B,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)
		const both = await readCreatedEvents()
		expect(both).toHaveLength(2)
	})

	it('allows kit-scoped rules (productId=null) alongside product-scoped rules', async () => {
		await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})

		// Kit-scoped (productId=null) is a distinct uniqueness slot per storeId.
		const out = await useCase.execute({
			userId: USER,
			storeId: STORE,
			productId: null,
			costType: ProductCostType.MULTIPLE,
			options: [singleOption()],
		})

		expect(out.productCostId).toMatch(/^[0-9a-f-]{36}$/)
		const saved = await repo.findById(out.productCostId)
		expect(saved?.productId).toBeNull()
		expect(saved?.costType).toBe(ProductCostType.MULTIPLE)
	})

	it('propagates INVALID_DATE_RANGE from the entity when startDate > endDate', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				storeId: STORE,
				productId: PRODUCT_A,
				costType: ProductCostType.SINGLE,
				options: [singleOption({ startDate: '2026-12-01', endDate: '2026-11-01' })],
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })

		// Confirm nothing persisted.
		const found = await repo.findByStoreAndProduct(STORE, PRODUCT_A)
		expect(found).toBeUndefined()
	})
})

import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'bun:test'
import { container, type DependencyContainer } from 'tsyringe-neo'
import { TestBed, testId } from '@test/support'
import { givenStoreIntegration } from '@test/support/given'
import { DomainEventRepository } from '@bk-dash/core-typescript'
import { CurrencyCode, ProductCostType, QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { UpdateProductCost } from './UpdateProductCost'
import { CreateProductCost } from './CreateProductCost'
import { ProductCostRepository } from '../repositories/ProductCostRepository'
import { ProductCostUpdatedEvent } from '../events'
import { ProductCost, type ProductCostOptionInput } from '../entities/ProductCost'

const STORE = testId('store', '1')
const PRODUCT_A = testId('product', 'a')
const VARIANT_1 = testId('variant', '1')
const USER = testId('user', '1')

function singleOption(overrides: Partial<ProductCostOptionInput> = {}): ProductCostOptionInput {
	return {
		currency: CurrencyCode.USD,
		startDate: '2026-05-01',
		items: [
			{
				variantIds: [VARIANT_1],
				quantity: 1,
				quantityModifier: QuantityModifier.EQ,
				unitCost: { amountCents: 500, currency: CurrencyCode.USD },
			},
		],
		...overrides,
	}
}

describe('UpdateProductCost (C28)', () => {
	let testBed: TestBed
	let testContainer: DependencyContainer
	let useCase: UpdateProductCost
	let createUseCase: CreateProductCost
	let repo: ProductCostRepository

	beforeAll(async () => {
		testContainer = container.createChildContainer()
		testBed = await TestBed.create('integration', { testContainer, ownerId: 'integration-tenant' })
		useCase = testBed.resolve(UpdateProductCost)
		createUseCase = testBed.resolve(CreateProductCost)
		repo = testBed.resolve(ProductCostRepository)
	})
	beforeEach(async () => {
		await testBed.reset()
		await givenStoreIntegration(testBed, { storeId: STORE, ownerId: 'integration-tenant' })
	})
	afterAll(async () => {
		await testBed.destroy()
	})

	async function seedProductCost(): Promise<string> {
		const { productCostId } = await createUseCase.execute({
			userId: USER,
			storeId: STORE,
			productId: PRODUCT_A,
			costType: ProductCostType.SINGLE,
			options: [singleOption()],
		})
		return productCostId
	}

	async function readUpdatedEvents() {
		return testBed.resolve(DomainEventRepository).findByType(ProductCostUpdatedEvent)
	}

	it('updates options + emits ProductCostUpdatedEvent', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({
			userId: USER,
			ids: [productCostId],
			options: [singleOption({ currency: CurrencyCode.EUR })],
		})

		const updated = await repo.findById(productCostId)
		expect(updated?.options[0]?.currency).toBe(CurrencyCode.EUR)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('updates options + reports changedFields=[options]; items get fresh ids + variantsHash', async () => {
		const productCostId = await seedProductCost()
		const before = await repo.findById(productCostId)
		const originalOptionId = before!.options[0]!.id

		const newOption = singleOption({
			currency: CurrencyCode.BRL,
			startDate: '2026-06-01',
			items: [
				{
					variantIds: [VARIANT_1],
					quantity: 10,
					quantityModifier: QuantityModifier.GTE,
					unitCost: { amountCents: 400, currency: CurrencyCode.BRL },
				},
			],
		})

		await useCase.execute({
			userId: USER,
			ids: [productCostId],
			options: [newOption],
		})

		const updated = await repo.findById(productCostId)
		const opt = updated?.options[0]
		expect(updated?.options).toHaveLength(1)
		expect(opt?.currency).toBe(CurrencyCode.BRL)
		expect(opt?.items[0]?.quantity).toBe(10)
		expect(opt?.id).not.toBe(originalOptionId) // fresh id
		expect(opt?.items[0]?.variantsHash).toBe(VARIANT_1)

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('updates options together with a currency change', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({
			userId: USER,
			ids: [productCostId],
			options: [singleOption({ currency: CurrencyCode.EUR })],
		})

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
	})

	it('emits ProductCostUpdatedEvent even when no fields supplied (always-publish)', async () => {
		const productCostId = await seedProductCost()

		await useCase.execute({ userId: USER, ids: [productCostId] })

		const emitted = await readUpdatedEvents()
		expect(emitted).toHaveLength(1)
		expect(emitted[0]!.payload.productCost).toBeDefined()
		expect(emitted[0]!.payload.productCost.storeId).toBe(STORE)
	})

	it('throws PRODUCT_COST_NOT_FOUND when the row is missing', async () => {
		await expect(
			useCase.execute({
				userId: USER,
				ids: [testId()],
				options: [singleOption()],
			}),
		).rejects.toMatchObject({ name: 'PRODUCT_COST_NOT_FOUND' })
	})

	it('throws PRODUCT_COST_NOT_FOUND when the row was soft-deleted', async () => {
		const productCostId = await seedProductCost()
		const entity = await repo.findById(productCostId)
		entity!.delete()
		await repo.save(entity as ProductCost)

		await expect(useCase.execute({ userId: USER, ids: [productCostId], options: [singleOption()] })).rejects.toMatchObject({
			name: 'PRODUCT_COST_NOT_FOUND',
		})
	})

	it('propagates INVALID_DATE_RANGE from entity.update when options carry bad dates', async () => {
		const productCostId = await seedProductCost()

		await expect(
			useCase.execute({
				userId: USER,
				ids: [productCostId],
				options: [singleOption({ startDate: '2026-12-01', endDate: '2026-11-01' })],
			}),
		).rejects.toMatchObject({ name: 'INVALID_DATE_RANGE' })
	})
})

import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier, CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'
import { Timeline } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

export const ProductCostOptionItemInputSchema = z.object({
	variantIds: z.array(z.uuid()).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: MonetaryAmountSchema,
})

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

function buildItems(items: ProductCostOptionInput['items']) {
	return items.map(item => ({
		id: crypto.randomUUID(),
		variantIds: item.variantIds,
		quantity: item.quantity,
		quantityModifier: item.quantityModifier,
		unitCost: item.unitCost,
		variantsHash: hashVariantIds(item.variantIds),
	}))
}

type PaintedOptionValue = { items: ReturnType<typeof buildItems>; startDate: Date; endDate: Date | null }
type PaintedOption = { id: string; currency: CurrencyCode; country?: Country; values: PaintedOptionValue[] }

/** Group input options by (currency, country); paint each value onto that key's Timeline. */
function groupAndPaint(inputs: ProductCostOptionInput[]): PaintedOption[] {
	const byKey = new Map<string, PaintedOption>()
	for (const opt of inputs) {
		const key = `${opt.currency}|${opt.country ?? ''}`
		const value: PaintedOptionValue = { items: buildItems(opt.items), startDate: new Date(opt.startDate), endDate: opt.endDate ? new Date(opt.endDate) : null }
		const entry = byKey.get(key)
		if (entry) entry.values = [...new Timeline(entry.values).place(value).entries]
		else byKey.set(key, { id: crypto.randomUUID(), currency: opt.currency, country: opt.country, values: [value] })
	}
	return [...byKey.values()]
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency and country — which in turn
 * hold a `values` Timeline of `{ items }` (the per-variant unit costs that
 * change over time).
 *
 * - Invariant: each option's `values` timeline is non-overlapping
 *   (Timeline-enforced); at most one option per (currency, country).
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Group by (currency, country) and paint each value onto the option's Timeline.
		// Then validate each painted option through ProductCostOptionSchema.
		const options = groupAndPaint(data.options)

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — the full options set. */
	update(data: { options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.options !== undefined) {
			const options = groupAndPaint(data.options)
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

import { BaseValueObject, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCostOptionItem } from './ProductCostOptionItem'

// Keys structural, only the value is historical: (currency, country) identify
// the option; the changing { items } is a leaf Timeline entry.
export const ProductCostOptionValueSchema = z.historical({
	items: z.array(z.instance(ProductCostOptionItem)).min(1),
})
export type ProductCostOptionValue = Z.infer<typeof ProductCostOptionValueSchema>

export const ProductCostOptionSchema = z.object({
	id: z.instance(Id),
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	/** A Timeline (array) of windowed { items } values for this (currency,country). */
	values: z.array(ProductCostOptionValueSchema).min(1),
})

export type ProductCostOptionProps = Z.infer<typeof ProductCostOptionSchema>

/**
 * A `(currency, country)`-keyed slice of a `ProductCost`. Identity is
 * structural; `values` is the time-effective series of `{ items }` (the
 * per-variant unit costs that change over time). Composite value object,
 * serialized inline in the `ProductCost` aggregate's jsonb column.
 */
export class ProductCostOption extends BaseValueObject<typeof ProductCostOptionSchema> {
	static override schema = ProductCostOptionSchema
}

export interface ProductCostOption extends ProductCostOptionProps {}

