import { z } from 'zod'
import { BaseError } from '../../types/BaseError'
import type { BaseInterfaceErrors } from '../../errors/codes'
import { instanceInputSchemaMap } from './InstanceRegistry'

/**
 * StringToNumber - Coerces a string to a number
 * Uses Zod's coerce which applies Number() to the input
 */
export const stringToNumber = (options?: { minimum?: number; maximum?: number }) => {
	let schema = z.coerce.number()
	if (options?.minimum !== undefined) schema = schema.min(options.minimum)
	if (options?.maximum !== undefined) schema = schema.max(options.maximum)
	return schema
}

/**
 * StringToInteger - Coerces a string to an integer
 * Uses Zod's coerce with .int() validation
 */
export const stringToInteger = (options?: { minimum?: number; maximum?: number }) => {
	let schema = z.coerce.number().int()
	if (options?.minimum !== undefined) schema = schema.min(options.minimum)
	if (options?.maximum !== undefined) schema = schema.max(options.maximum)
	return schema
}

/**
 * StringToBoolean - Coerces common string values to boolean
 * Uses Zod v4's stringbool() which handles 'true', '1', 'yes', 'on', etc.
 */
export const stringToBoolean = () => {
	return z.stringbool()
}

/**
 * StringToDate - Transforms an ISO date string to a Date object.
 * Validates input as ISO date (documented in OpenAPI as z.iso.date())
 * then pipes to z.date() for Date object output.
 */
export const stringToDate = () => {
	return z.union([z.iso.date(), z.iso.datetime()]).transform(v => new Date(v))
}

/**
 * StringToArray - Normalizes a query-string array filter into a typed array.
 *
 * Accepts the three shapes a query param can arrive in and validates each
 * element with `element` (defaults to `z.string()`):
 * - repeated params  `?id=a&id=b` → Fastify delivers `['a','b']`
 * - single param     `?id=a`      → delivers `'a'` → `['a']`
 * - comma-separated  `?id=a,b`    → `'a,b'` → `['a','b']`
 *
 * @example z.stringToArray(z.uuid()) // 'a' -> ['a'], ['a','b'] -> ['a','b']
 */
export const stringToArray = <T extends z.ZodTypeAny = z.ZodString>(element?: T, options?: { min?: number; max?: number }) => {
	const inner = (element ?? z.string()) as T
	let array = z.array(inner)
	if (options?.min !== undefined) array = array.min(options.min)
	if (options?.max !== undefined) array = array.max(options.max)
	return z
		.union([z.string(), z.array(z.string())])
		.transform(
			value =>
				(Array.isArray(value) ? value : [value])
					.flatMap(item => item.split(','))
					.map(item => item.trim())
					.filter(item => item.length > 0) as z.input<typeof array>,
		)
		.pipe(array)
}

/**
 * StringToNumberArray - Transforms a comma-separated string into an array of numbers
 */
export const stringToNumberArray = () => {
	return z
		.string()
		.transform(value => {
			if (!value || value.trim() === '') return []
			return value.split(',').map(item => {
				const num = Number(item.trim())
				if (Number.isNaN(num)) {
					throw new BaseError<BaseInterfaceErrors>('CANNOT_CONVERT_INPUT', `Cannot convert "${item}" to number`)
				}
				return num
			})
		})
		.pipe(z.array(z.number()))
}

function unwrapPipe(schema: z.ZodTypeAny): z.ZodTypeAny {
	// Check the instance registry FIRST: z.instance(Cls) produces a `pipe`
	// schema (z.unknown().transform(...)) that is registered here by the
	// `instance` helper. If we let the pipe branch run first, it would recurse
	// into z.unknown() and lose the VO schema. Checking early returns the real
	// wire-input schema without touching parse-time behaviour.
	const voSchema = instanceInputSchemaMap.get(schema)
	if (voSchema !== undefined) {
		return voSchema
	}
	if (schema._zod.def.type === 'pipe') {
		return unwrapPipe((schema._zod.def as any).in)
	}
	if (schema._zod.def.type === 'default') {
		return unwrapPipe((schema._zod.def as any).innerType).optional()
	}
	if (schema._zod.def.type === 'optional' || schema._zod.def.type === 'nullable') {
		return unwrapPipe((schema._zod.def as any).innerType).optional()
	}
	return schema
}

export function extractInputSchema<T extends z.ZodObject<any>>(schema: T): z.ZodType<z.input<T>> {
	const shape = schema._zod.def.shape
	const newShape = Object.fromEntries(Object.entries(shape).map(([key, value]) => [key, unwrapPipe(value as z.ZodTypeAny)]))
	return z.object(newShape) as any
}
// ZodTransforms - Transform functions that match Zod's camelCase naming convention
export const ZodTransforms = {
	stringToNumber,
	stringToInteger,
	stringToBoolean,
	stringToDate,
	stringToArray,
	stringToNumberArray,
}

import { z } from 'zod'
import type * as core from 'zod/v4/core'
import { extractInputSchema } from './Transforms'

// Augment Zod v4's ZodType interface to add .input() method
declare module 'zod' {
	// @ts-expect-error — variance on Shape is covariant in practice (we only read from it)
	interface ZodObject<out Shape extends core.$ZodShape, out Config extends core.$ZodObjectConfig> {
		/**
		 * Returns a schema with all pipe transforms stripped from fields,
		 * using the original schema's input type (preserving field types and optionality).
		 */
		input(): z.ZodType<core.input<this>, core.input<this>>
	}

	interface ZodType<out Output, out Input, out Internals extends core.$ZodTypeInternals<Output, Input>> {
		/**
		 * For non-object schemas, returns itself (no transforms to strip).
		 * For objects, the ZodObject overload takes precedence.
		 *
		 * NOTE: Only use .input() on ZodObject schemas (to strip field transforms).
		 * On primitive schemas (string, number, etc.) it's a no-op that degrades types.
		 */
		input(): z.ZodType<Input, Input>
	}
}
// Add the .input() method to Zod's prototype at runtime
// biome-ignore lint/suspicious/noExplicitAny: Required for prototype extension
;(z.ZodType.prototype as any).input = function () {
	if (this._zod.def.type === 'object') {
		return extractInputSchema(this)
	}
	return this
}

import { z, type ZodObject, type ZodRawShape, type ZodTypeAny, type ZodLiteral, ZodDiscriminatedUnion } from 'zod'
import { instanceInputSchemaMap } from './InstanceRegistry'
import { stringToInteger } from './Transforms'
import { BaseEventSchema } from '../../types/BaseEvent'
import { BaseDomainEventSchema } from '../../types/BaseDomainEvent'
import { BaseIntegrationEventSchema } from '../../types/BaseIntegrationEvent'

// Meta options with examples
interface SchemaOptions {
	examples?: unknown[]
}

type IntegrationEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: ZodObject<T> }
>

type IntegrationEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseIntegrationEventSchema)['shape'], 'payload' | 'name'> & { name: ZodLiteral<string>; payload: T }
>

type DomainEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

type DomainEventWithPayloadSchema<T extends ZodTypeAny> = ZodObject<
	Omit<(typeof BaseDomainEventSchema)['shape'], 'payload'> & { payload: T }
>

type BaseEventObjectSchema<T extends ZodRawShape> = ZodObject<
	Omit<(typeof BaseEventSchema)['shape'], 'payload'> & { payload: ZodObject<T> }
>

// Helper to get examples from schema meta
const getExamples = (schema: ZodTypeAny): unknown[] => {
	// Access meta from the schema definition - Zod v4 uses 'def' property
	const def = (schema as unknown as { def?: { meta?: SchemaOptions } }).def
	return def?.meta?.examples ?? []
}

// Helper function to merge examples from two schemas
const mergeExamples = (baseExamples: unknown[] = [], additionalExamples: unknown[] = []) => {
	if (baseExamples.length === 0) return additionalExamples
	if (additionalExamples.length === 0) return baseExamples

	const merged: unknown[] = []

	// Create all possible combinations
	for (const baseExample of baseExamples) {
		for (const additionalExample of additionalExamples) {
			merged.push({
				...(baseExample as object),
				...(additionalExample as object),
			})
		}
	}

	return merged
}

// PaginatedQuery schema
export const PaginatedQuery = z
	.object({
		page: stringToInteger({ minimum: 1 }).default(1),
		limit: stringToInteger({ minimum: 1, maximum: 100 }).default(10),
		search: z.string().optional(),
	})
	.meta({
		examples: [
			{
				limit: 10,
				page: 1,
				search: 'Kitten drinking coffee.',
			},
		],
	})

/**
 * Builds a paginated query schema with additional properties
 */
export function paginatedQuery(properties?: undefined, options?: SchemaOptions): typeof PaginatedQuery
export function paginatedQuery<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<(typeof PaginatedQuery)['shape'] & T>
export function paginatedQuery<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return PaginatedQuery

	const baseExamples = getExamples(PaginatedQuery)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	return z
		.object({
			...PaginatedQuery.shape,
			...properties,
		})
		.meta({ examples: mergedExamples })
}

// PaginatedData base schema
export const PaginatedData = z
	.object({
		items: z.array(z.unknown()),
		total: z.number(),
		totalPages: z.number(),
	})
	.meta({ examples: [] })

/**
 * Builds a paginated response schema with typed items
 */
export function paginatedResponse<T extends ZodRawShape>(
	properties: T,
	options?: SchemaOptions,
): ZodObject<{
	items: z.ZodArray<ZodObject<T>>
	total: z.ZodNumber
	totalPages: z.ZodNumber
}> {
	const baseExamples = getExamples(PaginatedData)
	const mergedExamples = mergeExamples(baseExamples, options?.examples)

	const itemSchema = z.object(properties)
	const itemsArraySchema = z.array(itemSchema)

	return z
		.object({
			items: itemsArraySchema,
			total: z.number(),
			totalPages: z.number(),
		})
		.meta({ examples: mergedExamples }) as any
}

/**
 * Builds a base event schema with custom payload properties
 */
export function baseEvent(properties?: undefined, options?: SchemaOptions): typeof BaseEventSchema
export function baseEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): BaseEventObjectSchema<T>
export function baseEvent<T extends ZodRawShape>(properties?: T, options?: SchemaOptions) {
	if (!properties) return BaseEventSchema.meta({ examples: options?.examples ?? [] })

	const payloadSchema = z.object(properties)
	const mergedExamples = options?.examples ?? []

	const { payload: _payload, ...baseShape } = BaseEventSchema.shape

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}

/**
 * Builds a domain event schema with custom payload properties
 */
export function domainEvent(properties?: undefined, options?: SchemaOptions): typeof BaseDomainEventSchema
export function domainEvent<T extends ZodTypeAny>(schema: T, options?: SchemaOptions): DomainEventWithPayloadSchema<T>
export function domainEvent<T extends ZodRawShape>(properties: T, options?: SchemaOptions): DomainEventObjectSchema<T>
export function domainEvent(properties?: ZodRawShape | ZodTypeAny, options?: SchemaOptions) {
	if (!properties) return BaseDomainEventSchema.meta({ examples: options?.examples ?? [] })

	const mergedExamples = options?.examples ?? []
	const { payload: _payload, ...baseShape } = BaseDomainEventSchema.shape

	const payloadSchema = '_zod' in properties ? properties : z.object(properties as ZodRawShape)

	return z
		.object({
			...baseShape,
			payload: payloadSchema,
		})
		.meta({ examples: mergedExamples })
}
/**
 * Builds an integration event schema with a baked-in z.literal name for discriminatedUnion support.
 */
export function integrationEvent(
	name: string,
	options?: SchemaOptions,
): ZodObject<{
	name: ZodLiteral<string>
	payload: (typeof BaseIntegrationEventSchema)['shape']['payload']
	ownerId: (typeof BaseIntegrationEventSchema)['shape']['ownerId']
}>
export function integrationEvent<T extends ZodTypeAny>(
	name: string,
	schema: T,
	options?: SchemaOptions,
): IntegrationEventWithPayloadSchema<T>
export function integrationEvent<T extends ZodRawShape>(
	name: string,
	properties: T,
	options?: SchemaOptions,
): IntegrationEventObjectSchema<T>
export function integrationEvent(name: string, properties?: ZodRawShape | ZodTypeAny | SchemaOptions, options?: SchemaOptions) {
	// Allow (name) / (name, options) / (name, schema) / (name, schema, options) / (name, properties, options).
	let resolvedProperties: ZodRawShape | ZodTypeAny | undefined
	let resolvedOptions: SchemaOptions | undefined

	if (properties && typeof properties === 'object' && !('_zod' in properties) && !Array.isArray(properties)) {
		// Either ZodRawShape or SchemaOptions (which has only `examples`).
		const keys = Object.keys(properties)
		const looksLikeOptions = keys.length === 1 && keys[0] === 'examples'
		if (looksLikeOptions) {
			resolvedOptions = properties as SchemaOptions
		} else {
			resolvedProperties = properties as ZodRawShape
			resolvedOptions = options
		}
	} else if (properties && '_zod' in (properties as object)) {
		resolvedProperties = properties as ZodTypeAny
		resolvedOptions = options
	} else {
		resolvedOptions = options
	}

	const mergedExamples = resolvedOptions?.examples ?? []
	const { name: _name, payload: _payload, ...baseShape } = BaseIntegrationEventSchema.shape

	if (resolvedProperties === undefined) {
		return z
			.object({ ...baseShape, name: z.literal(name), payload: BaseIntegrationEventSchema.shape.payload })
			.meta({ examples: mergedExamples })
	}

	const payloadSchema =
		'_zod' in (resolvedProperties as object) ? (resolvedProperties as ZodTypeAny) : z.object(resolvedProperties as ZodRawShape)

	return z.object({ ...baseShape, name: z.literal(name), payload: payloadSchema }).meta({ examples: mergedExamples })
}

// Time-effective window appended to any schema by `z.historical`. `endDate`
// null = open-ended / currently active. `z.coerce.date()` lets jsonb-stored
// ISO strings rehydrate to Date on read without manual parsing.
const TimeWindowShape = {
	startDate: z.coerce.date(),
	endDate: z.coerce.date().nullable().default(null),
}

// Cast to the broader refine callback type Zod v4 expects internally.
const windowIsValid = (w: unknown) => {
	const win = w as { startDate: Date; endDate: Date | null }
	return win.endDate === null || win.startDate < win.endDate
}
const INVALID_RANGE = { error: 'INVALID_DATE_RANGE' } as const

/**
 * Extends a schema with a validated `[startDate, endDate)` window.
 * Accepts a raw shape, a ZodObject, or a discriminated union (window
 * applied per-variant so the discriminator stays narrowable).
 *
 * `endDate` is nullable with a default of `null` (open-ended / currently active).
 * `z.coerce.date()` lets jsonb-stored ISO strings rehydrate to Date on read.
 * A `startDate < endDate` refine emits `INVALID_DATE_RANGE` on violation.
 */
export function historical<T extends ZodRawShape>(shape: T): ZodObject<T & typeof TimeWindowShape>
export function historical<T extends ZodTypeAny>(schema: T): z.ZodType<z.output<T> & { startDate: Date; endDate: Date | null }>
export function historical(input: ZodRawShape | ZodTypeAny): ZodTypeAny {
	if (!('_zod' in (input as object))) {
		// Raw shape — wrap in ZodObject then extend + refine
		return (z.object(input as ZodRawShape) as ZodObject<ZodRawShape>)
			.extend(TimeWindowShape)
			.refine(windowIsValid, INVALID_RANGE) as unknown as ZodTypeAny
	}
	const schema = input as ZodTypeAny
	// Discriminated union — extend each variant so the discriminator stays narrowable.
	// Zod v4: def.type is 'union' for discriminated unions; use instanceof instead.
	if (schema instanceof ZodDiscriminatedUnion) {
		// Access def via unknown cast — Zod v4 generics are complex; we only need
		// the discriminator string and the options array of ZodObjects at runtime.
		const du = schema as unknown as { def: { discriminator: string; options: ZodObject<ZodRawShape>[] } }
		const widened = du.def.options.map(o => o.extend(TimeWindowShape))
		return (z.discriminatedUnion(du.def.discriminator, widened as never) as ZodTypeAny).refine(windowIsValid, INVALID_RANGE)
	}
	// Plain ZodObject or any other schema — extend + refine
	return (schema as ZodObject<ZodRawShape>).extend(TimeWindowShape).refine(windowIsValid, INVALID_RANGE)
}

/**
 * Creates a schema that parses input and transforms it into a class instance.
 * The class must have a static `schema` property (BaseValueObject, BasePrimitiveValueObject, or BaseEntity).
 *
 * @example
 * ```ts
 * crm: z.instance(CRM),
 * userId: z.instance(Id),
 * specialties: z.array(z.instance(DoctorSpecialty)).default([]),
 * ```
 */
function instance<S extends ZodTypeAny, T>(Cls: { schema: S; new (props: any): T }): z.ZodType<T, T | z.input<S>> {
	// Accept already-constructed instances (idempotent for re-validation via
	// this.validate()) OR raw input (the constructor validates via static
	// schema). The declared input type mirrors both runtime branches so
	// call sites can pass either an instance or a props object without casts.
	const schema = z.unknown().transform((v: any) => (v instanceof Cls ? v : new Cls(v))) as z.ZodType<T, T | z.input<S>>
	// Register the underlying VO schema so that .input() can recover it instead
	// of returning z.unknown(). This does NOT change parse-time behaviour.
	instanceInputSchemaMap.set(schema as z.ZodTypeAny, Cls.schema as z.ZodTypeAny)
	return schema
}

// Export all extra schema types with camelCase naming to match Zod convention
export const ExtraSchemaTypes = {
	paginatedQuery,
	paginatedResponse,
	baseEvent,
	domainEvent,
	integrationEvent,
	instance,
	historical,
}

import Z from 'zod'
import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import { ProductCostType, QuantityModifier, CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmountSchema } from '../../shared/objects'
import { Timeline } from '../../shared/objects'
import { ProductCostOption, ProductCostOptionSchema } from '../objects/ProductCostOption'
import { ProductCostOptionItem, ProductCostOptionItemSchema } from '../objects/ProductCostOptionItem'
import type { CatalogApplicationErrors } from '../errors'

// `ProductCostOption` / `ProductCostOptionItem` are aggregate-internal value
// objects (live in `../objects`). Re-exported so existing importers keep their
// `../entities/ProductCost` path.
export { ProductCostOption, ProductCostOptionSchema, ProductCostOptionItem, ProductCostOptionItemSchema }

export const ProductCostSchema = z.object({
	storeId: z.instance(Id),
	storeIntegrationId: z.instance(Id),
	/** Null when scoped to a kit (multi-variant bundle priced together). */
	productId: z.instance(Id).nullable(),
	costType: z.enum(ProductCostType),
	options: z.array(z.instance(ProductCostOption)),
	deletedAt: z.date().nullable(),
})

export type ProductCostProps = Z.infer<typeof ProductCostSchema>

// ─── Input schemas (no computed fields, used by use cases / controllers) ──────

export const ProductCostOptionItemInputSchema = z.object({
	variantIds: z.array(z.uuid()).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: MonetaryAmountSchema,
})

export const ProductCostOptionInputSchema = z.object({
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	startDate: z.iso.date(),
	endDate: z.iso.date().optional(),
	items: z.array(ProductCostOptionItemInputSchema).min(1),
})

export type ProductCostOptionInput = Z.infer<typeof ProductCostOptionInputSchema>

/**
 * Deterministic hash of a sorted variant-ID set.
 * In production this should use crypto.createHash; for the Mock layer a
 * stable string sort + join is sufficient and produces consistent overlap
 * detection without the crypto dep at this module's load time.
 */
function hashVariantIds(variantIds: string[]): string {
	return [...variantIds].sort().join('|')
}

function buildItems(items: ProductCostOptionInput['items']) {
	return items.map(item => ({
		id: crypto.randomUUID(),
		variantIds: item.variantIds,
		quantity: item.quantity,
		quantityModifier: item.quantityModifier,
		unitCost: item.unitCost,
		variantsHash: hashVariantIds(item.variantIds),
	}))
}

interface PaintedOptionValue {
	items: ReturnType<typeof buildItems>
	startDate: Date
	endDate: Date | null
}
interface PaintedOption {
	id: string
	currency: CurrencyCode
	country?: Country
	values: PaintedOptionValue[]
}

/** Group input options by (currency, country); paint each value onto that key's Timeline. */
function groupAndPaint(inputs: ProductCostOptionInput[]): PaintedOption[] {
	const byKey = new Map<string, PaintedOption>()
	for (const opt of inputs) {
		const key = `${opt.currency}|${opt.country ?? ''}`
		const value: PaintedOptionValue = {
			items: buildItems(opt.items),
			startDate: new Date(opt.startDate),
			endDate: opt.endDate ? new Date(opt.endDate) : null,
		}
		const entry = byKey.get(key)
		if (entry) entry.values = [...new Timeline(entry.values).place(value).entries]
		else byKey.set(key, { id: crypto.randomUUID(), currency: opt.currency, country: opt.country, values: [value] })
	}
	return [...byKey.values()]
}

/**
 * `ProductCost` aggregate per spec § 4 BC5.
 *
 * One `ProductCost` represents a merchant's cost configuration for a
 * (storeIntegration × product?) scope. It holds one or more
 * `ProductCostOption`s — each scoped by currency and country — which in turn
 * hold a `values` Timeline of `{ items }` (the per-variant unit costs that
 * change over time).
 *
 * - Invariant: each option's `values` timeline is non-overlapping
 *   (Timeline-enforced); at most one option per (currency, country).
 * - Soft-delete: `deletedAt` is set by `delete()`; the row is preserved for
 *   historical COGS attribution.
 * - Scoping keys (storeIntegrationId, productId) are immutable after creation.
 */
export class ProductCost extends AggregateRoot<typeof ProductCostSchema> {
	static override schema = ProductCostSchema

	static create(data: {
		storeId: string
		storeIntegrationId: string
		productId: string | null
		costType: ProductCostType
		options: ProductCostOptionInput[]
	}): ProductCost {
		// Group by (currency, country) and paint each value onto the option's Timeline.
		// Then validate each painted option through ProductCostOptionSchema.
		const options = groupAndPaint(data.options)

		for (const opt of options) {
			const r = ProductCostOptionSchema.safeParse(opt)
			if (!r.success) throw new BaseError(r.error.issues[0]!.message)
		}

		return new ProductCost({
			id: crypto.randomUUID(),
			storeId: data.storeId,
			storeIntegrationId: data.storeIntegrationId,
			productId: data.productId,
			costType: data.costType,
			options,
			deletedAt: null,
		})
	}

	/** Updates mutable fields — the full options set. */
	update(data: { options?: ProductCostOptionInput[] }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		if (data.options !== undefined) {
			const options = groupAndPaint(data.options)
			for (const opt of options) {
				const r = ProductCostOptionSchema.safeParse(opt)
				if (!r.success) throw new BaseError(r.error.issues[0]!.message)
			}
			// Materialize the plain options into ProductCostOption value objects
			// through the aggregate's own field schema — no `new` in the body.
			this.options = ProductCostSchema.shape.options.parse(options)
		}
		this.validate()
	}

	/** Soft-delete. Preserved for historical COGS attribution. */
	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<CatalogApplicationErrors>('PRODUCT_COST_NOT_FOUND')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface ProductCost extends ProductCostProps {}

import { AggregateRoot, Id, z } from '@bk-dash/core-typescript'
import type Z from 'zod'
import { type PaymentGateway, type PaymentMethod, type CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'
import { Timeline } from '../../shared/objects'
import { GatewayFeeRateSchema, GatewayFeeSchema, CheckoutFeeSchema, ShippingFeeSchema } from '../objects'

type GatewayFeeEntry = Z.infer<typeof GatewayFeeSchema>
type GatewayFeeRate = Z.infer<typeof GatewayFeeRateSchema>
type CheckoutFeeEntry = Z.infer<typeof CheckoutFeeSchema>
type ShippingFeeEntry = Z.infer<typeof ShippingFeeSchema>

/** Flat input accepted by placeGatewayFee — the entity unpacks it into the nested structure. */
export interface GatewayFeeInput {
	platform: PaymentGateway
	paymentMethod: PaymentMethod
	variable: number
	fixed: { amountCents: number; currency: CurrencyCode }
	startDate: Date
	endDate: Date | null
}

export const FeesSchema = z.object({
	storeId: z.instance(Id),
	gatewayFees: z.array(GatewayFeeSchema).default([]),
	checkoutFee: z.array(CheckoutFeeSchema).default([]),
	shippingFee: z.array(ShippingFeeSchema).default([]),
})

export type FeesProps = Z.infer<typeof FeesSchema>

/**
 * One row per Store. Each fee block is a time-effective series.
 *
 * `gatewayFees` is indexed by platform. Each entry holds a `methods` record
 * mapping each PaymentMethod to its leaf `GatewayFeeRate[]` timeline. The
 * `placeGatewayFee` method accepts a flat input (platform + paymentMethod +
 * variable + fixed + window) and routes the rate into the correct per-method
 * Timeline inside the right platform entry.
 *
 * Checkout and shipping are single Timelines (whole-value historical).
 *
 * NOTE: the place* methods intentionally depart from the push-style
 * collection-mutation convention. A Timeline is a last-write-wins interval
 * series, so mutation trims/splits/removes entries via Timeline.place rather
 * than appending an item and returning it (spec Decision 3).
 */
export class Fees extends AggregateRoot<typeof FeesSchema> {
	static override schema = FeesSchema

	static create(data: { storeId: string }): Fees {
		return new Fees({ storeId: data.storeId, gatewayFees: [], checkoutFee: [], shippingFee: [] })
	}

	/**
	 * Places a flat gateway fee rate into the correct per-platform, per-method
	 * leaf Timeline. Isolates per (platform × paymentMethod) — placing a new
	 * STRIPE/CREDIT_CARD rate never touches PAYPAL/PIX.
	 */
	placeGatewayFee(fee: GatewayFeeInput): void {
		const rate: GatewayFeeRate = {
			variable: fee.variable,
			fixed: fee.fixed,
			startDate: fee.startDate,
			endDate: fee.endDate,
		}

		// Find or create the GatewayFee entry for this platform.
		const existing = this.gatewayFees.find(f => f.platform === fee.platform)
		const others = this.gatewayFees.filter(f => f.platform !== fee.platform)

		const currentMethods = existing?.methods ?? {}
		const currentRates: GatewayFeeRate[] = (currentMethods[fee.paymentMethod] as GatewayFeeRate[] | undefined) ?? []
		const updatedRates = new Timeline<GatewayFeeRate>(currentRates).place(rate).entries as GatewayFeeRate[]

		const updatedEntry: GatewayFeeEntry = {
			platform: fee.platform,
			methods: { ...currentMethods, [fee.paymentMethod]: updatedRates },
		}

		this.gatewayFees = [...others, updatedEntry]
		this.validate()
	}

	placeCheckoutFee(fee: CheckoutFeeEntry): void {
		this.checkoutFee = [...new Timeline<CheckoutFeeEntry>(this.checkoutFee).place(fee).entries]
		this.validate()
	}

	placeShippingFee(fee: ShippingFeeEntry): void {
		this.shippingFee = [...new Timeline<ShippingFeeEntry>(this.shippingFee).place(fee).entries]
		this.validate()
	}
}

export interface Fees extends FeesProps {}

import { BaseValueObject, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { QuantityModifier } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'

export const ProductCostOptionItemSchema = z.object({
	id: z.instance(Id),
	variantIds: z.array(z.instance(Id)).min(1),
	quantity: z.number().int().positive(),
	quantityModifier: z.enum(QuantityModifier),
	unitCost: z.instance(MonetaryAmount),
	/** SHA-1 of sorted variantIds — used for overlap detection. Computed by the aggregate, not supplied by the caller. */
	variantsHash: z.string(),
})

export type ProductCostOptionItemProps = Z.infer<typeof ProductCostOptionItemSchema>

/**
 * One per-variant × qty-tier cost line inside a {@link ProductCostOption}.
 * A composite value object: no independent lifecycle — it is materialized
 * and serialized inline within the `ProductCost` aggregate's JSON column.
 */
export class ProductCostOptionItem extends BaseValueObject<typeof ProductCostOptionItemSchema> {
	static override schema = ProductCostOptionItemSchema
}

export interface ProductCostOptionItem extends ProductCostOptionItemProps {}

import { BaseValueObject, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { CurrencyCode, Country } from '@bk-dash/contracts-typescript/wire/enums'
import { ProductCostOptionItem } from './ProductCostOptionItem'

// Keys structural, only the value is historical: (currency, country) identify
// the option; the changing { items } is a leaf Timeline entry.
export const ProductCostOptionValueSchema = z.historical({
	items: z.array(z.instance(ProductCostOptionItem)).min(1),
})
export type ProductCostOptionValue = Z.infer<typeof ProductCostOptionValueSchema>

export const ProductCostOptionSchema = z.object({
	id: z.instance(Id),
	currency: z.enum(CurrencyCode),
	country: z.enum(Country).optional(),
	/** A Timeline (array) of windowed { items } values for this (currency,country). */
	values: z.array(ProductCostOptionValueSchema).min(1),
})

export type ProductCostOptionProps = Z.infer<typeof ProductCostOptionSchema>

/**
 * A `(currency, country)`-keyed slice of a `ProductCost`. Identity is
 * structural; `values` is the time-effective series of `{ items }` (the
 * per-variant unit costs that change over time). Composite value object,
 * serialized inline in the `ProductCost` aggregate's jsonb column.
 */
export class ProductCostOption extends BaseValueObject<typeof ProductCostOptionSchema> {
	static override schema = ProductCostOptionSchema
}

export interface ProductCostOption extends ProductCostOptionProps {}

