import Z from 'zod'
import type { DomainErrors } from '../errors'

const isValidIanaTimezone = (tz: string): boolean =>
	tryCatch(() => new Intl.DateTimeFormat('en-US', { timeZone: tz }).format(new Date())).success

// BCP-47: language subtag (2-3 ASCII letters) optionally followed by a script subtag
// (4 letters), region subtag (2 letters or 3 digits), and/or variant. Covers the
// common forms ('en', 'pt-BR', 'zh-Hans-CN'); rejects free-form strings.
const BCP47_RE = /^[A-Za-z]{2,3}(-[A-Za-z]{4})?(-([A-Za-z]{2}|[0-9]{3}))?(-[A-Za-z0-9]{5,8})?$/

const isValidBcp47 = (lang: string): boolean => {
	if (!BCP47_RE.test(lang)) return false
	return tryCatch(() => new Intl.Locale(lang)).success
}

export const UserProfileSchema = z.object({
	userId: z.instance(Id),
	timezone: z
		.string()
		.refine(isValidIanaTimezone, { error: 'INVALID_TIMEZONE' as DomainErrors })
		.optional(),
	language: z
		.string()
		.refine(isValidBcp47, { error: 'INVALID_LANGUAGE' as DomainErrors })
		.optional(),
	brazilianTaxId: z.string().optional(),
	leadToken: z.string().optional(),
	disabledAt: z.date().optional(),
})

export type UserProfileProps = Z.infer<typeof UserProfileSchema>

export class UserProfile extends AggregateRoot<typeof UserProfileSchema> {
	static override schema = UserProfileSchema

	static create(data: { userId: string; timezone?: string; language?: string; brazilianTaxId?: string; leadToken?: string }): UserProfile {
		// `id` is the FK to authentication.users.id — must equal userId.
		// Domain-event entityId reads from `entity.id.value`, so binding the
		// two keeps audit logs + event payloads consistent with the database row.
		return new UserProfile({
			id: data.userId,
			userId: data.userId,
			timezone: data.timezone,
			language: data.language,
			brazilianTaxId: data.brazilianTaxId,
			leadToken: data.leadToken,
			disabledAt: undefined,
		})
	}

	updateProfile(data: { timezone?: string; language?: string; brazilianTaxId?: string | null }): void {
		if (data.timezone !== undefined) this.timezone = data.timezone
		if (data.language !== undefined) this.language = data.language
		if (data.brazilianTaxId !== undefined) this.brazilianTaxId = data.brazilianTaxId ?? undefined
		this.validate()
	}

	clearLeadToken(): void {
		this.leadToken = undefined
		this.validate()
	}

	disable(): void {
		this.disabledAt = new Date()
		this.validate()
	}

	enable(): void {
		this.disabledAt = undefined
		this.validate()
	}
}

export interface UserProfile extends UserProfileProps {}
