import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import type { FinanceDomainErrors } from '../errors'

export const WarrantyReserveSchema = z.object({
	storeId: z.instance(Id),
	/** Reserve rate as 0..1 fraction (controller exposes 0..100 %). */
	rate: z.number().min(0).max(1),
	effectiveFrom: z.date(),
	effectiveTo: z.date().nullable(),
	deletedAt: z.date().nullable(),
})

export type WarrantyReserveProps = Z.infer<typeof WarrantyReserveSchema>

/**
 * `WarrantyReserve` aggregate per spec § BC8 Finance. Time-effective
 * percentage of revenue reserved for warranty obligations. Same
 * supersession shape as Taxes / FeesConfiguration.
 */
export class WarrantyReserve extends AggregateRoot<typeof WarrantyReserveSchema> {
	static override schema = WarrantyReserveSchema

	static create(data: { storeId: string; rate: number; effectiveFrom: Date }): WarrantyReserve {
		return new WarrantyReserve({
			storeId: data.storeId,
			rate: data.rate,
			effectiveFrom: data.effectiveFrom,
			effectiveTo: null,
			deletedAt: null,
		})
	}

	update(patch: { rate?: number }): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'cannot update a deleted WarrantyReserve')
		}
		if (patch.rate !== undefined) {
			this.rate = patch.rate
		}
		this.validate()
	}

	supersede(at: Date): void {
		if (this.effectiveTo !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'WarrantyReserve row already superseded')
		}
		if (at <= this.effectiveFrom) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'supersession instant must be after effectiveFrom')
		}
		this.effectiveTo = at
		this.validate()
	}

	delete(): void {
		if (this.deletedAt !== null) {
			throw new BaseError<FinanceDomainErrors>('INVALID_DATE_RANGE', 'WarrantyReserve already deleted')
		}
		this.deletedAt = new Date()
		this.validate()
	}

	get isActive(): boolean {
		return this.effectiveTo === null && this.deletedAt === null
	}

	get isDeleted(): boolean {
		return this.deletedAt !== null
	}
}

export interface WarrantyReserve extends WarrantyReserveProps {}
