import { injectable } from 'tsyringe-neo'
import { BaseError, Handler, z, type Transaction } from '@bk-dash/core-typescript'
import Z from 'zod'
import { MonetaryAmountSchema } from '../../shared/objects'
import { GoalRepository } from '../repositories/GoalRepository'
import { GoalSchema } from '../entities/Goal'
import { GoalUpdatedEvent } from '../events'
import type { AnalyticsApplicationErrors } from '../errors'

export const UpdateGoalInputSchema = z.object({
	userId: z.uuid(),
	ids: z.array(z.uuid()).min(1),
	targetAmount: MonetaryAmountSchema.input()
		.refine(m => m.amountCents > 0)
		.optional(),
	from: z.date().optional(),
	to: z.date().optional(),
})

export const UpdateGoalOutputSchema = z.void()

/** C51 UpdateGoal. Mutable: targetAmount + from/to date range. Bulk by ids. */
@injectable()
export class UpdateGoal extends Handler<typeof UpdateGoalInputSchema, typeof UpdateGoalOutputSchema> {
	readonly name = 'update_goal' as const
	readonly inputSchema = UpdateGoalInputSchema
	readonly outputSchema = UpdateGoalOutputSchema

	constructor(private readonly goals: GoalRepository) {
		super()
	}

	protected async handle(input: this['input'], tx?: Transaction): Promise<this['output']> {
		await this.withTransaction(tx, async tx => {
			for (const goalId of input.ids) {
				const entity = await this.goals.findById(goalId, tx)
				if (!entity) {
					throw new BaseError<AnalyticsApplicationErrors>('GOAL_NOT_FOUND')
				}
				entity.updateTarget({
					targetAmount: input.targetAmount,
					from: input.from,
					to: input.to,
				})

				await this.goals.save(entity, tx)
				await this.domainEventRepository.save(
					new GoalUpdatedEvent({
						entityId: entity.id.value,
						ownerId: entity.storeId.value,
						// toJSON() serialises Id instances to strings; z.instance(Id) accepts
						// both at runtime — the cast bridges the TS mismatch.
						payload: { goal: entity.toJSON() as unknown as Z.infer<typeof GoalSchema> },
					}),
					tx,
				)
			}
		})

		return
	}
}

import { AggregateRoot, BaseError, Id, z } from '@bk-dash/core-typescript'
import Z from 'zod'
import { type CurrencyCode, GoalType } from '@bk-dash/contracts-typescript/wire/enums'
import { MonetaryAmount } from '../../shared/objects'
import type { AnalyticsDomainErrors } from '../errors'

export const GoalSchema = z.object({
	storeId: z.instance(Id),
	type: z.enum(GoalType),
	targetAmount: z.instance(MonetaryAmount).refine(m => m.amountCents > 0, {
		error: 'INVALID_AMOUNT' as AnalyticsDomainErrors,
	}),
	from: z.date(),
	to: z.date(),
})

export type GoalProps = Z.infer<typeof GoalSchema>

/**
 * `Goal` aggregate per spec § BC11 Analytics. Per-user, per-Store
 * revenue or profit target over a date window. Immutable scoping keys
 * after creation; only the target amount is mutable.
 */
export class Goal extends AggregateRoot<typeof GoalSchema> {
	static override schema = GoalSchema

	static create(data: {
		storeId: string
		type: GoalType
		targetAmount: { amountCents: number; currency: CurrencyCode }
		from: Date
		to: Date
	}): Goal {
		if (data.from > data.to) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		return new Goal(data)
	}

	updateTarget(patch: { targetAmount?: { amountCents: number; currency: CurrencyCode }; from?: Date; to?: Date }): void {
		const effFrom = patch.from ?? this.from
		const effTo = patch.to ?? this.to
		if (effFrom > effTo) {
			throw new BaseError<AnalyticsDomainErrors>('INVALID_DATE_RANGE', 'from must be <= to')
		}
		if (patch.targetAmount !== undefined) {
			this.targetAmount = new MonetaryAmount(patch.targetAmount)
		}
		if (patch.from !== undefined) {
			this.from = patch.from
		}
		if (patch.to !== undefined) {
			this.to = patch.to
		}
		this.validate()
	}
}

export interface Goal extends GoalProps {}

