\t// Check the instance registry FIRST: z.instance(Cls) produces a `pipe`
\t// schema (z.unknown().transform(...)) that is registered here by the
\t// `instance` helper. If we let the pipe branch run first, it would recurse
\t// into z.unknown() and lose the VO schema. Checking early returns the real
\t// wire-input schema without touching parse-time behaviour.
\tconst voSchema = instanceInputSchemaMap.get(schema)
\tif (voSchema !== undefined) {
\t\treturn voSchema
\t}
\tif (schema._zod.def.type === \'pipe\') {
\t\treturn unwrapPipe((schema._zod.def as any).in)
\t}
\tif (schema._zod.def.type === \'default\') {
\t\treturn unwrapPipe((schema._zod.def as any).innerType).optional()
\t}
\tif (schema._zod.def.type === \'optional\' || schema._zod.def.type === \'nullable\') {
\t\treturn unwrapPipe((schema._zod.def as any).innerType).optional()
\t}
\treturn schema
}

export function extractInputSchema<T extends z.ZodObject<any>>(schema: T): z.ZodType<z.input<T>> {
\tconst shape = schema._zod.def.shape
\tconst newShape = Object.fromEntries(Object.entries(shape).map(([key, value]) => [key, unwrapPipe(value as z.ZodTypeAny)]))
\treturn z.object(newShape) as any
}'''

new = '''/**
 * Dispatches a resolved (non-instance, non-wrapper) schema to deeper recursion
 * if it is a ZodObject or ZodArray — otherwise returns it as-is.
 *
 * Called AFTER instance-registry and wrapper (pipe/default/optional/nullable)
 * unwrapping so the input here is always the "real" schema, never a
 * transform or wrapper shell.
 */
function deepen(schema: z.ZodTypeAny): z.ZodTypeAny {
\tif (schema._zod.def.type === \'object\') {
\t\treturn extractInputSchema(schema as z.ZodObject<any>)
\t}
\tif (schema._zod.def.type === \'array\') {
\t\treturn unwrapArray(schema)
\t}
\treturn schema
}

/**
 * Rebuilds a ZodArray with its element unwrapped, preserving any min/max/length
 * constraints stored in `def.checks`. Zod v4 array checks are stored as check
 * objects in `schema._zod.def.checks`; each check has a `_zod.def` of shape
 * `{ check: \'min_length\', minimum: N }`, `{ check: \'max_length\', maximum: N }`,
 * or `{ check: \'length_equals\', length: N }`.
 */
function unwrapArray(schema: z.ZodTypeAny): z.ZodTypeAny {
\tconst def = schema._zod.def as any
