import { BaseValueObject } from '@bk-dash/core-typescript'
import { z } from '@bk-dash/core-typescript'

import Z from 'zod'
import { CurrencyCode } from '@bk-dash/contracts-typescript/wire/enums'

export const MonetaryAmountSchema = z.object({
	amountCents: z.number().int().nonnegative(),
	currency: z.enum(CurrencyCode),
})

/**
 * Signed variant for computed reporting figures (gross margin, profit, …) that
 * can legitimately be negative. NOT a stored MonetaryAmount value object — it's
 * the read-side shape for analytics outputs, so it drops the `.nonnegative()`.
 */
export const SignedMonetaryAmountSchema = z.object({
	amountCents: z.number().int(),
	currency: z.enum(CurrencyCode),
})

export class MonetaryAmount extends BaseValueObject<typeof MonetaryAmountSchema> {
	static override schema = MonetaryAmountSchema

	equals(other: MonetaryAmount): boolean {
