	F extends z.ZodArray<infer E extends z.ZodTypeAny> ? z.ZodArray<InputField<E>> :
	F extends z.ZodOptional<infer I extends z.ZodTypeAny> ? z.ZodOptional<InputField<I>> :
	F extends z.ZodNullable<infer I extends z.ZodTypeAny> ? z.ZodNullable<InputField<I>> :
	F extends z.ZodDefault<infer I extends z.ZodTypeAny> ? z.ZodOptional<InputField<I>> :
